import SaveManager from '../managers/SaveManager';
import { ASSET_PATHS, SPRITE_CONFIG } from '../config/AssetFrames';

export default class MainMenu extends Phaser.Scene {
    private menuItems: { text: Phaser.GameObjects.Text, action: () => void }[] = [];
    private currentSelectionIndex: number = 0;
    // Input handled via event listeners
    private selectorLeft!: Phaser.GameObjects.Image;
    private selectorRight!: Phaser.GameObjects.Image;

    constructor() {
        super('MainMenu');
    }

    preload() {
        this.load.image('menu_bg', '/assets/menu_bg.jpeg');
        this.load.image('spear', ASSET_PATHS.SPEAR);
        this.load.audio('dash', ASSET_PATHS.DASH);
        this.load.audio('theme', ASSET_PATHS.THEME);

        // Essential globally used assets
        this.load.spritesheet('tile_sheet', ASSET_PATHS.TILESET, SPRITE_CONFIG.TILESET);
        this.load.image('reel_fragment', ASSET_PATHS.JAISON); // Fallback if REEL not in paths, check config
        // Actually, AssetFrames has REEL: 'reel_fragment' but no path. 
        // Let's use the actual path if we can find it, or placeholder.
        // I'll check CreditsScene's create to see if it uses 'reel_fragment'
    }

    create() {
        // Reset menu items array to prevent stale references when scene restarts
        this.menuItems = [];
        this.currentSelectionIndex = 0;

        const width = this.scale.width;
        const height = this.scale.height;

        // --- BACKGROUND ---
        // Deep Cinematic Gradient
        const graphics = this.add.graphics();
        graphics.fillGradientStyle(0x050510, 0x050510, 0x101030, 0x101030, 1);
        graphics.fillRect(0, 0, width, height);

        // Ambience Spotlights
        this.createSpotlight(width * 0.2, height * 0.2, 0x4444ff);
        this.createSpotlight(width * 0.8, height * 0.8, 0xff4444);

        // --- PARTICLES (Glitch Dust) ---
        this.add.particles(0, 0, 'tile_sheet', {
            frame: 1,
            x: { min: 0, max: width },
            y: { min: 0, max: height },
            lifespan: { min: 2000, max: 5000 },
            speed: { min: 10, max: 40 },
            scale: { start: 0.1, end: 0 },
            alpha: { start: 0, end: 0.4 },
            tint: [0xffd700, 0x00ffff, 0xff00ff],
            blendMode: 'ADD',
            frequency: 100
        });

        // --- LOGO (Spinning Reel) ---
        // Using TILESET frame 1 (Save Zone) as a cinematic 'Reel' placeholder if reel_fragment png is missing
        const logo = this.add.sprite(width / 2 - 280, height * 0.16, 'tile_sheet', 1);
        logo.setScale(0.8).setTint(0xffd700);
        this.tweens.add({
            targets: logo,
            angle: 360,
            duration: 10000,
            repeat: -1
        });

        // --- TITLE ---
        const title = this.add.text(width / 2, height * 0.15, "MINNAL MURALI", {
            fontFamily: 'Cinzel',
            fontSize: '84px',
            color: '#ffffff',
            stroke: '#ffd700',
            strokeThickness: 2,
            shadow: { offsetX: 0, offsetY: 0, color: '#ffd700', blur: 20, stroke: true, fill: true }
        }).setOrigin(0.5);

        // Title Glitch Effect
        this.time.addEvent({
            delay: 3000,
            callback: () => {
                this.tweens.add({
                    targets: title,
                    scaleX: 1.1,
                    alpha: 0.8,
                    duration: 50,
                    yoyo: true,
                    repeat: 2,
                    onStart: () => title.setTint(0x00ffff),
                    onComplete: () => {
                        title.clearTint();
                        title.setAlpha(1);
                        title.setScale(1);
                    }
                });
            },
            loop: true
        });

        // Subtitle
        this.add.text(width / 2, height * 0.24, "THE CINEMA MULTIVERSE", {
            fontFamily: 'Cinzel',
            fontSize: '20px',
            color: '#00ffff',
            letterSpacing: 10
        }).setOrigin(0.5).setAlpha(0.6);

        // --- MENU ITEMS ---
        // Adjusted startY and gap to fit all items (including EXIT) within typical 600px height
        const startY = height * 0.38;
        const gap = 48;
        let currentY = startY;

        const save = SaveManager.load();
        if (save && save.currentLevel && save.currentLevel !== '') {
            this.addMenuItem(width / 2, currentY, "CONTINUE JOURNEY", () => {
                this.cameras.main.fadeOut(500, 0, 0, 0);
                this.cameras.main.once('camerafadeoutcomplete', () => {
                    this.scene.start(save.currentLevel, { state: save });
                });
            });
            currentY += gap;
        }

        this.addMenuItem(width / 2, currentY, "NEW REALITY", () => {
            if (window.confirm("Start a new game? Current progress will be lost.")) {
                SaveManager.clearSave();
                this.cameras.main.fadeOut(500, 0, 0, 0);
                this.cameras.main.once('camerafadeoutcomplete', () => {
                    this.scene.start('IntroScene');
                });
            }
        });
        currentY += gap;

        this.addMenuItem(width / 2, currentY, "AVATAR CUSTOMIZER", () => {
            this.cameras.main.fadeOut(300, 0, 0, 0);
            this.cameras.main.once('camerafadeoutcomplete', () => this.scene.start('AvatarEditor'));
        });
        currentY += gap;

        this.addMenuItem(width / 2, currentY, "STORE", () => {
            this.cameras.main.fadeOut(300, 0, 0, 0);
            this.cameras.main.once('camerafadeoutcomplete', () => this.scene.start('Store'));
        });
        currentY += gap;

        this.addMenuItem(width / 2, currentY, "LEVEL EDITOR", () => {
            this.cameras.main.fadeOut(300, 0, 0, 0);
            this.cameras.main.once('camerafadeoutcomplete', () => this.scene.start('EditorScene'));
        });
        currentY += gap;

        this.addMenuItem(width / 2, currentY, "OPTIONS", () => {
            this.cameras.main.fadeOut(300, 0, 0, 0);
            this.cameras.main.once('camerafadeoutcomplete', () => this.scene.start('Options'));
        });
        currentY += gap;

        this.addMenuItem(width / 2, currentY, "CREDITS", () => {
            this.cameras.main.fadeOut(500, 0, 0, 0);
            this.cameras.main.once('camerafadeoutcomplete', () => {
                this.scene.start('CreditsScene');
            });
        });
        currentY += gap;

        this.addMenuItem(width / 2, currentY, "EXIT", () => {
            if (window.confirm("Exit to multiverse?")) window.location.reload();
        });

        // --- SELECTORS ---
        this.selectorLeft = this.add.image(0, 0, 'spear').setScale(0.1).setAngle(90).setTint(0xffd700).setVisible(false);
        this.selectorRight = this.add.image(0, 0, 'spear').setScale(0.1).setAngle(-90).setTint(0xffd700).setVisible(false);

        // Input
        this.input.keyboard!.on('keydown-UP', () => this.navigate(-1));
        this.input.keyboard!.on('keydown-DOWN', () => this.navigate(1));
        this.input.keyboard!.on('keydown-ENTER', () => this.selectItem());
        this.input.keyboard!.on('keydown-SPACE', () => this.selectItem());

        this.updateSelection();

        // Music
        this.sound.stopAll();
        // Assuming we want a specific menu track, but using theme for now
        this.sound.play('theme', { volume: 0.5, loop: true });
    }

    private createSpotlight(x: number, y: number, color: number) {
        const light = this.add.circle(x, y, 300, color, 0.15);
        this.tweens.add({
            targets: light,
            alpha: 0.05,
            scale: 1.5,
            duration: 5000 + Math.random() * 2000,
            yoyo: true,
            repeat: -1,
            ease: 'Sine.easeInOut'
        });
    }

    private addMenuItem(x: number, y: number, text: string, action: () => void) {
        const item = this.add.text(x, y, text, {
            fontFamily: 'Cinzel',
            fontSize: '24px',
            color: '#aaaaaa'
        }).setOrigin(0.5).setInteractive({ useHandCursor: true });

        const index = this.menuItems.length;
        item.on('pointerover', () => {
            this.currentSelectionIndex = index;
            this.updateSelection();
        });
        item.on('pointerdown', () => action());

        this.menuItems.push({ text: item, action });
    }

    private navigate(direction: number) {
        this.currentSelectionIndex = Phaser.Math.Wrap(this.currentSelectionIndex + direction, 0, this.menuItems.length);
        this.updateSelection();
        this.sound.play('dash', { volume: 0.1, rate: 2 });
    }

    private selectItem() {
        const item = this.menuItems[this.currentSelectionIndex];
        if (item) {
            this.cameras.main.flash(500, 255, 255, 255);
            this.sound.play('dash', { volume: 0.5 });
            item.action();
        }
    }

    private updateSelection() {
        this.menuItems.forEach((item, index) => {
            const isSelected = index === this.currentSelectionIndex;
            item.text.setColor(isSelected ? '#ffffff' : '#888888');
            item.text.setScale(isSelected ? 1.2 : 1);

            if (isSelected) {
                this.selectorLeft.setPosition(item.text.x - item.text.width / 2 - 60, item.text.y).setVisible(true);
                this.selectorRight.setPosition(item.text.x + item.text.width / 2 + 60, item.text.y).setVisible(true);

                // Selector animation
                this.tweens.add({
                    targets: [this.selectorLeft, this.selectorRight],
                    alpha: { from: 0.5, to: 1 },
                    duration: 500,
                    yoyo: true,
                    repeat: -1
                });
            }
        });
    }
}
