import Phaser from 'phaser';
import BaseLevel from './BaseLevel';
import Enemy from '../entities/Enemy';
import SaveManager from '../managers/SaveManager';
import LevelLoader from '../utils/LevelLoader';
import { LEVEL3_DATA } from '../config/Level3Data';
import { SPRITE_KEYS, DEPTHS } from '../config';
import Dasan from '../entities/enemies/Dasan';
import TranslationManager from '../utils/TranslationManager';

export default class Level3 extends BaseLevel {
    private enemiesDefeated: number = 0;
    private survivalTime: number = 0;
    private totalSurvivalTime: number = 60; // 60 seconds default
    private enemyGroup!: Phaser.Physics.Arcade.Group;
    private objectiveText!: Phaser.GameObjects.Text;
    private hasShownIntro: boolean = false;

    // Rolling Defense specifics
    private roadBg!: Phaser.GameObjects.TileSprite;
    private spawnerTimers: Map<number, number> = new Map();
    private branches!: Phaser.Physics.Arcade.Group;

    constructor() {
        super('Level3', 'Level 3: Rolling Defense');
    }

    preload() {
        super.preload();
        LevelLoader.preloadCustomAssets(this, this.customData || LEVEL3_DATA);
        this.load.image(SPRITE_KEYS.LEVEL3_BG, '/assets/level3_background.png');
        this.load.image(SPRITE_KEYS.LEVEL3_BUS, '/assets/level3_bus_rooftop.png');
        this.load.image(SPRITE_KEYS.LEVEL3_TRUNK, '/assets/level3_trunk.png');
    }

    create() {
        super.create();

        const data = this.customData || LEVEL3_DATA;

        // 1. Setup Parallax Background (Road moving)
        const width = this.scale.width;
        const height = this.scale.height;

        // New Background
        this.roadBg = this.add.tileSprite(width / 2, height / 2, width, height, SPRITE_KEYS.LEVEL3_BG);
        this.roadBg.setDepth(-100).setScrollFactor(0);

        // Play background music
        LevelLoader.playAudio(this, data);

        // Spawn player — force position to ignore any saved world position
        this.player = this.createPlayer(
            data.playerSpawn.x,
            data.playerSpawn.y,
            data.playerSpawn.texture
        );
        this.player.setPosition(data.playerSpawn.x, data.playerSpawn.y);

        // Bus sprite (visual only) — sized to match the collision polygon walking area
        const busSprite = this.add.image(0, 0, SPRITE_KEYS.LEVEL3_BUS);
        busSprite.setOrigin(0, 0);
        busSprite.setDisplaySize(764, 1285);
        busSprite.setDepth(-50);

        // Setup bounds
        LevelLoader.setupBounds(this, data);

        // Check if level is already completed
        const isCompleted = SaveManager.isLevelCompleted('Level3');

        if (isCompleted) {
            this.openExitPath();
            this.hasShownIntro = true;
        } else {
            // Setup objectives
            this.setupObjectives();
            this.setupSpawners();
        }

        // Create exit zone logic (win condition triggers this)
        LevelLoader.createExitZones(this, data, () => this.handleExitTrigger());
    }

    private setupSpawners() {
        // Initial setup for spawners from data (if any)
    }

    private handleExitTrigger() {
        if (!SaveManager.isLevelCompleted('Level3')) return;
        this.scene.start('Level4');
    }

    private setupObjectives() {
        // Create enemy group
        this.enemyGroup = this.physics.add.group({
            classType: Enemy,
            runChildUpdate: true
        });

        // Initialize survival params
        const data = this.customData || LEVEL3_DATA;
        if (data.objectives?.survival) {
            this.totalSurvivalTime = data.objectives.survival.duration || 60;
        }

        if (!this.hasShownIntro && data.cutscenes?.intro) {
            LevelLoader.playIntroCutscene(this, data);
            this.hasShownIntro = true;
        }

        // Enemy Colliders
        this.physics.add.collider(this.player, this.enemyGroup);
        this.physics.add.collider(this.enemyGroup, this.enemyGroup);
        // Player combat
        this.player.setCombatTargets(this.enemyGroup);

        // Branch Section — roadside trunk obstacle (duck to survive)
        this.branches = this.physics.add.group();

        // Player hit by trunk
        this.physics.add.overlap(this.player, this.branches, (p, b) => {
            const player = p as any;
            const branch = b as Phaser.Physics.Arcade.Sprite;
            // Only isDucking flag is reliable — body height is 35 in both states
            if (!player.isDucking && branch.active) {
                player.takeDamage(1);
                branch.destroy();
                this.cameras.main.shake(150, 0.015);
            }
        });

        // Enemies hit by trunk (they never duck — always get swept off)
        this.physics.add.overlap(this.enemyGroup, this.branches, (e, b) => {
            const enemy = e as any;
            const branch = b as Phaser.Physics.Arcade.Sprite;
            if (branch.active && enemy.takeDamage) {
                enemy.takeDamage(2);
                branch.destroy();
                this.cameras.main.shake(100, 0.01);
            }
        });

        // Objective UI
        this.objectiveText = this.add.text(this.scale.width - 20, 55, '', {
            fontSize: '18px',
            color: '#ffff00',
            stroke: '#000000',
            strokeThickness: 3
        }).setOrigin(1, 0).setScrollFactor(0).setDepth(3000);

        this.updateObjectiveUI();
    }

    update(time: number, delta: number) {
        super.update(time, delta);

        if (this.isCutscenePlaying || SaveManager.isLevelCompleted('Level3')) return;

        // 1. Scroll Parallax
        if (this.roadBg) this.roadBg.tilePositionY -= 5 * (delta / 16); // Move down (bus moves up visually)
        // Removed treeBg scroll


        // 2. Manage Survival Timer
        const data = this.customData || LEVEL3_DATA;
        if (data.objectives?.survival?.duration) {
            this.survivalTime += delta / 1000;
            if (this.survivalTime >= this.totalSurvivalTime) {
                this.completeLevel();
            }
        }

        // 3. Spawners
        this.handleSpawners(time, delta);

        this.updateObjectiveUI();

        // Falling off bus check
        if (!this.physics.world.bounds.contains(this.player.x, this.player.y)) {
            // Fall damage respawn logic
            this.player.takeDamage(1);
            const data = this.customData || LEVEL3_DATA;
            this.player.setPosition(data.playerSpawn.x, data.playerSpawn.y);
            this.cameras.main.flash(200, 255, 0, 0);
        }
    }

    private handleSpawners(time: number, delta: number) {
        // Hardcoded example logic for "Generating" waves if data is empty
        // In fully data-driven, use LEVEL3_DATA.objects.enemySpawners

        // Spawn standard "Tribal" (Dasan) every 3 seconds from sides
        const SPAWN_INTERVAL = 3000;
        if (!this.spawnerTimers.has(1)) this.spawnerTimers.set(1, time);

        if (time - this.spawnerTimers.get(1)! > SPAWN_INTERVAL) {
            this.spawnerTimers.set(1, time);

            // Random side
            const side = Phaser.Math.RND.pick(['left', 'right']);
            const spawnData = this.customData || LEVEL3_DATA;
            const mapW = spawnData.map.width * spawnData.map.tileWidth * spawnData.map.tileScale;
            const mapH = spawnData.map.height * spawnData.map.tileHeight * spawnData.map.tileScale;
            const x = side === 'left' ? 0 : mapW;
            const y = Phaser.Math.Between(0, mapH); // Along length of bus

            // Spawn
            const enemy = new Dasan(this, x, y, this.player);
            // Customize for bus battle
            enemy.chaseSpeed = 80;
            this.enemyGroup.add(enemy);

            // Track kill when enemy is destroyed
            enemy.once('destroy', () => {
                this.enemiesDefeated++;
                this.spawnCoin(enemy.x, enemy.y);
                const d = this.customData || LEVEL3_DATA;
                if (d.objectives?.survival?.requiredKills &&
                    this.enemiesDefeated >= d.objectives.survival.requiredKills) {
                    this.completeLevel();
                }
                this.updateObjectiveUI();
            });

            // Add slight offset so they don't look like they pop in on top of wall
            if (side === 'left') enemy.x -= 32; else enemy.x += 32;
        }

        // Branch Spawner
        // Spawn a branch every 2-4 seconds
        const BRANCH_INTERVAL = 2500;
        if (!this.spawnerTimers.has(2)) this.spawnerTimers.set(2, time);

        if (time - this.spawnerTimers.get(2)! > BRANCH_INTERVAL) {
            this.spawnerTimers.set(2, time);
            this.spawnBranch();
        }

        // Update trunk (branch) positions — scroll down with the road
        if (this.branches) {
            this.branches.getChildren().forEach(b => {
                const branch = b as Phaser.Physics.Arcade.Sprite;
                branch.y += 5 * (delta / 16);
                // Despawn once below visible camera area
                if (branch.y > this.cameras.main.scrollY + this.scale.height + 200) {
                    branch.destroy();
                }
            });
        }
    }

    private spawnBranch() {
        if (!this.branches) return;

        // Spawn above the visible area so it enters naturally from the top
        const spawnY = this.cameras.main.scrollY - 150;

        // Always from left — left roadside tree trunk sweeping across the bus roof
        const branch = this.branches.create(0, spawnY, SPRITE_KEYS.LEVEL3_TRUNK) as Phaser.Physics.Arcade.Sprite;
        const scale = Phaser.Math.FloatBetween(0.55, 1.5);
        branch.setScale(scale);
        branch.setDepth(DEPTHS.PLAYER + 50); // Always render above player — looks like it passes overhead

        // Push the origin left so roughly half the trunk hangs off the bus edge (feels rooted to the tree)
        const halfW = branch.displayWidth / 3; // Use 1/3 of the image width to account for the trunk's shape (not a full rectangle)   
        branch.x = -halfW * 0.05; // ~5% of the image is off-screen left, 95% visible

        // Physics body: only the thick central trunk section — ignore leaf padding
        const body = branch.body as Phaser.Physics.Arcade.Body;
        body.setSize(branch.displayWidth * 0.85, branch.displayHeight * 0.28);
        body.reset(branch.x, spawnY);
    }

    private updateObjectiveUI() {
        if (!this.objectiveText) return;

        const data = this.customData || LEVEL3_DATA;
        if (data.objectives?.survival?.requiredKills) {
            const label = TranslationManager.translate("Defeat Enemies:");
            const req = data.objectives.survival.requiredKills;
            this.objectiveText.setText(`${label} ${this.enemiesDefeated}/${req}`);
        } else if (data.objectives?.survival?.duration) {
            const label = TranslationManager.translate("Survive:");
            const remaining = Math.max(0, this.totalSurvivalTime - this.survivalTime).toFixed(0);
            this.objectiveText.setText(`${label} ${remaining}s`);
        }
    }

    private completeLevel() {
        if (this.isCutscenePlaying || SaveManager.isLevelCompleted('Level3')) return;

        this.startCutscene();
        SaveManager.markLevelCompleted('Level3');
        SaveManager.unlockLevel('Level4');
        SaveManager.save({
            currentLevel: 'HubScene',
            playerHealth: this.player.health,
            money: this.player.money,
            lastSaveTime: Date.now()
        });
        this.endCutscene();
        this.showVictory("BUS ROOF SECURED!");
    }

    private openExitPath() {
        // Not used in survival mode, auto-transition
    }
}
