
import BaseLevel from './BaseLevel';
import { SPRITE_KEYS, AUDIO_KEYS, ASSET_PATHS } from '../config';
import SaveManager from '../managers/SaveManager';
import LevelLoader from '../utils/LevelLoader';
import { LEVEL_TEASHOP_DATA } from '../config/LevelTeaShopData';
import VisualEffectManager from '../utils/VisualEffectManager';

export default class TeaShopScene extends BaseLevel {
    private hasShopOpen: boolean = false;
    private burntCount: number = 0;
    private minigameCooldown: number = 0; // Timestamp when it ends

    constructor() {
        super('TeaShopScene', 'Damu\'s Tea Shop');
    }

    preload() {
        super.preload();
        // Load custom assets from data
        LevelLoader.preloadCustomAssets(this, this.customData || LEVEL_TEASHOP_DATA);

        // Ensure Tea Shop specific assets are loaded if not covered by customAssets
        // (If the editor exported them as custom assets, they are covered. If they are standard game assets, BaseLevel covers some, but let's be safe)
        this.load.image(SPRITE_KEYS.TEA_SHOP_FLOOR, ASSET_PATHS.TEA_SHOP_FLOOR);
        this.load.image(SPRITE_KEYS.TEA_SHOP_WALL, ASSET_PATHS.TEA_SHOP_WALL);
        this.load.image(SPRITE_KEYS.TEA_SHOP_COUNTER, ASSET_PATHS.TEA_SHOP_COUNTER);
        this.load.spritesheet(SPRITE_KEYS.POROTTA_1, ASSET_PATHS.POROTTA_1, { frameWidth: 256, frameHeight: 256 });
        this.load.spritesheet(SPRITE_KEYS.POROTTA_2, ASSET_PATHS.POROTTA_2, { frameWidth: 256, frameHeight: 256 });
        this.load.spritesheet(SPRITE_KEYS.POROTTA_3, ASSET_PATHS.POROTTA_3, { frameWidth: 256, frameHeight: 256 });
        this.load.spritesheet(SPRITE_KEYS.VINAYAKAN, ASSET_PATHS.VINAYAKAN, { frameWidth: 256, frameHeight: 256 });
    }

    create() {
        super.create();

        const data = this.customData || LEVEL_TEASHOP_DATA;

        // 1. Audio
        LevelLoader.playAudio(this, data);

        // 2. Background
        LevelLoader.renderBackground(this, data);

        // 3. Player
        // Use spawn from data, or default if missing
        const spawn = data.playerSpawn || { x: 400, y: 500, texture: 'jaison' };
        this.player = this.createPlayer(spawn.x, spawn.y, spawn.texture, spawn.scale);
        this.player.setCollideWorldBounds(true);

        // 5. Bounds & Collision Polygons
        LevelLoader.setupBounds(this, data);

        // 6. Spawn Objects (NPCs, Props, Exits, etc.)
        LevelLoader.spawnObjects(this, data);
        LevelLoader.createExitZones(this, data);
        LevelLoader.createUI(this, data);

        // 7. Attach Logic to Entities
        this.initializeSceneLogic();
    }

    private initializeSceneLogic() {
        let damu: any = null;
        let vinayakan: any = null;

        // Forcefully find them even if metadata was lost
        this.interactables.forEach((npc: any) => {
            const label = npc.label || '';
            const key = npc.customKey || npc.texture?.key || '';
            const dialog = npc.dialogText || '';

            if (label === 'Damu' || key === 'damu' || key === 'dasan' || dialog.includes('renovating')) {
                damu = npc;
            }
            if (label === 'Vinayakan' || key === 'vinayakan' || dialog.includes('kitchen')) {
                vinayakan = npc;
            }
        });

        if (damu) {
            // Prevent auto-depth sorting from hiding him behind the counter
            (damu as any).ignoreDepthSort = true;
            damu.setDepth(2000); 
            damu.setScale(1.0);
            damu.setOrigin(0.5, 1); // Grounded
            (damu as any).interactionRange = 400; // Large range so player can easily hit it

            // Override interact directly
            (damu as any).interact = async () => {
                if (this.isCutscenePlaying || this.hasShopOpen) return;
                this.openShopUI();
            };
            (damu as any).speak = (damu as any).interact;
        }

        if (vinayakan) {
            // Prevent auto-depth sorting from hiding him
            (vinayakan as any).ignoreDepthSort = true;
            vinayakan.setDepth(2000);
            vinayakan.setOrigin(0.5, 1);
            (vinayakan as any).interactionRange = 400;

            // Create Animations
            const anims = [
                { key: 'vinayakan_idle', texture: SPRITE_KEYS.VINAYAKAN, scale: 1.2 },
                { key: 'vinayakan_make_1', texture: SPRITE_KEYS.POROTTA_1, scale: 1.2 },
                { key: 'vinayakan_cry', texture: SPRITE_KEYS.POROTTA_2, scale: 1.2 },
                { key: 'vinayakan_make_2', texture: SPRITE_KEYS.POROTTA_3, scale: 1.2 },
            ];

            anims.forEach(anim => {
                if (!this.anims.exists(anim.key)) {
                    const frames = this.anims.generateFrameNumbers(anim.texture, {});
                    if (frames && frames.length > 0) {
                        this.anims.create({
                            key: anim.key,
                            frames: frames,
                            frameRate: anim.key === 'vinayakan_idle' ? 4 : 6,
                            repeat: -1
                        });
                    }
                }
            });

            // Helper to play and scale
            const playVinayakan = (key: string) => {
                const config = anims.find(a => a.key === key);
                if (config && this.anims.exists(key) && vinayakan && vinayakan.play) {
                    vinayakan.play(key);
                    vinayakan.setScale(config.scale);
                }
            };

            // Initial state (Porotta making by default)
            playVinayakan('vinayakan_make_1');

            // Random animation timer
            this.time.addEvent({
                delay: Phaser.Math.Between(5000, 10000),
                callback: () => {
                    if (vinayakan && vinayakan.anims && vinayakan.anims.currentAnim) {
                        if (vinayakan.anims.currentAnim.key !== 'vinayakan_cry') {
                            const keys = ['vinayakan_make_1', 'vinayakan_make_2', 'vinayakan_idle'];
                            const next = Phaser.Math.RND.pick(keys);
                            playVinayakan(next);
                        }
                    }
                },
                loop: true
            });

            // Override interact directly to bypass NPC default speak
            (vinayakan as any).interact = async () => {
                if (this.isCutscenePlaying) return;

                const state = SaveManager.load();
                if (state && !state.flags?.heardDemonetization) {
                    // Story Event: Demonetization News
                    this.startCutscene();
                    await this.showProfessionalDialogue("Jaison", "Vinayakan, the Screen is bleeding ink. The Multiverse is facing a 'System Stability' Demonetization!");
                    await this.showProfessionalDialogue("Vinayakan", "What? My black money! I invested all my illegal Porotta dough into 4K Pixels!");
                    await this.showProfessionalDialogue("Jaison", "The Director is recalling all 'High-Value' fragments to pay for the patch.");

                    playVinayakan('vinayakan_cry');
                    await this.showProfessionalDialogue("Vinayakan", "AYYO!!! My savings! My life's work! All those stolen frames of Pranchiyettan's rice!");

                    if (damu) {
                        await this.showProfessionalDialogue("Damu", "Don't worry Vinayaka. We will sell 'International Quality Kattan Chaya' to the developers.");
                        await this.showProfessionalDialogue("Vinayakan", "Will they pay in un-glitched pixels, Ayya?");
                    }

                    const flags = state.flags || {};
                    flags.heardDemonetization = true;
                    SaveManager.save({ flags });

                    this.time.delayedCall(1000, () => {
                        playVinayakan('vinayakan_make_1'); 
                        this.endCutscene();
                    });
                } else {
                    const now = Date.now();
                    if (now < this.minigameCooldown) {
                        const remaining = Math.ceil((this.minigameCooldown - now) / 60000);
                        this.startCutscene();
                        await this.showProfessionalDialogue("Vinayakan", "Mailvaasanam..! Go away! You burnt my precious porottas!");
                        await this.showProfessionalDialogue("Vinayakan", `Come back in ${remaining} minutes when you learn how to handle pixelated heat!`);
                        this.endCutscene();
                        return;
                    }

                    this.startCutscene();
                    this.showConfirmationDialogue("Asset Validation", "Help Vinayakan validate his 'stolen frames' into stable pixels and earn some un-demonetized currency.", () => {
                        this.startParottaMinigame(() => {
                            this.endCutscene();
                        });
                    }, () => {
                        this.endCutscene();
                    });
                }
            };
            (vinayakan as any).speak = (vinayakan as any).interact;
        }
    }

    update(time: number, delta: number) {
        super.update(time, delta);
        this.children.each((child: any) => {
            if (child.type === 'Sprite' || child.type === 'Image') {
                if (!child.ignoreDepthSort && child.depth > -50 && child.depth <= 1000) {
                    child.setDepth(child.y);
                }
            }
        });
    }



    // --- SHOP SYSTEM ---

    // --- SHOP SYSTEM ---

    private openShopUI() {
        if (this.hasShopOpen) return;
        this.hasShopOpen = true;
        this.startCutscene();

        const width = this.scale.width;
        const height = this.scale.height;
        const container = this.add.container(0, 0).setDepth(4000).setScrollFactor(0);

        // Dark Overlay
        const overlay = this.add.rectangle(width / 2, height / 2, width, height, 0x000000, 0.7);
        container.add(overlay);

        // Background
        const bg = this.add.rectangle(width / 2, height / 2, 640, 520, 0x111111, 0.95).setStrokeStyle(4, 0xaa8855);
        const title = this.add.text(width / 2, height / 2 - 220, "DAMU'S SUPPLIES", {
            fontSize: '36px',
            color: '#ffdd00',
            fontStyle: 'bold',
            stroke: '#000000',
            strokeThickness: 6
        }).setOrigin(0.5);

        container.add([bg, title]);

        const items = [
            { id: 'toddy', name: 'Toddy', price: 50, desc: 'Heals 50 HP (Consumable)', oneTime: false },
            { id: 'golden_spatula', name: 'Gilded Spatula', price: 150, desc: 'Easier cooking (Wider Zone)', oneTime: true, flag: 'hasGoldenSpatula' },
            { id: 'bus_ticket', name: 'Bus Ticket', price: 100, desc: 'Access to City (Level 4)', oneTime: true, flag: 'busTicket' }
        ];

        let selectedIndex = 0;
        const rows: Phaser.GameObjects.Container[] = [];

        const closeAction = () => {
            this.input.keyboard?.off('keydown-UP');
            this.input.keyboard?.off('keydown-DOWN');
            this.input.keyboard?.off('keydown-ENTER');
            this.input.keyboard?.off('keydown-SPACE');
            this.input.keyboard?.off('keydown-ESC');
            container.destroy();
            this.hasShopOpen = false;
            this.endCutscene();
        };

        const refreshUI = () => {
            rows.forEach(r => r.destroy());
            rows.length = 0;

            const state = SaveManager.load() || SaveManager.getInitialState();
            let y = height / 2 - 140;

            // Current Balance
            const balanceTxt = this.add.text(width / 2, y - 50, `YOUR BALANCE: ₹ ${this.player.money}`, {
                fontSize: '24px', color: '#00ff00', stroke: '#000000', strokeThickness: 2
            }).setOrigin(0.5);
            rows.push(balanceTxt as any);

            items.forEach((item, index) => {
                const isSelected = index === selectedIndex;
                const flags = state.flags || {};
                const isOwned = item.oneTime && (flags as any)[item.flag as string];

                const row = this.add.container(width / 2, y);
                const rowBg = this.add.rectangle(0, 0, 580, 80, isSelected ? 0x444444 : 0x222222)
                    .setStrokeStyle(2, isSelected ? 0xffff00 : 0x666666)
                    .setInteractive({ useHandCursor: true });

                const color = isOwned ? '#888888' : '#ffffff';
                const name = this.add.text(-270, -15, item.name, { fontSize: '24px', color: color, fontStyle: 'bold' }).setOrigin(0, 0.5);
                const desc = this.add.text(-270, 15, item.desc, { fontSize: '16px', color: '#aaaaaa' }).setOrigin(0, 0.5);
                const priceLabel = isOwned ? "ALREADY OWNED" : `₹ ${item.price}`;
                const price = this.add.text(270, 0, priceLabel, { fontSize: '24px', color: isOwned ? '#ff0000' : '#00ff00', fontStyle: 'bold' }).setOrigin(1, 0.5);

                row.add([rowBg, name, desc, price]);

                rowBg.on('pointerover', () => { selectedIndex = index; refreshUI(); });

                rowBg.on('pointerdown', () => {
                    if (!isOwned) {
                        this.handlePurchase(item);
                        refreshUI();
                    }
                });

                rows.push(row as any);
                container.add(row);
                y += 90;
            }); // This closing brace was missing, causing the inventory display to be inside the loop.

            // Comprehensive Inventory Display
            const invY = y + 20;
            const invTitle = this.add.text(width / 2, invY, "CURRENT CUSTODY", { fontSize: '20px', color: '#aaaaaa', fontStyle: 'bold' }).setOrigin(0.5);

            // Build inventory string
            const invList: string[] = [...state.inventory];
            
            // Add non-inventory state flags that were historically separate (like abilities or property)
            if (state.unlockedAbilities?.includes('speed_boots')) invList.push("Speed Boots");
            if (state.houseOwned) invList.push("Small Cottage");
            
            // Since we upgraded buying items like 'Bus Ticket' to use addItem(), we filter flags here
            // to avoid double listing them if they were already in state.inventory.
            // But for things DAMU sells (Toddy, etc.), we want to see the full list of what is in state.inventory!
            const invItems = invList.length > 0 ? invList.join(", ") : "Empty";

            // Brighten up the output so it's impossible to miss!
            const invText = this.add.text(width / 2, invY + 30, invItems, { fontSize: '18px', color: '#ffffff', fontStyle: 'bold', wordWrap: { width: 500 }, align: 'center' }).setOrigin(0.5);
            rows.push(invTitle as any, invText as any);
            container.add([invTitle, invText]);

            // Close Button
            const isCloseSelected = selectedIndex === items.length;
            const closeRow = this.add.container(width / 2, invY + 100);
            const closeBg = this.add.rectangle(0, 0, 300, 60, isCloseSelected ? 0x660000 : 0x330000)
                .setStrokeStyle(2, isCloseSelected ? 0xff0000 : 0x990000)
                .setInteractive({ useHandCursor: true });
            const closeText = this.add.text(0, 0, "CLOSE", { fontSize: '28px', color: '#ffffff', fontStyle: 'bold' }).setOrigin(0.5);
            closeRow.add([closeBg, closeText]);
            closeBg.on('pointerover', () => { selectedIndex = items.length; refreshUI(); });
            closeBg.on('pointerdown', closeAction);

            rows.push(closeRow as any);
            container.add(closeRow);
        };

        refreshUI();

        // Keyboard Controls
        this.input.keyboard?.on('keydown-UP', () => {
            selectedIndex = (selectedIndex - 1 + items.length + 1) % (items.length + 1);
            refreshUI();
        });
        this.input.keyboard?.on('keydown-DOWN', () => {
            selectedIndex = (selectedIndex + 1) % (items.length + 1);
            refreshUI();
        });
        const confirmPurchase = () => {
            if (selectedIndex < items.length) {
                const item = items[selectedIndex];
                const state = SaveManager.load() || SaveManager.getInitialState();
                const flags = state.flags || {};
                const isOwned = item.oneTime && (flags as any)[item.flag as string];
                if (!isOwned) {
                    this.handlePurchase(item);
                    refreshUI();
                }
            } else {
                closeAction();
            }
        };
        this.input.keyboard?.on('keydown-ENTER', confirmPurchase);
        this.input.keyboard?.on('keydown-SPACE', confirmPurchase);
        this.input.keyboard?.on('keydown-ESC', closeAction);
    }

    private handlePurchase(item: any) {
        if (this.player.money >= item.price) {
            // Collect all state changes BEFORE deducting money
            const state = SaveManager.load() || SaveManager.getInitialState();
            const flags = state.flags || {};

            if (item.id === 'toddy') {
                SaveManager.addItem('Toddy', true); // Allow multiples
            } else if (item.oneTime) {
                SaveManager.addItem(item.name, false); // Add unique named item (Gilded Spatula, etc.)
                if (item.flag) (flags as any)[item.flag] = true;
                
                if (item.id === 'bus_ticket') {
                    SaveManager.unlockLevel('Level4');
                }
            }

            // Deduct money from local object and update UI
            this.player.money -= item.price;
            this.updateMoneyUI(this.player.money);
            this.sound.play(AUDIO_KEYS.COIN_COLLECT);

            // Single atomic save for the remainder of states (ensuring items were already added safely!)
            SaveManager.save({
                money: this.player.money,
                flags: flags
            });

            VisualEffectManager.showOnomatopoeia(this, this.scale.width / 2, this.scale.height / 2, "BOUGHT!", "ui");
        } else {
            this.sound.play('tk_throw', { volume: 0.5 }); // Deny sound
            const msg = `NEED ₹${item.price} (You have ₹${this.player.money})`;
            VisualEffectManager.showOnomatopoeia(this, this.scale.width / 2, this.scale.height / 2, "NEED MONEY!", "ui");
            this.showProfessionalDialogue("Damu", msg);
        }
    }

    // --- MINIGAME V2 ---

    private startParottaMinigame(onComplete: () => void) {
        this.player.setMovementMode('cutscene');
        this.isCutscenePlaying = true;
        const cx = this.cameras.main.centerX;
        const cy = this.cameras.main.centerY;
        const container = this.add.container(0, 0).setDepth(2000).setScrollFactor(0);

        // Difficulty Check
        const state = SaveManager.load();
        const hasSpatula = state?.hasGoldenSpatula || false;
        const zoneSize = hasSpatula ? 80 : 50; // Wider zone if upgrade owned

        // Minigame UI
        const bg = this.add.rectangle(cx, cy, 400, 250, 0x222222, 0.95).setStrokeStyle(4, 0xFFD700);
        const title = this.add.text(cx, cy - 60, "VALIDATING ASSETS...", { fontSize: '24px', color: '#ffff00' }).setOrigin(0.5);

        // Order Text
        const orders = ["4K Pixel Frame", "HDR Rice Grain", "Ray-Traced Porotta"];
        const orderType = Phaser.Math.RND.pick(orders);
        const orderText = this.add.text(cx, cy - 20, `Asset: ${orderType}`, { fontSize: '18px', color: '#aaaaaa' }).setOrigin(0.5);

        // Bar
        const barBg = this.add.rectangle(cx, cy + 30, 300, 20, 0x000000).setStrokeStyle(2, 0x888888);
        const zoneX = cx - 150 + Phaser.Math.Between(50, 250);
        const successZone = this.add.rectangle(zoneX, cy + 30, zoneSize, 20, 0x00ff00);

        // Speed variation based on order
        let baseSpeed = 400;
        if (orderType === "Crispy Porotta") baseSpeed = 600;
        if (orderType === "Soft Porotta") baseSpeed = 300;

        const cursor = this.add.triangle(cx - 150, cy + 20, 0, 0, 10, 0, 5, 20, 0xff0000);

        container.add([bg, title, orderText, barBg, successZone, cursor]);

        let speed = baseSpeed; let dir = 1; let running = true;
        const update = (_t: number, d: number) => {
            if (!running) return;
            cursor.x += speed * (d / 1000) * dir;
            if (cursor.x > cx + 150) { cursor.x = cx + 150; dir = -1; }
            if (cursor.x < cx - 150) { cursor.x = cx - 150; dir = 1; }
        };
        this.events.on('update', update);

        const finish = () => {
            if (!running) return;
            running = false;
            this.events.off('update', update);
            this.input.keyboard?.removeKey('SPACE');

            // Check
            const halfZone = zoneSize / 2;
            if (cursor.x >= zoneX - halfZone && cursor.x <= zoneX + halfZone) {
                let reward = 10;
                if (orderType === "Crispy Porotta") reward = 20;
                if (orderType === "Soft Porotta") reward = 5;

                this.sound.play(AUDIO_KEYS.COIN_COLLECT || 'coin');
                title.setText(`PERFECT! +${reward}G`).setColor('#00ff00');
                this.player.money += reward;
                this.updateMoneyUI(this.player.money);
                SaveManager.save({ money: this.player.money });

                this.burntCount = 0; // Reset on success
            } else {
                title.setText("BURNT!").setColor('#ff0000');
                this.cameras.main.shake(100, 0.01);

                this.burntCount++;
                if (this.burntCount >= 3) {
                    this.minigameCooldown = Date.now() + 5 * 60 * 1000; // 5 minutes
                    this.burntCount = 0; // Reset after setting cooldown
                }
            }

            this.time.delayedCall(1000, () => {
                container.destroy();
                onComplete();
            });
        };
        this.input.keyboard?.addKey('SPACE').on('down', finish);
    }
}
