import Phaser from 'phaser';
import BaseLevel from './BaseLevel';
import SaveManager from '../managers/SaveManager';

export default class InteriorScene extends BaseLevel {
    private housePosition?: { x: number, y: number };
    private returnLevel?: string;

    constructor() {
        super('InteriorScene', 'Inside House');
    }

    init(data: any) {
        super.init(data as any);
        // Store house position for spawning player near it on exit
        if (data.houseX && data.houseY) {
            this.housePosition = { x: data.houseX, y: data.houseY };
        }
        this.returnLevel = data.returnLevel;
    }

    create() {
        super.create();

        // Small 10x10 Room
        this.map = this.make.tilemap({ tileWidth: 512, tileHeight: 512, width: 10, height: 10 });
        const tileset = this.map.addTilesetImage('tiles', 'tiles', 512, 512);

        if (tileset) {
            const layer = this.map.createBlankLayer('Ground', tileset)!;
            layer.fill(0); // Wood/Grass floor

            // Walls
            layer.fill(2, 0, 0, 10, 1);
            layer.fill(2, 0, 9, 10, 1);
            layer.fill(2, 0, 0, 1, 10);
            layer.fill(2, 9, 0, 1, 10);

            // Exit Door at bottom
            layer.putTileAt(0, 5, 9);
            layer.setCollision(2);
            layer.setScale(0.125);

            this.physics.world.setBounds(0, 0, 10 * 64, 10 * 64);
        }

        // Spawn Player at center
        this.player = this.createPlayer(5 * 64, 5 * 64, 'jaison');

        // Exit Logic
        const exitZone = this.add.zone(5 * 64, 9 * 64, 64, 64);
        this.physics.add.existing(exitZone, true);
        this.physics.add.overlap(this.player, exitZone, () => {
            // Go back to the level the player came from
            const save = SaveManager.load();
            const lastLevel = this.returnLevel || save?.currentLevel || 'Level2';

            // Spawn player near the house they exited from
            this.scene.start(lastLevel, {
                targetSpawn: this.housePosition
            });
        });

        // Some interior decoration (Crates, Pots)
        for (let i = 0; i < 3; i++) {
            const pot = this.physics.add.sprite(Phaser.Math.Between(2, 7) * 64, Phaser.Math.Between(2, 7) * 64, 'tile_sheet', 2);
            pot.setScale(0.125);
            pot.setImmovable(true);
            this.physics.add.collider(this.player, pot);
        }

        this.add.text(this.scale.width / 2, 50, "Home Sweet Home", {
            fontSize: '24px', color: '#ffffff'
        }).setOrigin(0.5).setScrollFactor(0);
    }
}
