export interface GameState {
    currentLevel: string;
    playerHealth: number;
    maxHealth: number;
    money: number;
    inventory: string[];
    unlockedAbilities: string[];
    lastSaveTime: number;
    posX?: number;
    posY?: number;
    houseOwned?: boolean;
    keyBindings?: {
        ACTION_PUNCH: string;
        ACTION_TK: string;
        ACTION_DASH: string;
        ACTION_SPELL: string;
        ACTION_RAGE: string;
        ACTION_JUMP: string;
        ACTION_INTERACT: string;
    };
    unlockedLevels: string[];
    completedLevels: string[];
    settings: {
        volume: number;
        uiLanguage: 'en' | 'ml';
        dialogueLanguage: 'en' | 'ml';
    };
    flags?: { [key: string]: any };
    avatar?: {
        hair: string;
        hat: string;
        shirt: string;
        pants?: string;
        shoes?: string;
        glasses?: string;
        mask?: string;
        hairColor?: number;
        skinColor?: number;
    };
    ownedAssets: string[];
    // Economy & Shop Flags
    hasGoldenSpatula?: boolean;
    hasRecipeBook?: boolean;
    busTicket?: boolean;
    stampLetter?: boolean;       // Official petition letter to enter Record Room
    reputation?: number;
    // Pranchi Investment
    pranchiInvestment?: number;
    pranchiInvestmentTime?: number;
}

const STORAGE_KEY = 'minnal_murali_save';

export default class SaveManager {
    static save(newState: Partial<GameState>) {
        try {
            const currentState = this.load() || this.getInitialState();
            const mergedState: GameState = {
                ...currentState,
                ...newState,
                lastSaveTime: Date.now()
            };
            const serialized = JSON.stringify(mergedState);
            localStorage.setItem(STORAGE_KEY, serialized);
        } catch (e) {
            console.error('Failed to save game:', e);
        }
    }

    static setFlag(key: string, value: any) {
        const state = this.load() || this.getInitialState();
        const flags = state.flags || {};
        flags[key] = value;
        this.save({ flags });
    }

    static getFlag(key: string, defaultValue: any = null): any {
        const state = this.load();
        if (!state || !state.flags) return defaultValue;
        return state.flags[key] ?? defaultValue;
    }

    static markLevelCompleted(levelKey: string) {
        const state = this.load() || this.getInitialState();
        if (!state.completedLevels.includes(levelKey)) {
            state.completedLevels.push(levelKey);
            this.save({ completedLevels: state.completedLevels });
        }
    }

    static unlockLevel(levelKey: string) {
        const state = this.load() || this.getInitialState();
        if (!state.unlockedLevels.includes(levelKey)) {
            state.unlockedLevels.push(levelKey);
            this.save({ unlockedLevels: state.unlockedLevels });
        }
    }

    static isLevelCompleted(levelKey: string): boolean {
        const state = this.load();
        return state ? state.completedLevels.includes(levelKey) : false;
    }

    static addItem(item: string, allowDuplicates: boolean = false) {
        const state = this.load() || this.getInitialState();
        if (allowDuplicates || !state.inventory.includes(item)) {
            state.inventory.push(item);
            this.save({ inventory: state.inventory });
        }
    }

    static hasItem(item: string): boolean {
        const state = this.load();
        return state ? state.inventory.includes(item) : false;
    }

    static load(): GameState | null {
        try {
            const serialized = localStorage.getItem(STORAGE_KEY);
            if (!serialized) return null;
            const state = JSON.parse(serialized) as GameState;

            // Migration: Add unlockedLevels if missing
            if (!state.unlockedLevels) {
                state.unlockedLevels = ['Level1'];
                // Infer based on currentLevel
                if (state.currentLevel === 'Level2') state.unlockedLevels.push('Level2');
                if (state.currentLevel === 'Level3') state.unlockedLevels.push('Level1', 'Level2', 'Level3');
                if (state.currentLevel === 'Level4') state.unlockedLevels.push('Level1', 'Level2', 'Level3', 'Level4');
            }

            if (!state.completedLevels) {
                state.completedLevels = [];
                // Infer if level is already passed
                if (state.unlockedLevels.includes('Level2')) state.completedLevels.push('Level1');
                if (state.unlockedLevels.includes('Level3')) state.completedLevels.push('Level2');
                if (state.unlockedLevels.includes('Level4')) state.completedLevels.push('Level3');
            }

            if (!state.flags) {
                state.flags = {};
            }

            if (!state.avatar) {
                state.avatar = {
                    hair: 'hair_base',
                    shirt: 'shirt_red',
                    pants: 'pants_plain',
                    shoes: 'shoes_default',
                    hat: 'hat_none',
                    glasses: 'glasses_none',
                    mask: 'mask_none',
                    hairColor: 0xffffff,
                    skinColor: 0xffffff
                };
            }

            if (!state.ownedAssets) {
                state.ownedAssets = ['hair_default', 'shirt_red', 'pants_plain', 'shoes_default'];
            }

            if (!state.inventory) {
                state.inventory = [];
            }

            // Migration: handle old language setting
            if (state.settings && (state.settings as any).language) {
                const oldLang = (state.settings as any).language;
                state.settings.uiLanguage = state.settings.uiLanguage || oldLang;
                state.settings.dialogueLanguage = state.settings.dialogueLanguage || oldLang;
                delete (state.settings as any).language;
            }

            return state;
        } catch (e) {
            console.error('Failed to load game:', e);
            return null;
        }
    }

    static clearSave() {
        localStorage.removeItem(STORAGE_KEY);
    }

    static getInitialState(): GameState {
        return {
            currentLevel: '',  // Empty means: no current level (fresh new game → go to Intro)
            playerHealth: 3,
            maxHealth: 3,
            money: 0,
            inventory: [],
            unlockedAbilities: [],
            unlockedLevels: ['Level1'],
            completedLevels: [],
            lastSaveTime: Date.now(),
            keyBindings: {
                ACTION_PUNCH: 'X',
                ACTION_TK: 'Z',
                ACTION_DASH: 'SPACE',
                ACTION_SPELL: 'R',
                ACTION_RAGE: 'M',
                ACTION_JUMP: 'B',
                ACTION_INTERACT: 'E'
            },
            settings: {
                volume: 0.5,
                uiLanguage: 'en',
                dialogueLanguage: 'en'
            },
            flags: {},
            avatar: {
                hair: 'hair_base',
                shirt: 'shirt_red',
                pants: 'pants_plain',
                shoes: 'shoes_default',
                hat: 'hat_none',
                glasses: 'glasses_none',
                mask: 'mask_none',
                hairColor: 0xffffff,
                skinColor: 0xffffff
            },
            ownedAssets: ['hair_default', 'shirt_red', 'pants_plain', 'shoes_default']
        };
    }
}
