import Phaser from 'phaser';

export type OnomatopoeiaType =
    | 'impact'   // POW, BAM
    | 'crit'     // CRIT!
    | 'miss'     // MISS
    | 'movement' // WHOOSH, BOING
    | 'damage'   // AYYOOO!
    | 'physics'  // THUD, WHACK
    | 'magic'    // ZAP, PEW PEW
    | 'meta'     // GLITCH, SCRIPT
    | 'special'  // BOSS THEME
    | 'ui';       // DING!

export default class VisualEffectManager {
    /**
     * Shows a manga-style floating text effect
     */
    static showOnomatopoeia(
        scene: Phaser.Scene,
        x: number,
        y: number,
        text: string,
        type: OnomatopoeiaType = 'impact'
    ) {
        let style = this.getStyle(type);

        const floatingText = scene.add.text(x, y, text, {
            fontSize: style.fontSize,
            fontFamily: 'Cinzel, monospace',
            color: style.color,
            stroke: style.stroke,
            strokeThickness: style.strokeThickness,
            fontStyle: 'bold italic'
        }).setOrigin(0.5).setDepth(2000);

        // Random rotation for that dynamic manga feel
        floatingText.setAngle(Phaser.Math.Between(-10, 10));

        // Pop Animation
        scene.tweens.add({
            targets: floatingText,
            scale: { start: 0.5, from: 0.5, to: 1.5 },
            y: y - 60,
            alpha: { from: 1, to: 0 },
            duration: 1600,
            ease: 'Back.out',
            onComplete: () => floatingText.destroy()
        });
    }

    /**
     * Flashes the camera with a color
     */
    static flashScreen(scene: Phaser.Scene, color: number = 0xffffff, duration: number = 200) {
        scene.cameras.main.flash(duration,
            (color >> 16) & 0xff,
            (color >> 8) & 0xff,
            color & 0xff
        );
    }

    private static getStyle(type: OnomatopoeiaType) {
        switch (type) {
            case 'impact':
                return { fontSize: '32px', color: '#ffcc00', stroke: '#ff0000', strokeThickness: 6 };
            case 'crit':
                return { fontSize: '40px', color: '#ffffff', stroke: '#00d4ff', strokeThickness: 8 };
            case 'miss':
                return { fontSize: '20px', color: '#888888', stroke: '#000000', strokeThickness: 4 };
            case 'movement':
                return { fontSize: '24px', color: '#00ffff', stroke: '#ffffff', strokeThickness: 4 };
            case 'damage':
                return { fontSize: '48px', color: '#ff00ff', stroke: '#ffffff', strokeThickness: 8 };
            case 'physics':
                return { fontSize: '28px', color: '#8B4513', stroke: '#ffffff', strokeThickness: 4 };
            case 'magic':
                return { fontSize: '30px', color: '#00ff88', stroke: '#000000', strokeThickness: 6 };
            case 'ui':
                return { fontSize: '26px', color: '#ffff00', stroke: '#000000', strokeThickness: 4 };
            case 'meta':
                return { fontSize: '36px', color: '#00ff00', stroke: '#ff00ff', strokeThickness: 10 };
            case 'special':
                return { fontSize: '42px', color: '#ff0000', stroke: '#ffff00', strokeThickness: 8 };
            default:
                return { fontSize: '24px', color: '#ffffff', stroke: '#000000', strokeThickness: 4 };
        }
    }
}
