
import Phaser from 'phaser';
import Enemy from '../Enemy';
import { SPRITE_KEYS, AUDIO_KEYS, ENEMY } from '../../config';

export default class Saajan extends Enemy {
    constructor(scene: Phaser.Scene, x: number, y: number, target: Phaser.Physics.Arcade.Sprite, texture: string = SPRITE_KEYS.SAAJAN, frame?: string | number) {
        super(scene, x, y, texture, target, 'BOSS');
        if (frame !== undefined) this.setFrame(frame);

        this.isBoss = true;
        this.chaseSpeed = ENEMY.CHASE_SPEED * 0.8;
        this.attackCooldown = 1500;
        this.health = 20;
        this.health = 20;
        this.maxHealth = 20;
        this.setScale(1.2); // Big guy (Scale override)

        // Ensure Physics are set correctly
        this.setCollideWorldBounds(true);
        this.setDrag(1000); // High drag to stop sliding
        this.setBounce(0.1);
        this.setPushable(true);
    }

    protected initAnimations() {
        const anims = this.scene.anims;
        const key = this.texture.key; // Use current texture key

        if (anims.exists(`${key}-walk-down`)) return;

        // Assuming standard 4-direction spritesheet layout based on Shibu/Character config
        // Frame width 64x64 or 256x256 depending on loader. Users said "all frames together" implies sheet.
        // We will stick to the Shibu/Standard layout if 64x64 was small, maybe 128 or 256?
        // User implied Shibu is the reference. Shibu uses standard frames.

        // Walk cycles
        anims.create({ key: `${key}-walk-down`, frames: anims.generateFrameNumbers(key, { start: 0, end: 2 }), frameRate: 8, repeat: -1 });
        anims.create({ key: `${key}-walk-up`, frames: anims.generateFrameNumbers(key, { start: 12, end: 15 }), frameRate: 8, repeat: -1 });
        anims.create({ key: `${key}-walk-right`, frames: anims.generateFrameNumbers(key, { start: 8, end: 11 }), frameRate: 8, repeat: -1 });
        anims.create({ key: `${key}-walk-left`, frames: anims.generateFrameNumbers(key, { start: 4, end: 7 }), frameRate: 8, repeat: -1 });

        // Attack (Basic punch/lathi)
        // anims.create({ key: `${key}-attack-down`, frames: anims.generateFrameNumbers(key, { start: 16, end: 19 }), frameRate: 12 });
        // anims.create({ key: `${key}-attack-right`, frames: anims.generateFrameNumbers(key, { start: 24, end: 27 }), frameRate: 12 });
        // anims.create({ key: `${key}-attack-left`, frames: anims.generateFrameNumbers(key, { start: 20, end: 23 }), frameRate: 12 });
        // anims.create({ key: `${key}-attack-up`, frames: anims.generateFrameNumbers(key, { start: 28, end: 31 }), frameRate: 12 });
    }

    protected handleAttack() {
        if (!this.scene || !this.target || this.isAttacking || this.isDashing) return;
        const now = this.scene.time.now;
        if (now - this.lastAttackTime < this.attackCooldown) return;

        const dist = Phaser.Math.Distance.Between(this.x, this.y, this.target.x, this.target.y);

        // Lathi Charge / Dash
        if (dist > 100 && dist < 300) {
            this.performDash();
            this.lastAttackTime = now;
            return;
        }

        // Close combat
        if (dist < 100) {
            this.performMeleeAttack();
            this.lastAttackTime = now;
        }
    }

    private performMeleeAttack() {
        this.isAttacking = true;
        this.setVelocity(0, 0);

        // Determine direction
        const angle = Phaser.Math.Angle.Between(this.x, this.y, this.target!.x, this.target!.y);
        const deg = Phaser.Math.RadToDeg(angle);
        let dir = 'down';
        if (deg > -45 && deg <= 45) dir = 'right';
        else if (deg > 45 && deg <= 135) dir = 'down';
        else if (deg > 135 || deg <= -135) dir = 'left';
        else dir = 'up';

        this.playAnim(`attack-${dir}`);

        // Hit logic
        this.scene.time.delayedCall(300, () => {
            if (this.active && this.target && Phaser.Math.Distance.Between(this.x, this.y, this.target.x, this.target.y) < 100) {
                if ((this.target as any).takeDamage) {
                    (this.target as any).takeDamage(1);
                }
                this.scene.sound.play(AUDIO_KEYS.PUNCH);
            }
        });

        this.scene.time.delayedCall(600, () => {
            this.isAttacking = false;
        });
    }

    public takeDamage(amount: number) {
        super.takeDamage(amount);
    }

    protected die() {
        if (!this.active) return;
        this.emit('dead');
        this.setVelocity(0, 0);
        if (this.body) this.body.enable = false;
        this.setTint(0x555555);
        // Do NOT destroy. Level2 handles cleanup.
    }
}
