import Phaser from 'phaser';
import BaseLevel from './BaseLevel';
import { SPRITE_KEYS, AUDIO_KEYS } from '../config';
import SaveManager from '../managers/SaveManager';

export default class IntroScene extends BaseLevel {
    private introBlackout!: Phaser.GameObjects.Rectangle;

    constructor() {
        super('IntroScene', 'PROLOGUE');
    }

    create() {
        super.create();

        const width = this.scale.width;
        const height = this.scale.height;

        // 1. Setup Background (Paddy Field Road)
        this.add.rectangle(0, 0, width, height, 0x228B22).setOrigin(0);
        this.add.rectangle(0, height * 0.7, width, height * 0.3, 0x8B4513).setOrigin(0); // Road

        // 2. Setup Characters
        this.createPlayer(200, height * 0.75, SPRITE_KEYS.PLAYER);
        this.player.setDepth(10);

        // Biji on Scooter (Using Nephew/Usha placeholder)
        const bijiContainer = this.add.container(400, height * 0.75);
        const scooter = this.add.rectangle(0, 30, 80, 40, 0xff0000).setOrigin(0.5);
        const biji = this.add.sprite(0, 0, SPRITE_KEYS.NEPHEW).setScale(0.5);
        biji.setTint(0xff99ff);
        bijiContainer.add([scooter, biji]);
        bijiContainer.setDepth(9);

        // 3. Cinematic Blackout Starts (Act 0: The Fracture)
        this.introBlackout = this.add.rectangle(0, 0, width, height, 0x000000).setOrigin(0).setDepth(2000);

        // 4. Start Narrative Sequence
        this.startSequence(bijiContainer);
    }

    /** Properly awaitable delay using Phaser's timer */
    private wait(ms: number): Promise<void> {
        return new Promise(resolve => this.time.delayedCall(ms, resolve));
    }

    private async startSequence(biji: Phaser.GameObjects.Container) {
        this.startCutscene();

        // --- PHASE 1: HEARTBEAT INTRO ---
        this.sound.play(AUDIO_KEYS.PUNCH, { volume: 0.8, rate: 0.2 });
        await this.wait(1000);
        this.sound.play(AUDIO_KEYS.PUNCH, { volume: 1.0, rate: 0.2 });
        await this.wait(1000);

        // Fade in from blackout
        this.tweens.add({
            targets: this.introBlackout,
            alpha: 0,
            duration: 2000,
            onComplete: () => this.introBlackout.destroy()
        });
        await this.wait(2200);

        // Scene: Jaison jogs alongside Biji's Scooter
        await this.showDialogue(biji.list[1] as any, "Too slow, Jaison! My grandmother walks faster.");
        await this.showDialogue(this.player, "I'm trying! Superhero cardio is hard.");
        await this.showDialogue(biji.list[1] as any, "Beat my scooter to that Banyan tree, and I'll give you a kiss.");
        await this.showDialogue(this.player, "A kiss? For real?");
        await this.showDialogue(biji.list[1] as any, "Catch me first!");

        // Characters move across the screen
        this.tweens.add({
            targets: [this.player, biji],
            x: '+=600',
            duration: 3000,
            ease: 'Linear'
        });
        await this.wait(3200);

        await this.showDialogue(this.player, "For the kiss... MINNAL MURALI!");

        // Jaison Sprints - Sonic Boom Effect
        this.tweens.add({
            targets: this.player,
            x: this.scale.width + 500,
            duration: 500,
            ease: 'Circ.easeIn',
            onUpdate: (tween) => {
                if (tween.progress > 0.8) {
                    this.cameras.main.shake(100, 0.05);
                }
            }
        });
        await this.wait(500);

        // Screen Crack / Sonic Boom
        this.cameras.main.flash(500, 255, 255, 255);
        this.sound.play(AUDIO_KEYS.EXPLOSION);
        const graphics = this.add.graphics().setDepth(1000).lineStyle(4, 0xffffff, 1);
        for (let i = 0; i < 10; i++) {
            graphics.moveTo(Math.random() * this.scale.width, Math.random() * this.scale.height);
            graphics.lineTo(Math.random() * this.scale.width, Math.random() * this.scale.height);
        }

        await this.wait(600);
        // Fade to Void
        this.cameras.main.fadeOut(1000, 0, 0, 0);
        await this.wait(1500);

        // Setup Void Scene
        this.children.removeAll();
        this.add.rectangle(0, 0, this.scale.width, this.scale.height, 0x000000).setOrigin(0);

        // Re-spawn Jaison in Void
        this.player = this.createPlayer(500, 400, SPRITE_KEYS.PLAYER);
        this.player.setAlpha(0);
        this.cameras.main.fadeIn(1000, 0, 0, 0);
        this.tweens.add({ targets: this.player, alpha: 1, duration: 2000 });

        // Zero-Gravity Float (The Fracture)
        this.tweens.add({
            targets: this.player,
            y: this.player.y - 20,
            duration: 2000,
            yoyo: true,
            repeat: -1,
            ease: 'Sine.easeInOut'
        });

        await this.wait(2500);

        await this.showDialogue(this.player, "Where... am I? The Fourth Wall is shattered... bleeding into the Cinema Multiverse!");

        // Josemon Fades In with Glitch Effect
        const josemon = this.physics.add.sprite(this.player.x + 200, this.player.y, SPRITE_KEYS.NEPHEW).setAlpha(0);
        this.tweens.add({ targets: josemon, alpha: 0.8, duration: 1000 });

        // Glitch flicker
        this.time.addEvent({
            delay: 100,
            callback: () => {
                if (josemon.active) {
                    josemon.setTint(Math.random() > 0.8 ? 0xccffff : 0xffffff);
                    josemon.setAlpha(0.6 + Math.random() * 0.4);
                }
            },
            loop: true
        });

        await this.wait(1000);

        await this.showDialogue(josemon, "Jaison! You've crossed the boundary. Shibu is using the glitch to rewrite the very film we inhabit!");
        await this.showDialogue(this.player, "Josemon... your resolution... it's breaking up.");
        await this.showDialogue(josemon, "Collect the Reel Fragments to fix the script. Go through the rift, before the Multiverse collapses!");

        // Save game state before entering hub so CONTINUE JOURNEY works
        SaveManager.save({ currentLevel: 'HubScene', playerHealth: 3, maxHealth: 3 });

        // Exit to Hub
        this.endCutscene();

        // Show portal with instructions
        const portalLabel = this.add.text(850, 360, "[ Enter the Rift ]", {
            fontSize: '16px', color: '#00ffff', stroke: '#000000', strokeThickness: 3
        }).setOrigin(0.5).setDepth(2000);
        this.tweens.add({ targets: portalLabel, alpha: 0, duration: 800, yoyo: true, repeat: -1 });

        const portal = this.createLevelLink(850, 400, 'HubScene', { x: 400, y: 400 }, '');

        // Glitch particles
        this.add.particles(portal.x, portal.y, 'tile_sheet', {
            frame: 1,
            speed: 100,
            scale: { start: 0.5, end: 0 },
            alpha: { start: 1, end: 0 },
            lifespan: 1000,
            frequency: 100
        });
    }
}
