import BaseLevel from './BaseLevel';
import { SPRITE_KEYS } from '../config';
import SaveManager from '../managers/SaveManager';
import LevelLoader from '../utils/LevelLoader';
import { HUB_DATA } from '../config/HubData'; // Assuming HubData exists or using a constant if it doesn't
import { LEVEL1_DATA } from '../config/Level1Data';
import { LEVEL2_DATA } from '../config/Level2Data';
import { LEVEL3_DATA } from '../config/Level3Data';
import { LEVEL4_DATA } from '../config/Level4Data';
import { LEVEL5_DATA } from '../config/Level5Data';


export default class HubScene extends BaseLevel {
    private portalObjects: (Phaser.GameObjects.GameObject | any)[] = [];

    constructor() {
        super('HubScene', 'GLITCHED VILLAGE (HUB)');
    }

    preload() {
        super.preload();
        // Preload assets from customData or fallback to HUB_DATA (needed for backgroundImage)
        LevelLoader.preloadCustomAssets(this, this.customData || HUB_DATA);
    }

    create() {
        super.create();

        const data = this.customData || HUB_DATA;
        if (data) {
            LevelLoader.renderBackground(this, data);
            this.player = this.createPlayer(data.playerSpawn.x, data.playerSpawn.y, data.playerSpawn.texture);
            // Force correct spawn position — prevent stale saved posX/posY from landing player on a portal
            if (!this.targetSpawn) {
                this.player.setPosition(data.playerSpawn.x, data.playerSpawn.y);
            }
            LevelLoader.setupBounds(this, data);
            LevelLoader.spawnObjects(this, data);
            LevelLoader.createExitZones(this, data, () => {});
            this.cameras.main.fadeIn(500, 0, 0, 0);

            // Save Hub as current level (clear stale position to avoid portal auto-trigger on next load)
            if (!this.customData) {
                const spawnX = this.targetSpawn?.x ?? data.playerSpawn.x;
                const spawnY = this.targetSpawn?.y ?? data.playerSpawn.y;
                SaveManager.save({ currentLevel: 'HubScene', posX: spawnX, posY: spawnY });
            }
            return;
        }

        const mapWidth = 40;

        const mapHeight = 30;
        const tileSize = 64;
        (this as any).mapWidth = mapWidth * tileSize;
        (this as any).mapHeight = mapHeight * tileSize;

        // Ground tiles
        for (let x = 0; x < mapWidth; x++) {
            for (let y = 0; y < mapHeight; y++) {
                this.add.image(x * tileSize, y * tileSize, 'tile_sheet', 0)
                    .setOrigin(0).setScale(0.125).setTint(0x444444);
            }
        }

        // Ambient fog
        this.add.rectangle(0, 0, mapWidth * tileSize, mapHeight * tileSize, 0x000022, 0.25)
            .setOrigin(0).setDepth(1);

        // Player spawn
        let spawnX = (mapWidth * tileSize) / 2;
        let spawnY = (mapHeight * tileSize) - 100;
        if (this.targetSpawn) {
            spawnX = this.targetSpawn.x;
            spawnY = this.targetSpawn.y;
        }
        this.createPlayer(spawnX, spawnY, SPRITE_KEYS.PLAYER);

        // World bounds
        this.physics.world.setBounds(0, 0, mapWidth * tileSize, mapHeight * tileSize);
        this.player.setCollideWorldBounds(true);
        this.cameras.main.setBounds(0, 0, mapWidth * tileSize, mapHeight * tileSize);

        SaveManager.save({ currentLevel: 'HubScene' });

        this.createHubNPCs();
        this.refreshPortals();

        this.cameras.main.fadeIn(500, 0, 0, 0);
    }

    private refreshPortals() {
        // Cleanup existing portals
        this.portalObjects.forEach(obj => {
            if (obj.destroy) obj.destroy();
        });
        this.portalObjects = [];

        this.createLevelPortals();
    }

    // ─────────────────────────────────────────────────────────────────────────
    // NPCs
    // ─────────────────────────────────────────────────────────────────────────
    private createHubNPCs() {
        const midX = (this as any).mapWidth / 2;
        const midY = (this as any).mapHeight / 2;

        // Shaji Pappan — lore guide
        const pappan = this.createNPC(midX + 200, midY, 'shaji_pappan', 'Shaji Pappan');
        pappan.setDialogue([
            "Eda Mone! Reality is tearing at the seams.",
            "Shibu's glitch has bankrupted our physics engine!",
            "Go find the Reel Fragments — use the portals!"
        ]);

        // Josemon — tutorial guide
        const josemon = this.createNPC(midX - 100, midY + 200, 'josemon', 'Josemon');
        josemon.setDialogue([
            "Walk into a glowing portal to enter a level.",
            "Orange portals need something from you first.",
            "Grey ones are locked until you clear the previous stage."
        ]);

        // Pranchiyettan
        const pranchi = this.createNPC(midX + 400, midY + 100, 'pranchiyettan', 'Pranchiyettan');
        (pranchi as any).speak = () => this.handlePranchiInteraction();

        // Biji
        const biji = this.createNPC(midX - 400, midY + 100, 'nephew', 'Biji');
        biji.setTint(0xff99ff);
        (biji as any).speak = () => this.handleBijiInteraction();

        // Dinesan — petition writer (prerequisite for Record Room)
        const dinesan = this.createNPC(midX + 200, midY + 300, 'dinesan', 'Thalathil Dinesan (Petition Writer)');
        this.add.text(midX + 200, midY + 240, '📋 Petition Writer', {
            fontSize: '12px', color: '#ffdd88', backgroundColor: '#000000cc',
            padding: { x: 5, y: 2 }
        }).setOrigin(0.5).setDepth(300);
        (dinesan as any).speak = () => this.handleDinesanInteraction();

        // Tea Shop entrance (Damu is now located exclusively inside)
        this.createTeaShop(midX - 100, midY - 350);
    }

    // ─────────────────────────────────────────────────────────────────────────
    // NPC Interaction Handlers
    // ─────────────────────────────────────────────────────────────────────────
    private hasBusTicket(): boolean {
        const s = SaveManager.load();
        return !!(s?.busTicket || s?.flags?.busTicket);
    }

    private hasStampLetter(): boolean {
        const s = SaveManager.load();
        return !!(s?.stampLetter || s?.flags?.stampLetter);
    }

    // Damu interaction handled in TeaShopScene now

    private async handleDinesanInteraction() {
        this.startCutscene();

        if (this.hasStampLetter()) {
            await this.showProfessionalDialogue("Dinesan", "Your application letter is stamped and ready. My wife says it's perfect. The Record Room duty officer will let you in!");
        } else {
            await this.showProfessionalDialogue("Dinesan", "I am Thalathil Dinesan, certified petition writer. I am watching everyone.");
            await this.showProfessionalDialogue("Dinesan", "You need an official application letter to request access to the Police Station Record Room.");
            await this.showProfessionalDialogue("Dinesan", "I charge 25 coins for the full service: stamp, notarization, and my personal calligraphy.");

            if (this.player.money >= 25) {
                const choice = await this.showChoiceDialogue(
                    "Get official application letter?\n(Cost: 25 coins)",
                    [
                        { text: '📋 Yes, write it (25 coins)', value: 'yes' },
                        { text: 'Come back later', value: 'no' }
                    ]
                );
                if (choice === 'yes') {
                    this.player.money -= 25;
                    SaveManager.save({ stampLetter: true, money: this.player.money });
                    SaveManager.setFlag('stampLetter', true); // For compatibility
                    this.updateMoneyUI(this.player.money);

                    // Dramatic signing animation
                    this.cameras.main.shake(300, 0.005);
                    await this.showProfessionalDialogue("Dinesan", "*STAMPS PAPER LOUDLY*");
                    await this.showProfessionalDialogue("Dinesan", "DONE! One official petition to Inspector-General, Muralipuram, requesting access to Evidence Room. With my rubber stamp seal!");
                    await this.showProfessionalDialogue("Jaison", "The Record Room portal should be open now. Thank you, Dinesan-etta!");

                    // Live refresh the portals!
                    this.refreshPortals();
                }
            } else {
                await this.showProfessionalDialogue("Dinesan", "You only have " + this.player.money + " coins. I need 25.");
                await this.showProfessionalDialogue("Dinesan", "Go inside the Tea Shop and help Vinayakan with the porotta work. He pays well!");
            }
        }

        this.endCutscene();
    }

    private async handleBijiInteraction() {
        this.startCutscene();
        await this.showProfessionalDialogue("Biji", "Jaison, stop staring. If you have guts, go to the Harbor.");
        this.endCutscene();
    }

    private async handlePranchiInteraction() {
        this.startCutscene();
        await this.showProfessionalDialogue("Pranchiyettan", "Jaison! The Bank of Muralipuram has declared my 'Golden Rice' frames as 'Unstable Assets'!");
        await this.showProfessionalDialogue("Pranchiyettan", "They want to liquidate my pixels! I am fighting for the very resolution I stand on!");
        await this.showProfessionalDialogue("Jaison", "Is it because of the Glitch, Pranchiettan?");
        await this.showProfessionalDialogue("Pranchiyettan", "No! It's because the developers ran out of VRAM!");
        this.endCutscene();
    }

    // ─────────────────────────────────────────────────────────────────────────
    // Tea Shop
    // ─────────────────────────────────────────────────────────────────────────
    private createTeaShop(x: number, y: number) {
        const doorY = y + 80;
        console.log(`[HubScene] Creating Tea Shop entrance at ${x}, ${doorY}`);

        // Seamless entrance trigger
        this.createLevelLink(x, doorY, 'TeaShopScene', { x: 1312, y: 1120 }, '');

        this.add.text(x, doorY - 30, "[ ENTER TEA SHOP ]", {
            fontSize: '12px', color: '#ffdd88', backgroundColor: '#000000', padding: { x: 4, y: 2 }
        }).setOrigin(0.5).setDepth(y + 200);

        // Sign above tea shop
        this.add.text(x, doorY - 55, "Damu's Chayakada", {
            fontSize: '14px', color: '#ffffff', fontStyle: 'bold',
            stroke: '#000000', strokeThickness: 2
        }).setOrigin(0.5).setDepth(y + 201);
    }

    // ─────────────────────────────────────────────────────────────────────────
    // Level Portals — Linear chain with prerequisite checks
    // ─────────────────────────────────────────────────────────────────────────
    private createLevelPortals() {
        const midX = (this as any).mapWidth / 2;
        const midY = (this as any).mapHeight / 2;

        // Load save once for all prerequisite checks (Removed unused state var)

        interface ChainEntry {
            scene: string;
            spawn: { x: number; y: number };
            x: number; y: number;
            label: string; sublabel: string; color: number;
            confirmBefore?: boolean;
            prerequisite?: {
                check: () => boolean;
                failLabel: string;    // Shown on portal badge
                failHint: string;     // Floating toast when player gets close
            };
        }

        const chain: ChainEntry[] = [
            {
                scene: 'Level1', spawn: LEVEL1_DATA.playerSpawn,
                x: midX + 500, y: midY - 200,
                label: 'The Harbor', sublabel: 'Find the Reel', color: 0x00ffaa,
            },
            {
                scene: 'Level2', spawn: LEVEL2_DATA.playerSpawn,
                x: midX - 500, y: midY,
                label: 'The Blockade', sublabel: 'Break Through', color: 0xff4444,
            },
            {
                scene: 'Level3', spawn: LEVEL3_DATA.playerSpawn,
                x: midX - 400, y: midY + 400,
                label: 'KSRTC Bus Roof', sublabel: 'Board the Bus', color: 0x4488ff,
                prerequisite: {
                    check: () => this.hasBusTicket(),
                    failLabel: '🎫 Need KSRTC Ticket',
                    failHint: 'Buy a ticket (100 coins) from Damu at the Tea Shop →\nNo coins? Help Vinayakan inside to earn!'
                }
            },
            {
                scene: 'RecordRoomScene', spawn: { x: 400, y: 800 },
                x: midX + 400, y: midY + 400,
                label: 'Record Room', sublabel: 'Find the Evidence', color: 0xffff00,
                prerequisite: {
                    check: () => this.hasStampLetter(),
                    failLabel: '📋 Need Application Letter',
                    failHint: 'Talk to Thalathil Dinesan (Petition Writer) →\n25 coins for the official stamp letter!'
                }
            },
            {
                scene: 'Level4', spawn: LEVEL4_DATA.playerSpawn,
                x: midX, y: midY - 500,
                label: 'Final Push', sublabel: 'Confront Shibu', color: 0xff6600,
            },
            {
                scene: 'Level5', spawn: LEVEL5_DATA.playerSpawn,
                x: midX + 300, y: midY - 500,
                label: 'FINAL BOSS', sublabel: "Shibu's Throne", color: 0xff0000
            },
        ];

        // Logic: A portal is Available (Active or Prerequisite) if:
        // 1. It is the very next Story Level (isReachable).
        // 2. OR it is a Side Quest whose condition is met (Parallel Questing).
        chain.forEach((entry, i) => {
            const isCompleted = SaveManager.isLevelCompleted(entry.scene);
            const isReachable = i === 0 || SaveManager.isLevelCompleted(chain[i - 1].scene);
            const hasPrereq = !!entry.prerequisite;
            const prereqMet = entry.prerequisite ? entry.prerequisite.check() : true;

            // A portal is "Active" if it's reachable and met, OR if it's any parallel quest that is met.
            const isActive = !isCompleted && ((isReachable && prereqMet) || (hasPrereq && prereqMet));

            // A portal is "Showing as Prerequisite" if it's reachable but Gated.
            const isPrerequisite = !isCompleted && isReachable && hasPrereq && !prereqMet;

            if (isCompleted) {
                this.createCompletedPortal(entry.x, entry.y, entry.label, entry.color);
            } else if (isActive) {
                this.createActivePortal(entry);
            } else if (isPrerequisite) {
                this.createPrerequisitePortal(
                    entry.x, entry.y,
                    entry.label,
                    entry.prerequisite!.failLabel,
                    entry.prerequisite!.failHint
                );
            } else {
                // Locked
                const prevLabel = i > 0 ? chain[i - 1].label : '';
                this.createLockedPortal(entry.x, entry.y, entry.label, prevLabel ? `Clear: ${prevLabel}` : '');
            }
        });
    }

    // ─────────────────────────────────────────────────────────────────────────
    // Portal Renderers
    // ─────────────────────────────────────────────────────────────────────────

    /** Active portal — can be entered */
    private createActivePortal(entry: {
        x: number; y: number; targetScene?: string; scene: string;
        targetSpawn?: { x: number; y: number }; spawn: { x: number; y: number };
        label: string; sublabel: string; color: number; confirmBefore?: boolean;
    }) {
        const { x, y, scene, spawn, label, sublabel, color, confirmBefore } = entry;

        const ring = this.add.circle(x, y, 48, color, 0.15).setDepth(4);
        this.tweens.add({ targets: ring, alpha: 0.45, scale: 1.15, duration: 1200, yoyo: true, repeat: -1, ease: 'Sine.easeInOut' });

        const inner = this.add.circle(x, y, 32, color, 0.7).setDepth(5);
        this.tweens.add({ targets: inner, alpha: 0.35, duration: 800, yoyo: true, repeat: -1 });

        const labelTxt = this.add.text(x, y - 60, label, {
            fontSize: '13px', color: '#ffffff', stroke: '#000000', strokeThickness: 3, fontStyle: 'bold'
        }).setOrigin(0.5).setDepth(6);

        const sublabelTxt = this.add.text(x, y - 42, sublabel, {
            fontSize: '10px', color: `#${color.toString(16).padStart(6, '0')}`,
            stroke: '#000000', strokeThickness: 2
        }).setOrigin(0.5).setDepth(6);

        const enterTxt = this.add.text(x, y + 42, '▷  ENTER', {
            fontSize: '11px', color: '#ffffff', stroke: '#000000', strokeThickness: 2
        }).setOrigin(0.5).setDepth(6);
        this.tweens.add({ targets: enterTxt, alpha: 0.25, duration: 600, yoyo: true, repeat: -1 });

        const zone = this.createLevelLink(x, y, scene, spawn, '', confirmBefore || false, 48, 48);
        this.portalObjects.push(ring, inner, labelTxt, sublabelTxt, enterTxt, zone);
    }

    /** Completed portal — greyed out, not clickable */
    private createCompletedPortal(x: number, y: number, label: string, color: number) {
        const ring1 = this.add.circle(x, y, 48, color, 0.07).setDepth(4);
        const ring2 = this.add.circle(x, y, 32, color, 0.18).setDepth(5);

        const labelTxt = this.add.text(x, y - 60, label, {
            fontSize: '13px', color: '#555555', stroke: '#000000', strokeThickness: 2, fontStyle: 'bold'
        }).setOrigin(0.5).setDepth(6);

        const clearTxt = this.add.text(x, y + 42, '✓  CLEARED', {
            fontSize: '12px', color: '#00cc66', stroke: '#000000', strokeThickness: 2, fontStyle: 'bold'
        }).setOrigin(0.5).setDepth(6);

        this.portalObjects.push(ring1, ring2, labelTxt, clearTxt);
    }

    /** Prerequisite portal — player is close enough in chain but missing an item */
    private createPrerequisitePortal(x: number, y: number, label: string, failLabel: string, hint: string) {
        // Orange pulsing ring
        const ring = this.add.circle(x, y, 48, 0xff8800, 0.2).setDepth(4);
        this.tweens.add({ targets: ring, alpha: 0.5, scale: 1.1, duration: 900, yoyo: true, repeat: -1 });

        const inner = this.add.circle(x, y, 32, 0xff4400, 0.35).setDepth(5);
        const icon = this.add.text(x, y, '⚠', { fontSize: '28px' }).setOrigin(0.5).setDepth(6);

        const labelTxt = this.add.text(x, y - 60, label, {
            fontSize: '13px', color: '#ffaa44', stroke: '#000000', strokeThickness: 3, fontStyle: 'bold'
        }).setOrigin(0.5).setDepth(6);

        const failTxt = this.add.text(x, y + 42, failLabel, {
            fontSize: '10px', color: '#ff8800', stroke: '#000000', strokeThickness: 2
        }).setOrigin(0.5).setDepth(6);

        this.portalObjects.push(ring, inner, icon, labelTxt, failTxt);

        // Proximity hint — fires when player walks near
        const zone = this.add.zone(x, y, 160, 160);
        this.physics.add.existing(zone, true);
        this.portalObjects.push(zone);

        let lastHintShown = -9999;
        this.physics.add.overlap(this.player, zone, () => {
            const now = this.time.now;
            if (now - lastHintShown < 6000) return;
            lastHintShown = now;

            const hintLines = hint.split('\n');
            const toastY = y - 100;

            hintLines.forEach((line, idx) => {
                const toast = this.add.text(x, toastY - idx * 22, line, {
                    fontSize: '12px', color: '#ffcc44',
                    backgroundColor: '#000000cc',
                    padding: { x: 8, y: 4 },
                    stroke: '#000000', strokeThickness: 1
                }).setOrigin(0.5).setDepth(600);

                this.tweens.add({
                    targets: toast,
                    y: toastY - idx * 22 - 30,
                    alpha: 0,
                    duration: 3000,
                    delay: 1000,
                    onComplete: () => toast.destroy()
                });
            });
        });
    }

    /** Locked portal — future level, not yet reachable */
    private createLockedPortal(x: number, y: number, label: string, requirement: string) {
        const ring = this.add.circle(x, y, 48, 0x333333, 0.3).setDepth(4);
        this.tweens.add({ targets: ring, alpha: 0.1, duration: 2500, yoyo: true, repeat: -1 });

        const inner = this.add.circle(x, y, 32, 0x222222, 0.45).setDepth(5);
        const lock = this.add.text(x, y, '🔒', { fontSize: '22px' }).setOrigin(0.5).setDepth(6);

        const labelTxt = this.add.text(x, y - 60, label, {
            fontSize: '13px', color: '#444444', stroke: '#000000', strokeThickness: 2, fontStyle: 'bold'
        }).setOrigin(0.5).setDepth(6);

        this.portalObjects.push(ring, inner, lock, labelTxt);

        if (requirement) {
            const reqTxt = this.add.text(x, y + 42, requirement, {
                fontSize: '10px', color: '#3a3a3a', stroke: '#000000', strokeThickness: 2
            }).setOrigin(0.5).setDepth(6);
            this.portalObjects.push(reqTxt);
        }
    }
}
