
import Phaser from 'phaser';
import Enemy from '../Enemy';
import { SPRITE_KEYS } from '../../config';

export default class PachalamBhasi extends Enemy {
    private throwCooldown: number = 2000;
    private lastThrowTime: number = 0;

    constructor(scene: Phaser.Scene, x: number, y: number, target: Phaser.Physics.Arcade.Sprite, texture: string = SPRITE_KEYS.DINESAN, frame?: string | number) {
        super(scene, x, y, texture, target); // Default type
        if (frame !== undefined) this.setFrame(frame);

        this.chaseSpeed = 180; // Fast runner
        this.health = 8;
        this.maxHealth = 8;
        this.setScale(0.8);

        // Physics
        this.setCollideWorldBounds(true);
        this.setBounce(0.5);
    }

    protected handleAttack() {
        if (!this.scene || !this.target || this.isAttacking || !this.active) return;

        const dist = Phaser.Math.Distance.Between(this.x, this.y, this.target.x, this.target.y);

        // Run away if too close (Skirmisher behavior)
        if (dist < 150) {
            const angle = Phaser.Math.Angle.Between(this.target.x, this.target.y, this.x, this.y); // Away from player
            this.setVelocity(Math.cos(angle) * this.chaseSpeed, Math.sin(angle) * this.chaseSpeed);
            return;
        }

        // Throw Script
        const now = this.scene.time.now;
        if (dist < 400 && now - this.lastThrowTime > this.throwCooldown) {
            this.throwScript();
            this.lastThrowTime = now;
        } else {
            // Circle or idle? Just standard chase (slowly) or strafe
            this.moveTowardsTarget();
        }
    }

    private moveTowardsTarget() {
        if (!this.target) return;
        this.scene.physics.moveToObject(this, this.target, this.chaseSpeed);
    }

    private throwScript() {
        this.isAttacking = true;
        this.setVelocity(0, 0);

        // Visual Tell
        const bubble = this.scene.add.text(this.x, this.y - 40, "Script!", { fontSize: '12px', backgroundColor: '#fff', color: '#000' }).setOrigin(0.5);
        this.scene.time.delayedCall(500, () => bubble.destroy());

        this.scene.time.delayedCall(500, () => {
            if (!this.active) return;

            // Create Projectile
            const script = this.scene.physics.add.sprite(this.x, this.y, SPRITE_KEYS.SCRIPT_PROJECTILE);
            script.setScale(0.2);
            this.scene.physics.moveToObject(script, this.target!, 300);

            // Logic for hitting player needs to be handled in Scene or via overlap here if we reference player
            this.scene.physics.add.overlap(script, this.target!, () => {
                if ((this.target as any).takeDamage) (this.target as any).takeDamage(1);
                script.destroy();
            });

            // Cleanup after 2s
            this.scene.time.delayedCall(2000, () => { if (script.active) script.destroy(); });

            this.isAttacking = false;
        });
    }
}
