import SaveManager from '../managers/SaveManager';
import TranslationManager from '../utils/TranslationManager';

export default class Options extends Phaser.Scene {
    private volumeText!: Phaser.GameObjects.Text;
    private currentVolume: number = 50;

    constructor() {
        super('Options');
    }

    create() {
        const width = this.scale.width;
        const height = this.scale.height;

        const save = SaveManager.load() || SaveManager.getInitialState();
        this.currentVolume = Math.round((save.settings?.volume || 0.5) * 100);

        this.add.rectangle(0, 0, width, height, 0x1a1a2e).setOrigin(0);

        this.add.text(width / 2, 50, TranslationManager.translate("OPTIONS"), {
            fontFamily: 'Cinzel',
            fontSize: '48px',
            color: '#FFD700',
            stroke: '#000000',
            strokeThickness: 6
        }).setOrigin(0.5);

        // --- VOLUME CONTROL ---
        this.add.text(width / 2, 110, TranslationManager.translate("VOLUME"), {
            fontFamily: 'Cinzel',
            fontSize: '24px',
            color: '#ffffff'
        }).setOrigin(0.5);

        // Slider Track
        const trackWidth = 360;
        this.add.rectangle(width / 2, 140, trackWidth, 8, 0x333333).setOrigin(0.5);

        // Volume Fill
        const fill = this.add.rectangle(width / 2 - trackWidth / 2, 140, 0, 8, 0xFFD700).setOrigin(0, 0.5);

        // Knob
        const knob = this.add.circle(width / 2, 140, 12, 0xffffff).setInteractive({ draggable: true });

        this.volumeText = this.add.text(width / 2, 165, `${this.currentVolume}%`, {
            fontSize: '20px',
            color: '#FFD700'
        }).setOrigin(0.5);

        const updateVolumeUI = (vol: number) => {
            const pct = vol / 100;
            fill.width = trackWidth * pct;
            knob.x = (width / 2 - trackWidth / 2) + (trackWidth * pct);
            this.volumeText.setText(`${vol}%`);
            this.sound.volume = pct;
        };

        // Initialize UI
        updateVolumeUI(this.currentVolume);

        knob.on('drag', (_pointer: any, dragX: number) => {
            let x = Phaser.Math.Clamp(dragX, width / 2 - trackWidth / 2, width / 2 + trackWidth / 2);
            knob.x = x;

            const pct = (x - (width / 2 - trackWidth / 2)) / trackWidth;
            this.currentVolume = Math.round(pct * 100);
            updateVolumeUI(this.currentVolume);
        });

        knob.on('dragend', () => {
            SaveManager.save({ settings: { ...save.settings, volume: this.currentVolume / 100 } });
        });

        // --- UI LANGUAGE ---
        const uiLang = save.settings?.uiLanguage || 'en';
        this.add.text(width / 2, 205, TranslationManager.translate("UI LANGUAGE"), {
            fontFamily: 'Cinzel',
            fontSize: '22px',
            color: '#FFD700'
        }).setOrigin(0.5);

        const createUILangBtn = (x: number, y: number, label: string, code: 'en' | 'ml') => {
            const isActive = uiLang === code;
            const btn = this.add.text(x, y, label, {
                fontSize: '18px',
                color: isActive ? '#00ff00' : '#ffffff'
            }).setOrigin(0.5).setInteractive({ useHandCursor: true });

            btn.on('pointerdown', () => {
                if (uiLang === code) return;
                SaveManager.save({ settings: { ...save.settings, uiLanguage: code } });
                this.scene.restart();
            });
            return btn;
        };

        createUILangBtn(width / 2 - 80, 235, "ENGLISH", 'en');
        createUILangBtn(width / 2 + 80, 235, "MALAYALAM", 'ml');

        // --- DIALOGUE LANGUAGE ---
        const diagLang = save.settings?.dialogueLanguage || 'en';
        this.add.text(width / 2, 275, TranslationManager.translate("DIALOGUE LANGUAGE"), {
            fontFamily: 'Cinzel',
            fontSize: '22px',
            color: '#FFD700'
        }).setOrigin(0.5);

        const createDiagLangBtn = (x: number, y: number, label: string, code: 'en' | 'ml') => {
            const isActive = diagLang === code;
            const btn = this.add.text(x, y, label, {
                fontSize: '18px',
                color: isActive ? '#00ff00' : '#ffffff'
            }).setOrigin(0.5).setInteractive({ useHandCursor: true });

            btn.on('pointerdown', () => {
                if (diagLang === code) return;
                SaveManager.save({ settings: { ...save.settings, dialogueLanguage: code } });
                this.scene.restart();
            });
            return btn;
        };

        createDiagLangBtn(width / 2 - 80, 305, "ENGLISH", 'en');
        createDiagLangBtn(width / 2 + 80, 305, "MALAYALAM", 'ml');

        // --- CONTROLS REBINDING ---
        const controlsBox = this.add.container(width / 2, 460);
        const cbBg = this.add.rectangle(0, 20, 500, 240, 0x0f3460, 0.5).setStrokeStyle(2, 0x16213e);
        const cbTitle = this.add.text(0, -115, TranslationManager.translate("REBIND CONTROLS (Click to change)"), {
            fontFamily: 'Cinzel', fontSize: '20px', color: '#aaaaaa'
        }).setOrigin(0.5);

        const bindings = save.keyBindings || {
            ACTION_PUNCH: 'X',
            ACTION_TK: 'Z',
            ACTION_DASH: 'SPACE',
            ACTION_SPELL: 'R',
            ACTION_RAGE: 'M',
            ACTION_JUMP: 'B',
            ACTION_INTERACT: 'E'
        };

        const keys = [
            { id: 'ACTION_PUNCH', label: 'Punch' },
            { id: 'ACTION_TK', label: 'Telekinesis' },
            { id: 'ACTION_DASH', label: 'Dash' },
            { id: 'ACTION_SPELL', label: 'Psychic Burst' },
            { id: 'ACTION_RAGE', label: 'Mundu Madakkal' },
            { id: 'ACTION_JUMP', label: 'Jump' },
            { id: 'ACTION_INTERACT', label: 'Interact' }
        ];

        let startY = -90;
        keys.forEach(k => {
            const keyName = (bindings as any)[k.id] || 'NONE';
            const row = this.add.text(0, startY, `${k.label}: ${keyName}`, { fontSize: '16px', color: '#ffffff' }).setOrigin(0.5).setInteractive({ useHandCursor: true });

            row.on('pointerdown', () => {
                row.setText(`${k.label}: [ Press a Key ]`).setColor('#ffff00');

                // One-time listener for next key press
                const onKeyDown = (event: KeyboardEvent) => {
                    const newKey = event.key.toUpperCase() === ' ' ? 'SPACE' : event.key.toUpperCase();
                    (bindings as any)[k.id] = newKey;
                    row.setText(`${k.label}: ${newKey}`).setColor('#ffffff');

                    // Save updated bindings
                    SaveManager.save({ keyBindings: bindings });

                    // Cleanup
                    this.input.keyboard!.off('keydown', onKeyDown);
                };

                this.input.keyboard!.on('keydown', onKeyDown);
            });

            controlsBox.add(row);
            startY += 28;
        });

        controlsBox.add([cbBg, cbTitle]);

        const backBtn = this.add.text(width / 2, height - 40, TranslationManager.translate("BACK"), {
            fontFamily: 'Cinzel',
            fontSize: '28px',
            color: '#FFD700'
        }).setOrigin(0.5).setInteractive({ useHandCursor: true });

        backBtn.on('pointerover', () => backBtn.setScale(1.1).setColor('#ffffff'));
        backBtn.on('pointerout', () => backBtn.setScale(1).setColor('#FFD700'));

        backBtn.on('pointerdown', () => {
            this.scene.start('MainMenu');
        });

        this.input.keyboard!.on('keydown-ESC', () => {
            this.scene.start('MainMenu');
        });
    }
}
