
import Phaser from 'phaser';
import { ENEMY, COLORS, AUDIO_KEYS, SPRITE_KEYS } from '../config';
import VisualEffectManager from '../utils/VisualEffectManager';

export type EnemyAttackType = 'THROWER' | 'DASHER' | 'CIRCLE' | 'PULLER' | 'BOSS';

export default class Enemy extends Phaser.Physics.Arcade.Sprite {
    protected target: Phaser.Physics.Arcade.Sprite | null = null;
    public chaseSpeed: number = ENEMY.CHASE_SPEED;
    public attackCooldown: number = ENEMY.ATTACK_COOLDOWN;
    public isBoss: boolean = false;
    protected attackRange: number = ENEMY.ATTACK_RANGE;
    protected attackType: EnemyAttackType = 'THROWER';

    public debrisGroup: Phaser.Physics.Arcade.Group;
    public isHeld: boolean = false;
    protected lastDirection: string = 'down';
    protected isDashing: boolean = false;
    protected isAttacking: boolean = false;
    protected lastAttackTime: number = 0;

    public health: number = ENEMY.BASIC_HEALTH;
    public maxHealth: number = ENEMY.BASIC_MAX_HEALTH;
    private healthBar!: Phaser.GameObjects.Graphics;

    constructor(scene: Phaser.Scene, x: number, y: number, texture: string, target: Phaser.Physics.Arcade.Sprite, attackType: EnemyAttackType = 'THROWER') {
        super(scene, x, y, texture);

        scene.add.existing(this);
        scene.physics.add.existing(this);

        this.target = target;
        this.attackType = attackType;
        this.setCollideWorldBounds(true);
        this.setScale(0.5);

        // Adjust body to fit through 64px tile gaps (0.5 scale * 120 = 60px)
        this.body!.setSize(120, 120);
        this.body!.setOffset(68, 68);

        // Enemy Physics
        this.setPushable(true);
        this.setDrag(ENEMY.DRAG);
        this.setMass(ENEMY.MASS);

        this.debrisGroup = scene.physics.add.group();
        this.initAnimations();
    }

    update() {
        if (!this.scene || !this.target || this.isHeld || this.isDashing || this.isAttacking) return;

        if ((this.scene as any).isCutscenePlaying) {
            this.setVelocity(0, 0);
            this.playAnim('walk-down', true);
            return;
        }

        const dist = Phaser.Math.Distance.Between(this.x, this.y, this.target.x, this.target.y);

        if (dist < ENEMY.AGGRO_RANGE) {
            if (dist > ENEMY.MIN_DISTANCE) {
                this.scene.physics.moveToObject(this, this.target, this.chaseSpeed);

                // Update direction for animations
                const angle = Phaser.Math.Angle.Between(this.x, this.y, this.target.x, this.target.y);
                const deg = Phaser.Math.RadToDeg(angle);

                if (deg > -45 && deg <= 45) this.lastDirection = 'right';
                else if (deg > 45 && deg <= 135) this.lastDirection = 'down';
                else if (deg > 135 || deg <= -135) this.lastDirection = 'left';
                else this.lastDirection = 'up';

                this.playAnim(`walk-${this.lastDirection}`, true);
            } else {
                this.setVelocity(0, 0);
                this.playAnim(`walk-${this.lastDirection}`, true);
            }
        } else {
            this.setVelocity(0, 0);
            this.playAnim('walk-down', true);
        }

        // Handle Attacks
        this.handleAttack();
    }

    protected initAnimations() {
        const anims = this.scene.anims;
        const key = this.texture.key;

        // Automatically create basic walk animations for any character sheet if they don't exist
        // This ensures hitboxes and visuals work for non-standard enemy textures
        const frameCount = this.texture.frameTotal;

        if (!anims.exists(`${key}-walk-down`)) {
            // Check if we have enough frames for the standard ranges, otherwise fallback to frame 0
            const getFrames = (start: number, end: number): Phaser.Types.Animations.GenerateFrameNumbers => {
                const maxFrame = frameCount - 1;
                if (start > maxFrame) return { frames: [0] };
                return { start, end: Math.min(end, maxFrame) };
            };

            anims.create({ key: `${key}-walk-down`, frames: anims.generateFrameNumbers(key, getFrames(1, 4)), frameRate: 10, repeat: -1 });
            anims.create({ key: `${key}-walk-up`, frames: anims.generateFrameNumbers(key, getFrames(5, 6)), frameRate: 10, repeat: -1 });
            anims.create({ key: `${key}-walk-right`, frames: anims.generateFrameNumbers(key, getFrames(9, 12)), frameRate: 10, repeat: -1 });
            anims.create({ key: `${key}-walk-left`, frames: anims.generateFrameNumbers(key, getFrames(14, 17)), frameRate: 10, repeat: -1 });
        }
    }

    protected playAnim(keySuffix: string, ignoreIfPlaying: boolean = true) {
        let baseKey = this.texture.key;
        if (baseKey === SPRITE_KEYS.DASAN_MIRROR) baseKey = SPRITE_KEYS.DASAN;

        const key = `${baseKey}-${keySuffix}`;
        if (!this.scene.anims.exists(key)) return;

        const anim = this.scene.anims.get(key);
        if (!anim || !anim.frames || anim.frames.length === 0) return;

        const frame = anim.frames[0].frame;
        if (frame) {
            const textureKey = frame.texture.key;
            if (this.texture.key !== textureKey) {
                this.setTexture(textureKey);
            }
        }

        // Standard flip logic
        if (keySuffix.includes('left')) this.setFlipX(true);
        else if (keySuffix.includes('right')) this.setFlipX(false);

        this.anims.play(key, ignoreIfPlaying);
    }

    protected handleAttack() {
        if (!this.scene || !this.target || this.isAttacking || this.isDashing) return;
        const now = this.scene.time.now;
        if (now - this.lastAttackTime < this.attackCooldown) return;
        const dist = Phaser.Math.Distance.Between(this.x, this.y, this.target.x, this.target.y);

        if (this.attackType === 'DASHER' && dist < 300) {
            this.performDash();
            this.lastAttackTime = now;
            return;
        }

        if (dist > this.attackRange * 1.5) return;

        this.lastAttackTime = now;
        this.executeAttackLogic();
    }

    protected executeAttackLogic() {
        if (!this.scene || !this.target) return;
        switch (this.attackType) {
            case 'CIRCLE': this.throwCircleDebris(); break;
            case 'PULLER': this.performPull(); break;
            case 'BOSS': this.throwBossDebris(); break;
            case 'THROWER': this.throwDebris(1); break;
        }
    }

    protected performDash() {
        if (!this.target) return;
        this.isDashing = true;
        this.lastDirection = this.target.x < this.x ? 'left' : 'right';
        const side = this.lastDirection;

        this.playAnim(`walk-${side}`);
        this.setTint(0xffaa00);
        this.scene.physics.moveToObject(this, this.target, 600);
        this.scene.time.delayedCall(600, () => {
            if (!this.active) return;
            this.isDashing = false;
            this.clearTint();
            this.setVelocity(0);
        });
    }

    protected performPull() {
        if (!this.target) return;
        VisualEffectManager.showOnomatopoeia(this.scene, this.x, this.y, 'PULL!', 'special' as any);
        this.scene.sound.play(AUDIO_KEYS.TK_GRAB, { volume: 0.3, rate: 1.5 });
        const angle = Phaser.Math.Angle.Between(this.target.x, this.target.y, this.x, this.y);
        this.target.body!.velocity.x += Math.cos(angle) * 400;
        this.target.body!.velocity.y += Math.sin(angle) * 400;
        const line = this.scene.add.graphics();
        this.scene.tweens.add({
            targets: line, alpha: 0, duration: 300,
            onUpdate: () => {
                if (!this.active || !this.target || !this.target.active) { line.destroy(); return; }
                line.clear().lineStyle(2, 0x00ffff, line.alpha).lineBetween(this.x, this.y, this.target.x, this.target.y);
            },
            onComplete: () => line.destroy()
        });
    }

    protected throwCircleDebris() {
        for (let i = 0; i < 8; i++) {
            this.spawnAndLaunchDebris((i / 8) * Math.PI * 2, 400);
        }
    }

    protected throwBossDebris() {
        const throwCount = (this.health < this.maxHealth / 2) ? 3 : 1;
        const baseAngle = Phaser.Math.Angle.Between(this.x, this.y, this.target!.x, this.target!.y);
        for (let i = 0; i < throwCount; i++) {
            const angle = baseAngle + (i - (throwCount - 1) / 2) * 0.3;
            this.spawnAndLaunchDebris(angle, ENEMY.DEBRIS_SPEED, 400 + (i * 100));
        }
    }

    protected throwDebris(count: number) {
        const baseAngle = Phaser.Math.Angle.Between(this.x, this.y, this.target!.x, this.target!.y);
        for (let i = 0; i < count; i++) {
            this.spawnAndLaunchDebris(baseAngle, ENEMY.DEBRIS_SPEED);
        }
    }

    protected spawnAndLaunchDebris(angle: number, speed: number, delay: number = 400) {
        const spawnX = this.x + Math.cos(angle) * 80;
        const spawnY = this.y + Math.sin(angle) * 80;
        const debris = this.scene.physics.add.sprite(spawnX, spawnY, 'tile_sheet', 2);
        debris.setScale(0.125);
        this.debrisGroup.add(debris);
        debris.setCollideWorldBounds(true).setBounce(0.5).setDrag(100);
        this.scene.tweens.add({
            targets: debris, angle: 360, duration: delay,
            onComplete: () => {
                if (this.scene && this.target && debris.active && debris.body) {
                    debris.setVelocity(Math.cos(angle) * speed, Math.sin(angle) * speed);
                }
            }
        });
    }

    protected updateHealthBar() {
        if (!this.active) { if (this.healthBar) this.healthBar.destroy(); return; }
        if (!this.healthBar) this.healthBar = this.scene.add.graphics().setDepth(100);
        this.healthBar.clear();
        const w = 50, h = 5, x = this.x - w / 2, y = this.y + 35;
        this.healthBar.fillStyle(0x000000, 0.7).fillRect(x, y, w, h);
        const pct = Phaser.Math.Clamp(this.health / this.maxHealth, 0, 1);
        this.healthBar.fillStyle(COLORS.HEALTH_FILL, 1).fillRect(x + 1, y + 1, (w - 2) * pct, h - 2);
    }

    preUpdate(time: number, delta: number) {
        super.preUpdate(time, delta);
        this.updateHealthBar();
    }

    public takeDamage(amount: number) {
        if (!this.scene) return;
        this.health -= amount;
        this.updateHealthBar();
        this.setTint(COLORS.DAMAGE_FLASH);
        this.scene.time.delayedCall(100, () => { if (this.scene && this.active) this.clearTint(); });

        const angle = Phaser.Math.Angle.Between(this.target?.x || 0, this.target?.y || 0, this.x, this.y);
        const vec = this.scene.physics.velocityFromRotation(angle, ENEMY.KNOCKBACK_VELOCITY);
        this.setVelocity(vec.x, vec.y);

        this.scene.sound.play(AUDIO_KEYS.PUNCH, { volume: 0.4 });
        VisualEffectManager.showOnomatopoeia(this.scene, this.x, this.y, Phaser.Math.RND.pick(['WHACK!', 'THWACK!']), 'physics');

        if (this.health <= 0) {
            this.die();
        }
    }

    protected die() {
        this.scene.sound.play(AUDIO_KEYS.EXPLOSION, { volume: 0.5 });
        VisualEffectManager.showOnomatopoeia(this.scene, this.x, this.y, 'KO!', 'crit');

        // Reward player with coins
        const baseLevel = this.scene as any;
        if (baseLevel && baseLevel.player) {
            const reward = this.isBoss ? 50 : 25;
            baseLevel.player.money += reward;
            if (baseLevel.updateMoneyUI) baseLevel.updateMoneyUI(baseLevel.player.money);

            // Floating text for reward
            const txt = this.scene.add.text(this.x, this.y - 20, `+₹${reward}`, {
                fontSize: '20px', color: '#FFD700', stroke: '#000000', strokeThickness: 3
            }).setOrigin(0.5);
            this.scene.tweens.add({ targets: txt, y: this.y - 60, alpha: 0, duration: 1000, onComplete: () => txt.destroy() });
        }

        this.destroy(); // Will handle healthbar cleanup
    }

    public setHeld(state: boolean) {
        this.isHeld = state;
        if (state) { this.setVelocity(0, 0); this.setAlpha(0.8); }
        else { this.setAlpha(1); }
    }

    destroy(fromScene?: boolean) {
        if (this.healthBar) this.healthBar.destroy();
        super.destroy(fromScene);
    }
}
