import SaveManager from '../managers/SaveManager';
import TranslationManager from '../utils/TranslationManager';

export default class LevelSelect extends Phaser.Scene {
    private menuItems: { text: Phaser.GameObjects.Text, scene: string }[] = [];
    private currentSelectionIndex: number = 0;
    private selector!: Phaser.GameObjects.Text;

    constructor() {
        super('LevelSelect');
    }

    create() {
        const width = this.scale.width;
        const height = this.scale.height;

        // Background
        this.add.rectangle(0, 0, width, height, 0x000000).setOrigin(0);

        // Particles
        this.add.particles(0, 0, 'tile_sheet', {
            frame: 1,
            x: { min: 0, max: width },
            y: { min: 0, max: height },
            lifespan: 4000,
            speedY: { min: -10, max: -20 },
            scale: { start: 0.02, end: 0 },
            alpha: { start: 0.3, end: 0 },
            quantity: 1,
            tint: 0xaaccff
        });

        this.add.text(width / 2, 80, TranslationManager.translate("LEVEL SELECT"), {
            fontFamily: 'Cinzel',
            fontSize: '48px',
            color: '#ffffff'
        }).setOrigin(0.5);

        const save = SaveManager.load() || SaveManager.getInitialState();
        const unlocked = save.unlockedLevels || ['Level1'];

        const levels = [
            { name: "LEVEL 1: THE BEGINNING", key: "Level1" },
            { name: "LEVEL 2: THE VILLAGE", key: "Level2" },
            { name: "LEVEL 3: THE AMBUSH", key: "Level3" },
            { name: "FINAL BATTLE: SHIBU", key: "Level4" }
        ];

        let startY = 200;
        const gap = 60;

        levels.forEach((lvl) => {
            const isUnlocked = unlocked.includes(lvl.key);
            const color = isUnlocked ? '#ffffff' : '#555555';
            const displayText = isUnlocked ? TranslationManager.translate(lvl.name) : TranslationManager.translate("??? LOCKED ???");

            const item = this.add.text(width / 2, startY, displayText, {
                fontSize: '28px',
                color: color,
                fontFamily: 'Cinzel'
            }).setOrigin(0.5);

            if (isUnlocked) {
                this.menuItems.push({ text: item, scene: lvl.key });
            }
            startY += gap;
        });

        // Back button
        const backBtn = this.add.text(width / 2, height - 80, TranslationManager.translate("BACK TO MENU"), {
            fontSize: '24px',
            color: '#aaaaaa'
        }).setOrigin(0.5);
        this.menuItems.push({ text: backBtn, scene: 'MainMenu' });

        this.selector = this.add.text(0, 0, "> ", { fontSize: '32px', color: '#ffff00' }).setOrigin(0.5);
        this.updateSelection();

        // Input
        this.input.keyboard?.on('keydown-UP', () => {
            this.currentSelectionIndex = (this.currentSelectionIndex - 1 + this.menuItems.length) % this.menuItems.length;
            this.updateSelection();
            this.sound.play('dash', { volume: 0.2, rate: 2 });
        });

        this.input.keyboard?.on('keydown-DOWN', () => {
            this.currentSelectionIndex = (this.currentSelectionIndex + 1) % this.menuItems.length;
            this.updateSelection();
            this.sound.play('dash', { volume: 0.2, rate: 2 });
        });

        this.input.keyboard?.on('keydown-ENTER', () => this.confirmSelection());
        this.input.keyboard?.on('keydown-SPACE', () => this.confirmSelection());
        this.input.keyboard?.on('keydown-ESC', () => this.scene.start('MainMenu'));
    }

    private updateSelection() {
        this.menuItems.forEach((item, index) => {
            if (index === this.currentSelectionIndex) {
                item.text.setColor('#ffff00');
                this.selector.setPosition(item.text.x - (item.text.width / 2) - 30, item.text.y);
            } else {
                item.text.setColor(item.scene === 'MainMenu' ? '#aaaaaa' : '#ffffff');
            }
        });
    }

    private confirmSelection() {
        const selection = this.menuItems[this.currentSelectionIndex];
        const save = SaveManager.load() || SaveManager.getInitialState();

        if (selection.scene === 'MainMenu') {
            this.scene.start('MainMenu');
        } else {
            // Start the selected level with existing save state
            this.scene.start(selection.scene, { state: save });
        }
    }
}
