import Phaser from 'phaser';
import { AUDIO_KEYS, ASSET_PATHS, SPRITE_CONFIG } from '../config';

export default class CreditsScene extends Phaser.Scene {
    constructor() {
        super('CreditsScene');
    }

    preload() {
        this.load.audio(AUDIO_KEYS.UYIRE, ASSET_PATHS.UYIRE);
        this.load.audio(AUDIO_KEYS.LEVEL_WON, ASSET_PATHS.LEVEL_WON);

        // Ensure essential textures are loaded
        if (!this.textures.exists('tile_sheet')) {
            this.load.spritesheet('tile_sheet', ASSET_PATHS.TILESET, SPRITE_CONFIG.TILESET);
        }
    }

    create() {
        this.cameras.main.fadeIn(1000, 0, 0, 0);

        // Start 'Uyire' thematic music if not already playing
        if (!this.sound.get(AUDIO_KEYS.UYIRE)) {
            this.sound.play(AUDIO_KEYS.UYIRE, { volume: 0.6, loop: true });
        }

        const width = this.scale.width;
        const height = this.scale.height;

        // Background
        this.add.rectangle(0, 0, width, height, 0x000000).setOrigin(0);

        // --- GOLDEN REEL ANIMATION ---
        const reelContainer = this.add.container(width / 2, height / 2);

        // 1. Particle Emitter (The 'Aura')
        const particles = this.add.particles(0, 0, 'tile_sheet', {
            frame: 1, // Dust/Glitch frame
            speed: { min: 100, max: 200 },
            scale: { start: 0.5, end: 0 },
            alpha: { start: 0.6, end: 0 },
            rotate: { min: 0, max: 360 },
            lifespan: 2000,
            blendMode: 'ADD',
            tint: [0xffd700, 0xffaa00, 0xffffff]
        });
        reelContainer.add(particles);

        // 2. The Golden Reel Sprite
        const goldenReel = this.add.sprite(0, 0, 'tile_sheet', 1);
        goldenReel.setScale(1.5); // Adjust scale for tile_sheet frame
        goldenReel.setTint(0xffd700);
        reelContainer.add(goldenReel);

        // 3. Animation: Rotation & Pulse
        this.tweens.add({
            targets: goldenReel,
            angle: 360,
            duration: 5000,
            repeat: -1
        });

        this.tweens.add({
            targets: goldenReel,
            scale: 4.5,
            duration: 2000,
            yoyo: true,
            repeat: -1,
            ease: 'Sine.easeInOut'
        });

        // 4. Glow Flash (Meta Climax)
        this.time.delayedCall(1000, () => {
            this.cameras.main.flash(2000, 255, 215, 0, false);
            this.sound.play(AUDIO_KEYS.LEVEL_WON, { volume: 0.5 });
        });

        // Fade out reel when text reaches center? No, let it stay as a backdrop.
        reelContainer.setAlpha(0.3); // Fade it back to allow text to be readable

        // Titles
        const titleStyle = { fontSize: '40px', color: '#ffcc00', fontStyle: 'bold', fontFamily: 'Cinzel' };
        const textStyle = { fontSize: '24px', color: '#ffffff', fontFamily: 'monospace' };
        const roleStyle = { fontSize: '20px', color: '#aaaaaa', fontFamily: 'monospace' };

        // Content
        const content = [
            { type: 'title', text: 'MINNAL MURALI: THE GAME' },
            { type: 'spacer', height: 50 },

            { type: 'role', text: 'Based on the Movie' },
            { type: 'text', text: 'MINNAL MURALI' },
            { type: 'spacer', height: 40 },

            { type: 'role', text: 'Developed By' },
            { type: 'text', text: 'AKHIB & ANTIGRAVITY' },
            { type: 'spacer', height: 40 },

            { type: 'title', text: 'CAST' },
            { type: 'spacer', height: 30 },

            { type: 'role', text: 'JAISON (Minnal Murali)' },
            { type: 'text', text: 'Tovino Thomas' },
            { type: 'spacer', height: 20 },

            { type: 'role', text: 'BIJI (The Fierce)' },
            { type: 'text', text: 'Femina George' },
            { type: 'spacer', height: 20 },

            { type: 'role', text: 'SHIBU (The God of the Loop)' },
            { type: 'text', text: 'Guru Somasundaram' },
            { type: 'spacer', height: 20 },

            { type: 'role', text: 'DASHAMOOLAM DAMU' },
            { type: 'text', text: 'Suraj Venjaramoodu' },
            { type: 'spacer', height: 20 },

            { type: 'role', text: 'PRANCHIYETTAN' },
            { type: 'text', text: 'Mammootty (Voice/Spirit)' },
            { type: 'spacer', height: 20 },

            { type: 'role', text: 'S.I. SAAJAN' },
            { type: 'text', text: 'Baiju Santhosh' },
            { type: 'spacer', height: 50 },

            { type: 'title', text: 'THE GOLDEN REEL' },
            { type: 'text', text: 'Reality Restored.' },
            { type: 'spacer', height: 50 },

            { type: 'text', text: 'THANK YOU FOR PLAYING!' },
            { type: 'spacer', height: 100 },
        ];

        // Container for scrolling
        const container = this.add.container(width / 2, height + 100);

        let currentY = 0;
        content.forEach(item => {
            if (item.type === 'title') {
                const text = this.add.text(0, currentY, item.text!, titleStyle).setOrigin(0.5);
                container.add(text);
                currentY += 60;
            } else if (item.type === 'text') {
                const text = this.add.text(0, currentY, item.text!, textStyle).setOrigin(0.5);
                container.add(text);
                currentY += 40;
            } else if (item.type === 'role') {
                const text = this.add.text(0, currentY, item.text!, roleStyle).setOrigin(0.5);
                container.add(text);
                currentY += 30;
            } else if (item.type === 'spacer') {
                currentY += (item.height || 20);
            }
        });

        // Scroll Animation
        this.tweens.add({
            targets: container,
            y: -currentY, // Scroll until everything is off screen top
            duration: 20000, // 20 seconds
            ease: 'Linear',
            onComplete: () => {
                this.returnToMenu();
            }
        });

        // Skip logic
        this.add.text(width - 20, height - 20, "Press SPACE to Skip", { fontSize: '14px', color: '#555555' }).setOrigin(1);
        this.input.keyboard?.once('keydown-SPACE', () => {
            this.returnToMenu();
        });
    }

    private returnToMenu() {
        this.cameras.main.fadeOut(1000, 0, 0, 0);
        this.cameras.main.once('camerafadeoutcomplete', () => {
            this.sound.stopAll(); // Stop music here
            this.scene.start('MainMenu');
        });
    }
}
