import Phaser from 'phaser';

export default class ExtractionScene extends Phaser.Scene {
    private mainImage?: Phaser.GameObjects.Image;
    private selectionRect?: Phaser.GameObjects.Rectangle;
    private startPoint?: Phaser.Math.Vector2;
    private isSelecting: boolean = false;

    // Polygon
    private selectionMode: 'rect' | 'polygon' = 'rect';
    private polygonPoints: Phaser.Math.Vector2[] = [];
    private polygonGraphics?: Phaser.GameObjects.Graphics;
    private tempLine?: Phaser.GameObjects.Line;

    // UI
    private extractionList: string[] = [];
    private tooltipBg?: Phaser.GameObjects.Rectangle;
    private tooltipText?: Phaser.GameObjects.Text;


    // Scrollable extracted items
    private extractedItemsContainer?: Phaser.GameObjects.Container;
    private extractedItemsScrollOffset: number = 0;
    private maxVisibleItems: number = 8;
    private modeButtons: { [key: string]: Phaser.GameObjects.Rectangle } = {};

    private extractionMode: 'full' | 'smart' | 'grid' = 'full';
    private autoExtractGridSize: number = 64;

    constructor() {
        super('ExtractionScene');
    }

    init(data?: { mode?: 'full' | 'smart' | 'grid' }) {
        this.extractionMode = data?.mode || 'full';
    }

    create() {
        // Dark background - Photoshop style
        this.add.rectangle(0, 0, this.scale.width, this.scale.height, 0x2b2b2b).setOrigin(0).setScrollFactor(0);

        // Check if texture exists
        if (this.textures.exists('imported_sheet')) {
            // Reset main image to 0,0 for easier math, then center/fit
            this.mainImage = this.add.image(0, 0, 'imported_sheet').setOrigin(0);
            this.fitImageToScreen();
            this.mainImage.setInteractive();
        } else {
            this.add.text(this.scale.width / 2, this.scale.height / 2, 'No Image Loaded', { color: '#ff0000', fontSize: '24px' }).setOrigin(0.5);
        }

        this.setupGraphics();
        this.setupUI();
        this.setupControls();

        // Auto-run extraction based on mode
        if (this.extractionMode === 'smart') {
            this.time.delayedCall(500, () => this.smartExtractObjects());
        } else if (this.extractionMode === 'grid') {
            this.time.delayedCall(500, () => this.autoExtractSprites());
        }
    }

    private setupGraphics() {
        this.selectionRect = this.add.rectangle(0, 0, 0, 0).setStrokeStyle(2, 0x00ff00).setOrigin(0).setVisible(false);
        this.polygonGraphics = this.add.graphics();
        this.tempLine = this.add.line(0, 0, 0, 0, 0, 0, 0x00ff00).setOrigin(0).setVisible(false);
    }

    private fitImageToScreen() {
        if (!this.mainImage) return;

        // Reset scale
        this.mainImage.setScale(1);

        const padding = 60; // Space for UI
        const availableWidth = this.scale.width - padding * 2;
        const availableHeight = this.scale.height - 150; // Bottom UI space

        if (this.mainImage.width > availableWidth || this.mainImage.height > availableHeight) {
            const scaleX = availableWidth / this.mainImage.width;
            const scaleY = availableHeight / this.mainImage.height;
            const scale = Math.min(scaleX, scaleY);
            this.mainImage.setScale(scale);
        }

        // Center it
        this.mainImage.setPosition(
            (this.scale.width - this.mainImage.displayWidth) / 2,
            (this.scale.height - 150 - this.mainImage.displayHeight) / 2 + 20
        );
    }

    private setupUI() {
        // Top Toolbar - Flat minimalist design
        const barHeight = 50;
        this.add.rectangle(0, 0, this.scale.width, barHeight, 0x1e1e1e).setOrigin(0).setScrollFactor(0);

        this.add.text(20, 15, '📐', { fontSize: '20px', color: '#cccccc', fontStyle: 'bold' }).setScrollFactor(0);

        // Mode Toggles - Flat icon buttons
        this.modeButtons['rect'] = this.createIconButton('⏹️', 130, 25, () => this.setMode('rect'), this.selectionMode === 'rect' ? 0x00d4ff : 0x1e1e1e, 'Rectangle Selection');
        this.modeButtons['polygon'] = this.createIconButton('🕸️', 180, 25, () => this.setMode('polygon'), this.selectionMode === 'polygon' ? 0x00d4ff : 0x1e1e1e, 'Polygon Selection');

        // Zoom Controls
        this.add.text(230, 25, 'Zoom:', { fontSize: '14px', color: '#888888' }).setOrigin(0.5).setScrollFactor(0);
        this.createSmallBtn('-', 270, 25, () => this.adjustZoom(-0.1), 'Zoom Out');
        this.createSmallBtn('+', 300, 25, () => this.adjustZoom(0.1), 'Zoom In');

        // Action Buttons - Flat design
        this.createIconButton('✖️', 350, 25, () => {
            this.scene.stop();
            this.scene.resume('EditorScene');
        }, 0x1e1e1e, 'Cancel - Return to Editor');

        this.createIconButton('🧩', 400, 25, () => this.autoExtractSprites(), 0x1e1e1e, 'Auto Tile Extract - Slice into 64x64 tiles');
        this.createIconButton('🤖', 450, 25, () => this.smartExtractObjects(), 0x1e1e1e, 'Smart Object Extract - Detect whole objects');
        this.createIconButton('📦', 500, 25, () => this.extractPoints('object'), 0x1e1e1e, 'Add Selection as Object');
        this.createIconButton('🎨', 550, 25, () => this.extractPoints('tile'), 0x1e1e1e, 'Add Selection as Tile');

        // Bottom Toolbar (scrollable extracted items)
        const bottomY = this.scale.height - 90;
        this.add.rectangle(0, bottomY, this.scale.width, 90, 0x1e1e1e).setOrigin(0).setScrollFactor(0);

        // Extracted Items Title
        this.add.text(20, bottomY + 5, 'Extracted Items:', { fontSize: '14px', color: '#888888' }).setScrollFactor(0);

        // Container for extracted items
        this.extractedItemsContainer = this.add.container(80, bottomY + 45).setScrollFactor(0);

        // Navigation arrows
        this.createIconButton('◀', 40, bottomY + 45, () => this.scrollExtractedItems(-1), 0x1e1e1e, 'Previous Items');
        this.createIconButton('▶', this.scale.width - 40, bottomY + 45, () => this.scrollExtractedItems(1), 0x1e1e1e, 'Next Items');

        // Tooltip setup - flat style
        this.tooltipBg = this.add.rectangle(0, 0, 200, 30, 0x2b2b2b, 0.95).setOrigin(0).setVisible(false).setDepth(1000).setScrollFactor(0);
        this.tooltipText = this.add.text(0, 0, '', { fontSize: '11px', color: '#cccccc', padding: { x: 8, y: 6 } }).setOrigin(0).setVisible(false).setDepth(1001).setScrollFactor(0);

        // Keyboard shortcuts
        this.input.keyboard?.on('keydown-ESC', () => this.setMode(this.selectionMode));
        this.input.keyboard?.on('keydown-PLUS', () => this.adjustZoom(0.5));
        this.input.keyboard?.on('keydown-MINUS', () => this.adjustZoom(-0.5));

        // Dimension Inputs (Manually created simple UI)
        this.createDimensionInputs();
    }

    private adjustZoom(delta: number) {
        if (!this.mainImage) return;
        const newScale = Phaser.Math.Clamp(this.mainImage.scale + delta, 0.3, 5);
        this.mainImage.setScale(newScale);
    }

    private createSmallBtn(text: string, x: number, y: number, callback: () => void, tooltip: string = '') {
        const btn = this.add.container(x, y).setScrollFactor(0);
        const bg = this.add.rectangle(0, 0, 24, 24, 0x1e1e1e).setInteractive({ useHandCursor: true });
        const txt = this.add.text(0, 0, text, { fontSize: '16px', color: '#cccccc' }).setOrigin(0.5);
        bg.on('pointerdown', callback);

        if (tooltip) {
            bg.on('pointerover', () => {
                bg.setFillStyle(0x3a3a3a);
                this.showTooltip(tooltip, x, y + 20);
            });
            bg.on('pointerout', () => {
                bg.setFillStyle(0x1e1e1e);
                this.hideTooltip();
            });
        }
        btn.add([bg, txt]);
    }





    private createIconButton(icon: string, x: number, y: number, callback: () => void, color: number = 0x1e1e1e, tooltip: string = ''): Phaser.GameObjects.Rectangle {
        const btn = this.add.container(x, y).setScrollFactor(0);
        const size = 36;

        const bg = this.add.rectangle(0, 0, size, size, color)
            .setInteractive({ useHandCursor: true });

        const txt = this.add.text(0, 0, icon, { fontSize: '18px' }).setOrigin(0.5);

        bg.on('pointerdown', callback);

        if (tooltip) {
            bg.on('pointerover', () => {
                if (this.selectionMode !== (icon === '⏹️' ? 'rect' : 'polygon')) {
                    bg.setFillStyle(0x3a3a3a);
                }
                this.showTooltip(tooltip, x, y + 25);
            });
            bg.on('pointerout', () => {
                const isActive = (icon === '⏹️' && this.selectionMode === 'rect') || (icon === '🕸️' && this.selectionMode === 'polygon');
                bg.setFillStyle(isActive ? 0x00d4ff : 0x1e1e1e);
                this.hideTooltip();
            });
        }

        btn.add([bg, txt]);
        return bg;
    }

    private showTooltip(text: string, x: number, y: number) {
        if (!this.tooltipText || !this.tooltipBg) return;

        this.tooltipText.setText(text);
        const width = this.tooltipText.width + 16;
        const height = this.tooltipText.height + 12;

        this.tooltipBg.setSize(width, height);
        this.tooltipBg.setPosition(x - width / 2, y);
        this.tooltipText.setPosition(x - width / 2 + 8, y + 6);

        this.tooltipBg.setVisible(true);
        this.tooltipText.setVisible(true);
    }

    private hideTooltip() {
        this.tooltipBg?.setVisible(false);
        this.tooltipText?.setVisible(false);
    }

    private setMode(mode: 'rect' | 'polygon') {
        this.selectionMode = mode;
        this.isSelecting = false;
        this.polygonPoints = [];
        this.selectionRect?.setVisible(false);
        this.tempLine?.setVisible(false);
        this.drawPolygon(); // Clear

        // Update Button Highlights
        if (this.modeButtons['rect']) this.modeButtons['rect'].setFillStyle(mode === 'rect' ? 0x00d4ff : 0x1e1e1e);
        if (this.modeButtons['polygon']) this.modeButtons['polygon'].setFillStyle(mode === 'polygon' ? 0x00d4ff : 0x1e1e1e);
    }

    private setupControls() {
        // Zoom - only zoom the image
        this.input.on('wheel', (_pointer: any, _gameObjects: any, _deltaX: number, deltaY: number) => {
            if (!this.mainImage) return;
            const delta = deltaY > 0 ? -0.1 : 0.1;
            const newScale = Phaser.Math.Clamp(this.mainImage.scale + delta, 0.3, 5);
            this.mainImage.setScale(newScale);
        });

        // Pan (Middle Mouse)
        let isPanning = false;
        let lastPan = new Phaser.Math.Vector2();

        this.input.on('pointerdown', (pointer: Phaser.Input.Pointer) => {
            if (pointer.middleButtonDown()) {
                isPanning = true;
                lastPan.set(pointer.x, pointer.y);
                return;
            }

            if (pointer.y > this.scale.height - 90 || pointer.y < 50) return; // Ignore UI areas

            if (this.selectionMode === 'rect') {
                this.isSelecting = true;
                this.startPoint = new Phaser.Math.Vector2(pointer.x, pointer.y);
                this.selectionRect?.setPosition(pointer.x, pointer.y).setSize(0, 0).setVisible(true);
            } else {
                // Polygon Point
                // Toggle point addition
                // If close to start, close polygon?
                if (this.polygonPoints.length > 2) {
                    const first = this.polygonPoints[0];
                    if (Phaser.Math.Distance.Between(pointer.x, pointer.y, first.x, first.y) < 20 / this.cameras.main.zoom) {
                        // Close shape
                        this.extractPoints('object');
                        return;
                    }
                }
                const worldPoint = this.cameras.main.getWorldPoint(pointer.x, pointer.y);
                this.polygonPoints.push(new Phaser.Math.Vector2(worldPoint.x, worldPoint.y));
                this.drawPolygon();
            }
        });

        this.input.on('pointermove', (pointer: Phaser.Input.Pointer) => {
            if (isPanning) {
                const currentPos = new Phaser.Math.Vector2(pointer.x, pointer.y);
                const diff = lastPan.clone().subtract(currentPos).scale(1 / this.cameras.main.zoom);
                this.cameras.main.scrollX += diff.x;
                this.cameras.main.scrollY += diff.y;
                lastPan.set(pointer.x, pointer.y);
                return;
            }

            const worldPoint = this.cameras.main.getWorldPoint(pointer.x, pointer.y);

            if (this.selectionMode === 'rect' && this.isSelecting && this.startPoint && this.selectionRect) {
                // Need to convert startPoint back to world if needed or just use screen for visual?
                // Actually selectionRect is added to Scene, so it follows camera unless scroll factor 0.
                // We haven't set scroll factor 0 for mainImage, so let's stick to world coords.
                const startWorld = this.cameras.main.getWorldPoint(this.startPoint.x, this.startPoint.y);

                const x = Math.min(worldPoint.x, startWorld.x);
                const y = Math.min(worldPoint.y, startWorld.y);
                const w = Math.abs(worldPoint.x - startWorld.x);
                const h = Math.abs(worldPoint.y - startWorld.y);
                this.selectionRect.setPosition(x, y).setSize(w, h);
            } else if (this.selectionMode === 'polygon' && this.polygonPoints.length > 0) {
                // Draw temp line from last point to cursor
                const last = this.polygonPoints[this.polygonPoints.length - 1];
                this.tempLine?.setTo(last.x, last.y, worldPoint.x, worldPoint.y).setVisible(true).setStrokeStyle(1 / this.cameras.main.zoom, 0x00ff00);
            }
        });

        this.input.on('pointerup', (pointer: Phaser.Input.Pointer) => {
            if (this.selectionMode === 'rect' && !this.isSelecting && !isPanning) {
                // Check if we are in "Point/Cell" mode (implied if not dragging rect)
                // Simply clicking in rect mode without dragging -> Select Cell
                // Or add a specific button for "Cell Mode". 
                // For now, let's say if drag was very small (< 5px), treat as click
                if (getDist(pointer, this.startPoint) < 5) {
                    this.extractCellAt(pointer.worldX, pointer.worldY);
                }
            } else if (this.selectionMode === 'rect') {
                this.isSelecting = false;
            }
            isPanning = false;
        });

        const getDist = (p1: any, p2: any) => {
            if (!p1 || !p2) return 999;
            return Phaser.Math.Distance.Between(p1.x, p1.y, p2.x, p2.y);
        };

        // Right click to remove last polygon point
        this.input.on('pointerdown', (pointer: Phaser.Input.Pointer) => {
            if (this.selectionMode === 'polygon' && pointer.rightButtonDown()) {
                this.polygonPoints.pop();
                this.drawPolygon();
            }
        });
    }

    private drawPolygon() {
        if (!this.polygonGraphics) return;
        this.polygonGraphics.clear();
        this.polygonGraphics.lineStyle(2, 0x00ff00);
        this.polygonGraphics.fillStyle(0x00ff00, 0.2);

        if (this.polygonPoints.length > 0) {
            this.polygonGraphics.beginPath();
            this.polygonGraphics.moveTo(this.polygonPoints[0].x, this.polygonPoints[0].y);
            for (let i = 1; i < this.polygonPoints.length; i++) {
                this.polygonGraphics.lineTo(this.polygonPoints[i].x, this.polygonPoints[i].y);
            }
            if (this.polygonPoints.length > 2) {
                // Visualize closing?
                this.polygonGraphics.strokePath();
                this.polygonGraphics.fillPath();
            } else {
                this.polygonGraphics.strokePath();
            }
        }
    }

    private extractPoints(type: 'tile' | 'object') {
        if (!this.mainImage) return;

        let regions: { x: number, y: number }[] = [];
        let minX = Infinity, minY = Infinity, maxX = -Infinity, maxY = -Infinity;

        if (this.selectionMode === 'rect') {
            if (!this.selectionRect || this.selectionRect.width === 0) return;
            // Convert rect to points
            const r = this.selectionRect;
            regions = [
                { x: r.x, y: r.y },
                { x: r.x + r.width, y: r.y },
                { x: r.x + r.width, y: r.y + r.height },
                { x: r.x, y: r.y + r.height }
            ];
            minX = r.x; minY = r.y; maxX = r.x + r.width; maxY = r.y + r.height;
        } else {
            if (this.polygonPoints.length < 3) return;
            regions = this.polygonPoints;
            regions.forEach(p => {
                minX = Math.min(minX, p.x);
                minY = Math.min(minY, p.y);
                maxX = Math.max(maxX, p.x);
                maxY = Math.max(maxY, p.y);
            });
        }

        // Convert Screen Coords to Image Local Coords
        const imgX = this.mainImage.x;
        const imgY = this.mainImage.y;
        const scaleX = this.mainImage.scaleX;
        const scaleY = this.mainImage.scaleY;

        // Bounding Box on Texture
        const texX = Math.floor((minX - imgX) / scaleX);
        const texY = Math.floor((minY - imgY) / scaleY);
        const texW = Math.floor((maxX - minX) / scaleX);
        const texH = Math.floor((maxY - minY) / scaleY);

        if (texW <= 0 || texH <= 0) return;

        // Generate Texture Key
        const key = `extract_${Date.now()}`;

        // Create Canvas for cropping
        const canvas = this.textures.createCanvas(key, texW, texH);
        if (!canvas) return;

        const ctx = canvas.context;

        // Draw path clips
        ctx.beginPath();
        regions.forEach((p, i) => {

            const localX = (p.x - minX) / scaleX;
            const localY = (p.y - minY) / scaleY;
            if (i === 0) ctx.moveTo(localX, localY);
            else ctx.lineTo(localX, localY);
        });
        ctx.closePath();
        ctx.clip(); // Clip to polygon

        // Draw the image section
        const source = this.mainImage.texture.getSourceImage() as HTMLImageElement;
        ctx.drawImage(source, texX, texY, texW, texH, 0, 0, texW, texH);

        canvas.refresh();

        // Notify Editor
        const editor = this.scene.get('EditorScene') as any;
        if (editor && editor.receiveExtractedSprite) {
            editor.receiveExtractedSprite({
                x: 0, y: 0, width: texW, height: texH, type,
                textureKey: key
            });
        }

        // Add to local visual list
        this.addExtractedThumbnail(key, texW, texH);

        // Visual flash
        this.cameras.main.flash(200, 0, 255, 0);

        // Reset polygon if needed
        if (this.selectionMode === 'polygon') {
            this.polygonPoints = [];
            this.drawPolygon();
        }
        this.tempLine?.setVisible(false);
        this.selectionRect?.setVisible(false);
    }


    private addExtractedThumbnail(key: string, _w: number, _h: number) {
        if (!this.extractedItemsContainer) return;

        const idx = this.extractionList.length;
        const size = 64;
        const gap = 10;
        const x = idx * (size + gap);

        // Create a container for this item
        const itemContainer = this.add.container(x, 0);

        // Background - flat style
        const bg = this.add.rectangle(0, 0, size + 4, size + 4, 0x2b2b2b).setOrigin(0.5);

        // Sprite
        const img = this.add.image(0, 0, key);
        const scale = Math.min(size / img.width, size / img.height);
        img.setScale(scale);

        // Label
        const label = this.add.text(0, size / 2 + 5, `Item ${idx + 1}`, { fontSize: '10px', color: '#888888' }).setOrigin(0.5);

        itemContainer.add([bg, img, label]);
        this.extractedItemsContainer.add(itemContainer);

        this.extractionList.push(key);

        // Update visibility based on scroll
        this.updateExtractedItemsVisibility();
    }

    private scrollExtractedItems(direction: number) {
        const maxOffset = Math.max(0, this.extractionList.length - this.maxVisibleItems);
        this.extractedItemsScrollOffset = Phaser.Math.Clamp(this.extractedItemsScrollOffset + direction, 0, maxOffset);
        this.updateExtractedItemsVisibility();
    }

    private updateExtractedItemsVisibility() {
        if (!this.extractedItemsContainer) return;

        const size = 64;
        const gap = 10;
        const itemWidth = size + gap;

        // Move container based on scroll offset
        this.extractedItemsContainer.x = 80 - (this.extractedItemsScrollOffset * itemWidth);

        // Keep all items visible - they scroll with the container
    }

    private autoExtractSprites() {
        if (!this.mainImage) return;

        // Get the source image
        const source = this.mainImage.texture.getSourceImage() as HTMLImageElement;
        if (!source) return;

        // Create a temporary canvas to analyze pixels
        const tempCanvas = document.createElement('canvas');
        tempCanvas.width = source.width;
        tempCanvas.height = source.height;
        const tempCtx = tempCanvas.getContext('2d');
        if (!tempCtx) return;

        tempCtx.drawImage(source, 0, 0);

        const gridSize = this.autoExtractGridSize;
        const cols = Math.ceil(source.width / gridSize);
        const rows = Math.ceil(source.height / gridSize);

        let extractedCount = 0;
        let isFirstExtraction = true;

        // Scan grid and extract non-empty cells
        for (let row = 0; row < rows; row++) {
            for (let col = 0; col < cols; col++) {
                const x = col * gridSize;
                const y = row * gridSize;
                const w = Math.min(gridSize, source.width - x);
                const h = Math.min(gridSize, source.height - y);

                // Check if this cell has non-transparent pixels
                if (this.hasNonTransparentPixels(tempCtx, x, y, w, h)) {
                    // Extract this region
                    const key = `auto_extract_${Date.now()}_${extractedCount}`;

                    // Create canvas for this sprite
                    const canvas = this.textures.createCanvas(key, w, h);
                    if (!canvas) continue;

                    const ctx = canvas.context;
                    ctx.drawImage(source, x, y, w, h, 0, 0, w, h);
                    canvas.refresh();

                    // Send to Editor - STRICTLY as tile
                    const editor = this.scene.get('EditorScene') as any;
                    if (editor && editor.receiveExtractedSprite) {
                        editor.receiveExtractedSprite({
                            x: 0, y: 0, width: w, height: h, type: 'tile',
                            textureKey: key
                        }, isFirstExtraction);
                    }

                    // Add to local visual list - ensure container exists
                    if (this.extractedItemsContainer) {
                        this.addExtractedThumbnail(key, w, h);
                    }

                    extractedCount++;
                    isFirstExtraction = false;
                }
            }
        }

        // Visual feedback
        if (extractedCount > 0) {
            this.cameras.main.flash(300, 0, 255, 0);

        } else {
            this.cameras.main.flash(300, 255, 0, 0);

        }
    }

    private smartExtractObjects() {
        if (!this.mainImage) return;


        const source = this.mainImage.texture.getSourceImage() as HTMLImageElement;

        const tempCanvas = document.createElement('canvas');
        tempCanvas.width = source.width;
        tempCanvas.height = source.height;
        const ctx = tempCanvas.getContext('2d');
        if (!ctx) return;
        ctx.drawImage(source, 0, 0);

        const imageData = ctx.getImageData(0, 0, source.width, source.height);
        const data = imageData.data;
        const width = source.width;
        const height = source.height;

        // 1. Determine Background Color (Top-left pixel if fully opaque)
        let isOpaque = true;
        for (let i = 3; i < data.length; i += 40) { // Sample some pixels
            if (data[i] < 250) { isOpaque = false; break; }
        }

        const bgR = data[0], bgG = data[1], bgB = data[2];
        const visited = new Uint8Array(width * height);
        const objects: { minX: number, minY: number, maxX: number, maxY: number }[] = [];

        // 2. Connected Component Labeling (Simplified BFS)
        for (let y = 0; y < height; y += 4) { // Step for speed, can refine
            for (let x = 0; x < width; x += 4) {
                const idx = (y * width + x);
                if (visited[idx]) continue;

                const pIdx = idx * 4;
                const r = data[pIdx], g = data[pIdx + 1], b = data[pIdx + 2], a = data[pIdx + 3];

                let isContent = false;
                if (isOpaque) {
                    // Difference from background color
                    const diff = Math.abs(r - bgR) + Math.abs(g - bgG) + Math.abs(b - bgB);
                    if (diff > 30) isContent = true;
                } else {
                    if (a > 20) isContent = true;
                }

                if (isContent) {
                    // Start BFS to find bounds
                    const result = this.findObjectBounds(data, visited, x, y, width, height, isOpaque, bgR, bgG, bgB);
                    if (result.width > 10 && result.height > 10) {
                        objects.push(result);
                    }
                }
            }
        }



        let extractedCount = 0;
        objects.forEach((obj, i) => {
            const key = `smart_extract_${Date.now()}_${i}`;
            const w = obj.maxX - obj.minX;
            const h = obj.maxY - obj.minY;

            const canvas = this.textures.createCanvas(key, w, h);
            if (canvas) {
                canvas.context.drawImage(source, obj.minX, obj.minY, w, h, 0, 0, w, h);
                canvas.refresh();

                const editor = this.scene.get('EditorScene') as any;
                if (editor && editor.receiveExtractedSprite) {
                    editor.receiveExtractedSprite({
                        x: 0, y: 0, width: w, height: h, type: 'object',
                        textureKey: key
                    }, i === 0);
                }
                this.addExtractedThumbnail(key, w, h);
                extractedCount++;
            }
        });

        if (extractedCount > 0) {
            this.cameras.main.flash(300, 0, 255, 0);
            this.showTooltip(`Smart Detected ${extractedCount} Objects!`, this.scale.width / 2, 80);
        }
    }

    private findObjectBounds(data: Uint8ClampedArray, visited: Uint8Array, startX: number, startY: number, width: number, height: number, isOpaque: boolean, bgR: number, bgG: number, bgB: number) {
        let minX = startX, minY = startY, maxX = startX, maxY = startY;
        const queue: [number, number][] = [[startX, startY]];
        visited[startY * width + startX] = 1;

        const checkContent = (x: number, y: number) => {
            const pIdx = (y * width + x) * 4;
            if (isOpaque) {
                const diff = Math.abs(data[pIdx] - bgR) + Math.abs(data[pIdx + 1] - bgG) + Math.abs(data[pIdx + 2] - bgB);
                return diff > 30;
            }
            return data[pIdx + 3] > 20;
        };

        let count = 0;
        while (queue.length > 0 && count < 5000) { // Limit size for safety
            const [curX, curY] = queue.shift()!;
            count++;

            minX = Math.min(minX, curX);
            minY = Math.min(minY, curY);
            maxX = Math.max(maxX, curX);
            maxY = Math.max(maxY, curY);

            // Neighbors (4-connectivity, skip steps for speed)
            const dirs = [[0, 4], [0, -4], [4, 0], [-4, 0]];
            for (const [dx, dy] of dirs) {
                const nx = curX + dx;
                const ny = curY + dy;
                if (nx >= 0 && nx < width && ny >= 0 && ny < height) {
                    const nIdx = ny * width + nx;
                    if (!visited[nIdx] && checkContent(nx, ny)) {
                        visited[nIdx] = 1;
                        queue.push([nx, ny]);
                    }
                }
            }
        }

        return { minX, minY, maxX, maxY, width: maxX - minX, height: maxY - minY };
    }

    private hasNonTransparentPixels(ctx: CanvasRenderingContext2D, x: number, y: number, w: number, h: number): boolean {
        try {
            const imageData = ctx.getImageData(x, y, w, h);
            const data = imageData.data;

            // Check every pixel's alpha channel
            for (let i = 3; i < data.length; i += 4) {
                if (data[i] > 10) { // Alpha > 10 (nearly opaque)
                    return true;
                }
            }
            return false;
        } catch (e) {
            console.error('Error checking pixels:', e);
            return false;
        }
    }
    private inputs: { w: HTMLInputElement, h: HTMLInputElement } | null = null;
    private createDimensionInputs() {
        // Since Phaser raw DOM input can be tricky, we'll assume a simple overlay or just use prompts if DOM is restricted.
        // But for better UX, let's try to add standard text inputs if possible, or just use Phaser text that prompts standard window.prompt.
        // Actually, let's use a "Settings" button that prompts for now to be safe, OR render a simple HTML overlay.

        // Let's create an HTML overlay for W/H
        const wrapper = document.createElement('div');
        wrapper.style.position = 'absolute';
        wrapper.style.top = '60px';
        wrapper.style.left = '50%';
        wrapper.style.transform = 'translateX(-50%)';
        wrapper.style.display = 'flex';
        wrapper.style.gap = '10px';
        wrapper.style.padding = '5px';
        wrapper.style.background = '#1e1e1e';
        wrapper.style.border = '1px solid #444';
        wrapper.style.borderRadius = '4px';

        const createInp = (lbl: string, val: number) => {
            const cont = document.createElement('div');
            cont.style.color = '#ccc';
            cont.style.fontSize = '12px';
            cont.innerText = lbl;
            const inp = document.createElement('input');
            inp.type = 'number';
            inp.value = val.toString();
            inp.style.width = '50px';
            inp.style.background = '#333';
            inp.style.color = '#fff';
            inp.style.border = '1px solid #555';
            inp.style.marginLeft = '5px';
            cont.appendChild(inp);
            wrapper.appendChild(cont);
            return inp;
        };

        const wInp = createInp('W:', 64);
        const hInp = createInp('H:', 64);

        document.body.appendChild(wrapper);

        // Sync values
        wInp.onchange = () => this.autoExtractGridSize = parseInt(wInp.value) || 64;
        hInp.onchange = () => { /* Handle Height if different */ };

        this.inputs = { w: wInp, h: hInp };

        // Cleanup on shutdown
        this.events.once('shutdown', () => {
            if (document.body.contains(wrapper)) document.body.removeChild(wrapper);
        });
    }

    // Update click handler to use these values for manual cell selection
    private extractCellAt(worldX: number, worldY: number) {
        if (!this.mainImage) return;

        const w = parseInt(this.inputs?.w.value || '64');
        const h = parseInt(this.inputs?.h.value || '64');

        // Convert world to local
        const imgX = this.mainImage.x;
        const imgY = this.mainImage.y;

        // Click relative to image origin
        const relX = (worldX - imgX) / this.mainImage.scaleX;
        const relY = (worldY - imgY) / this.mainImage.scaleY;

        if (relX < 0 || relY < 0 || relX > this.mainImage.width || relY > this.mainImage.height) return;

        // Snap to grid
        const col = Math.floor(relX / w);
        const row = Math.floor(relY / h);

        const x = col * w;
        const y = row * h;

        // Extract
        const key = `cell_${col}_${row}_${Date.now()}`;
        const canvas = this.textures.createCanvas(key, w, h);
        if (!canvas) return;

        const source = this.mainImage.texture.getSourceImage() as HTMLImageElement;
        canvas.context.drawImage(source, x, y, w, h, 0, 0, w, h);
        canvas.refresh();

        const editor = this.scene.get('EditorScene') as any;
        if (editor && editor.receiveExtractedSprite) {
            editor.receiveExtractedSprite({
                x: 0, y: 0, width: w, height: h, type: 'tile',
                textureKey: key
            });
        }
        this.addExtractedThumbnail(key, w, h);
        this.cameras.main.flash(100, 0, 255, 255);
    }
}

