import Phaser from 'phaser';
import SaveManager from '../managers/SaveManager';

export default class Store extends Phaser.Scene {
    private moneyText!: Phaser.GameObjects.Text;
    private items: { name: string, cost: number, description: string, action: () => void }[] = [];
    private selectionIndex: number = 0;
    private itemContainers: Phaser.GameObjects.Container[] = [];

    constructor() {
        super('Store');
    }

    private returnScene: string = 'MainMenu';

    init(data: { returnScene?: string }) {
        if (data && data.returnScene) {
            this.returnScene = data.returnScene;
        }
    }

    create() {
        const width = this.scale.width;
        const height = this.scale.height;

        // --- BACKGROUND ---
        this.add.rectangle(0, 0, width, height, 0x1a1a2e).setOrigin(0);

        // Title
        this.add.text(width / 2, 60, "KURUKKANMOOLA GENERAL STORE", {
            fontFamily: 'Cinzel',
            fontSize: '42px',
            color: '#FFD700',
            stroke: '#000000',
            strokeThickness: 4
        }).setOrigin(0.5);

        // Money Display
        const savedState = SaveManager.load() || SaveManager.getInitialState();
        this.moneyText = this.add.text(width - 50, 60, `₹ ${savedState.money}`, {
            fontFamily: 'Courier',
            fontSize: '32px',
            color: '#00ff00',
            align: 'right'
        }).setOrigin(1, 0.5);

        // --- ITEMS ---
        this.defineItems(savedState);
        this.renderItems();

        // --- INSTRUCTIONS ---
        this.add.text(width / 2, height - 50, "[ UP / DOWN to Select ]  [ ENTER to Buy ]  [ ESC to Leave ]", {
            fontSize: '20px',
            color: '#aaaaaa'
        }).setOrigin(0.5);

        // --- INPUT ---
        this.input.keyboard!.on('keydown-UP', () => this.navigate(-1));
        this.input.keyboard!.on('keydown-DOWN', () => this.navigate(1));
        this.input.keyboard!.on('keydown-ENTER', () => this.buyItem());
        this.input.keyboard!.on('keydown-ESC', () => this.leaveStore());

        this.updateSelection();
    }

    private defineItems(_state: any) {
        this.items = [
            {
                name: "Health Elixir",
                cost: 50,
                description: "Restores full health.",
                action: () => {
                    const currentState = SaveManager.load();
                    if (currentState) {
                        currentState.playerHealth = currentState.maxHealth;
                        this.saveAndRefresh(currentState);
                        this.showMessage("Health Restored!");
                    }
                }
            },
            {
                name: "Vitality Charm",
                cost: 100,
                description: "Increases Max Health by 1.",
                action: () => {
                    const currentState = SaveManager.load();
                    if (currentState) {
                        currentState.maxHealth += 1;
                        currentState.playerHealth = currentState.maxHealth; // Heal on upgrade
                        this.saveAndRefresh(currentState);
                        this.showMessage("Max Health Increased!");
                    }
                }
            },
            // Placeholder for ability unlock
            {
                name: "Speed Boots",
                cost: 200,
                description: "Move faster! (Passive)",
                action: () => {
                    // Logic to unlock speed (save to unlockedAbilities)
                    const currentState = SaveManager.load();
                    if (currentState) {
                        if (!currentState.unlockedAbilities) currentState.unlockedAbilities = [];
                        if (!currentState.unlockedAbilities.includes('speed_boots')) {
                            currentState.unlockedAbilities.push('speed_boots');
                            this.saveAndRefresh(currentState);
                            this.showMessage("Speed Boots Acquired!");
                        } else {
                            this.showMessage("You already have this!");
                            // Refund? Or just checks before buying. 
                            // For now, simpler to just message.
                            // Actually we should charge first only if success.
                            // Fix in buyItem logic.
                        }
                    }
                }
            },
            {
                name: "Small Cottage",
                cost: 300,
                description: "Purchase a permanent home in the village.",
                action: () => {
                    const currentState = SaveManager.load();
                    if (currentState) {
                        if (currentState.houseOwned) {
                            this.showMessage("You already own a home!", 0xffff00);
                        } else {
                            currentState.houseOwned = true;
                            this.saveAndRefresh(currentState);
                            this.showMessage("Home Ownership Acquired!", 0x00ff00);
                        }
                    }
                }
            }
        ];
    }

    private renderItems() {
        this.itemContainers.forEach(c => c.destroy());
        this.itemContainers = [];

        let y = 180;
        const x = this.scale.width / 2;
        const state = SaveManager.load() || SaveManager.getInitialState();

        this.items.forEach((item) => {
            const isOwned = (item.name === "Speed Boots" && state.unlockedAbilities?.includes('speed_boots')) ||
                            (item.name === "Small Cottage" && state.houseOwned);

            const container = this.add.container(x, y);

            // Bg
            const bg = this.add.rectangle(0, 0, 600, 80, isOwned ? 0x222222 : 0x0f3460).setStrokeStyle(2, 0x16213e);
            container.add(bg);

            // Text
            const color = isOwned ? '#888888' : '#ffffff';
            const nameText = this.add.text(-280, -20, item.name, { fontSize: '24px', color, fontFamily: 'Cinzel' });
            const costText = this.add.text(280, -20, isOwned ? "OWNED" : `₹ ${item.cost}`, { fontSize: '24px', color: isOwned ? '#888888' : '#FFD700' }).setOrigin(1, 0);
            const descText = this.add.text(-280, 10, item.description, { fontSize: '16px', color: '#aaaaaa', fontFamily: 'Sans-serif' });

            container.add([nameText, costText, descText]);

            this.itemContainers.push(container);
            y += 100;
        });

        // Comprehensive Inventory Display at bottom
        const invY = y + 20;
        this.add.text(x, invY, "CURRENT CUSTODY", { fontSize: '20px', color: '#aaaaaa', fontStyle: 'bold' }).setOrigin(0.5);
        
        // Build comprehensive inventory list
        const invList: string[] = [...state.inventory];
        if (state.unlockedAbilities?.includes('speed_boots')) invList.push("Speed Boots");
        if (state.flags?.hasGoldenSpatula) invList.push("Gilded Spatula");
        if (state.busTicket || state.flags?.busTicket) invList.push("Bus Ticket");
        if (state.houseOwned) invList.push("Small Cottage");

        const invItems = invList.length > 0 ? invList.join(", ") : "Empty";
        this.add.text(x, invY + 30, invItems, { 
            fontSize: '16px', color: '#888888', fontStyle: 'italic', wordWrap: { width: 500 }, align: 'center' 
        }).setOrigin(0.5);
    }

    private navigate(direction: number) {
        this.selectionIndex += direction;
        if (this.selectionIndex < 0) this.selectionIndex = this.items.length - 1;
        if (this.selectionIndex >= this.items.length) this.selectionIndex = 0;

        this.updateSelection();
        this.sound.play('dash', { volume: 0.2, rate: 2.0 });
    }

    private updateSelection() {
        this.itemContainers.forEach((container, index) => {
            const bg = container.list[0] as Phaser.GameObjects.Rectangle;
            if (index === this.selectionIndex) {
                bg.setStrokeStyle(4, 0xFFD700);
                if (bg.fillColor !== 0x222222) bg.setFillStyle(0x1a1a40);
            } else {
                bg.setStrokeStyle(2, 0x16213e);
                if (bg.fillColor !== 0x222222) bg.setFillStyle(0x0f3460);
            }
        });
    }

    private buyItem() {
        const item = this.items[this.selectionIndex];
        const state = SaveManager.load();
        if (!state) return;

        // Owned checks
        const isOwned = (item.name === "Speed Boots" && state.unlockedAbilities?.includes('speed_boots')) ||
                        (item.name === "Small Cottage" && state.houseOwned);

        if (isOwned) {
            this.showMessage("ALREADY OWNED", 0xffff00);
            return;
        }

        if (state.money >= item.cost) {
            state.money -= item.cost;
            SaveManager.save(state);
            this.updateMoneyDisplay(state.money);
            item.action();
            this.renderItems(); // Refresh OWNED labels
            this.updateSelection();
            this.sound.play('dash', { rate: 1.5, volume: 0.5 });
        } else {
            this.showMessage("NOT ENOUGH MONEY", 0xff0000);
            this.sound.play('dash', { rate: 0.5 });
        }
    }

    private saveAndRefresh(state: any) {
        SaveManager.save(state);
        this.updateMoneyDisplay(state.money);
    }

    private updateMoneyDisplay(amount: number) {
        this.moneyText.setText(`₹ ${amount}`);
    }

    private showMessage(text: string, color: number = 0x00ff00) {
        const msg = this.add.text(this.scale.width / 2, this.scale.height - 100, text, {
            fontSize: '32px',
            color: color === 0x00ff00 ? '#00ff00' : '#ff0000',
            stroke: '#000000',
            strokeThickness: 4
        }).setOrigin(0.5);

        this.tweens.add({
            targets: msg,
            y: msg.y - 50,
            alpha: 0,
            duration: 1500,
            onComplete: () => msg.destroy()
        });
    }

    private leaveStore() {
        if (this.returnScene && this.scene.manager.getScene(this.returnScene)) {
            this.scene.stop();
            this.scene.wake(this.returnScene);
        } else {
            this.scene.start('MainMenu');
        }
    }
}
