
import Phaser from 'phaser';
import Enemy from '../Enemy';
import { SPRITE_KEYS } from '../../config';
import VisualEffectManager from '../../utils/VisualEffectManager';

export default class Dasan extends Enemy {
    constructor(scene: Phaser.Scene, x: number, y: number, target: Phaser.Physics.Arcade.Sprite) {
        super(scene, x, y, SPRITE_KEYS.DASAN, target, 'DASHER');
        this.attackRange = 100; // Physical range
    }

    protected initAnimations() {
        const anims = this.scene.anims;
        const mainKey = SPRITE_KEYS.DASAN;
        const mirrorKey = SPRITE_KEYS.DASAN_MIRROR;

        if (anims.exists(`${mainKey}-walk-down`)) return;

        // Walk
        anims.create({ key: `${mainKey}-walk-down`, frames: anims.generateFrameNumbers(mainKey, { start: 1, end: 4 }), frameRate: 10, repeat: -1 });
        anims.create({ key: `${mainKey}-walk-up`, frames: anims.generateFrameNumbers(mainKey, { start: 5, end: 6 }), frameRate: 10, repeat: -1 });
        anims.create({ key: `${mainKey}-walk-right`, frames: anims.generateFrameNumbers(mainKey, { start: 9, end: 12 }), frameRate: 10, repeat: -1 });
        anims.create({ key: `${mainKey}-walk-left`, frames: anims.generateFrameNumbers(mirrorKey, { start: 14, end: 11 }), frameRate: 10, repeat: -1 });

        // Run
        anims.create({ key: `${mainKey}-run-right`, frames: anims.generateFrameNumbers(mainKey, { start: 12, end: 14 }), frameRate: 15, repeat: -1 });
        anims.create({ key: `${mainKey}-run-left`, frames: anims.generateFrameNumbers(mirrorKey, { start: 15, end: 13 }), frameRate: 15, repeat: -1 });

        // Jump
        anims.create({ key: `${mainKey}-jump-right`, frames: anims.generateFrameNumbers(mainKey, { start: 21, end: 23 }), frameRate: 12 });
        anims.create({ key: `${mainKey}-jump-left`, frames: anims.generateFrameNumbers(mirrorKey, { start: 19, end: 17 }), frameRate: 12 });

        // Knife Skills
        anims.create({ key: `${mainKey}-knife-1-right`, frames: anims.generateFrameNumbers(mainKey, { start: 4, end: 6 }), frameRate: 12 });
        anims.create({ key: `${mainKey}-knife-1-left`, frames: anims.generateFrameNumbers(mirrorKey, { start: 1, end: 3 }), frameRate: 12 });

        anims.create({ key: `${mainKey}-knife-2-right`, frames: anims.generateFrameNumbers(mainKey, { start: 24, end: 30 }), frameRate: 12 });
        anims.create({ key: `${mainKey}-knife-2-left`, frames: anims.generateFrameNumbers(mirrorKey, { start: 31, end: 25 }), frameRate: 12 });

        anims.create({ key: `${mainKey}-knife-3-right`, frames: anims.generateFrameNumbers(mainKey, { start: 32, end: 37 }), frameRate: 12 });
        anims.create({ key: `${mainKey}-knife-3-left`, frames: anims.generateFrameNumbers(mirrorKey, { start: 40, end: 35 }), frameRate: 12 });

        anims.create({ key: `${mainKey}-knife-4-right`, frames: anims.generateFrameNumbers(mainKey, { start: 40, end: 45 }), frameRate: 12 });
        anims.create({ key: `${mainKey}-knife-4-left`, frames: anims.generateFrameNumbers(mirrorKey, { start: 47, end: 42 }), frameRate: 12 });
    }

    protected playAnim(keySuffix: string, ignoreIfPlaying: boolean = true) {
        // Dasan uses mirror sprites for left direction
        let baseKey = SPRITE_KEYS.DASAN;
        const key = `${baseKey}-${keySuffix}`;
        if (!this.scene.anims.exists(key)) return;

        const anim = this.scene.anims.get(key);
        const frame = anim.frames[0].frame;
        const textureKey = frame.texture.key;

        if (this.texture.key !== textureKey) {
            this.setTexture(textureKey);
        }

        // Dasan's animations handle texture swapping, no manual flip
        this.setFlipX(false);
        this.anims.play(key, ignoreIfPlaying);
    }

    protected handleAttack() {
        if (!this.scene || !this.target || this.isAttacking || this.isDashing) return;
        const now = this.scene.time.now;
        if (now - this.lastAttackTime < this.attackCooldown) return;
        const dist = Phaser.Math.Distance.Between(this.x, this.y, this.target.x, this.target.y);

        // Dasan is more aggressive with dash
        if (dist > 150 && dist < 400 && Phaser.Math.Between(1, 100) < 30) {
            this.performDash();
            this.lastAttackTime = now;
            return;
        }

        if (dist > this.attackRange * 1.5) return;

        this.lastAttackTime = now;
        this.executePhysicalCombo();
    }

    private executePhysicalCombo() {
        if (!this.target) return;
        this.isAttacking = true;
        this.setVelocity(0, 0);

        const side = this.target.x < this.x ? 'left' : 'right';
        const comboType = Phaser.Math.Between(1, 4);

        if (comboType === 1) {
            // BASIC ATTACK
            this.playAnim(`knife-1-${side}`);
            this.createMeleeHitbox(side);
            this.once('animationcomplete', () => { if (this.active) this.isAttacking = false; });
        } else if (comboType === 2) {
            // LEAP STRIKE
            this.playAnim(`jump-${side}`);
            const jumpHeight = 50;
            const targetY = Phaser.Math.Clamp(this.y - jumpHeight, 64, (this.scene.physics.world.bounds.height || 2000) - 64);

            this.scene.tweens.add({
                targets: this,
                y: targetY,
                scale: 0.6,
                duration: 300,
                yoyo: true,
                onYoyo: () => {
                    if (this.active) {
                        this.playAnim(`knife-3-${side}`);
                        this.createMeleeHitbox(side);
                    }
                },
                onComplete: () => {
                    if (this.active) {
                        this.setScale(0.5);
                        this.isAttacking = false;
                    }
                }
            });
        } else if (comboType === 3) {
            // DOUBLE SLASH
            this.playAnim(`knife-2-${side}`);
            this.createMeleeHitbox(side);
            this.once('animationcomplete', () => {
                if (!this.active) return;
                this.playAnim(`knife-4-${side}`);
                this.createMeleeHitbox(side);
                this.once('animationcomplete', () => { if (this.active) this.isAttacking = false; });
            });
        } else {
            // DASH STRIKE
            this.playAnim(`run-${side}`);
            this.scene.physics.moveToObject(this, this.target, 500);
            this.scene.time.delayedCall(400, () => {
                if (!this.active) return;
                this.setVelocity(0);
                this.playAnim(`knife-1-${side}`);
                this.createMeleeHitbox(side);
                this.once('animationcomplete', () => { if (this.active) this.isAttacking = false; });
            });
        }
    }

    private createMeleeHitbox(side: 'left' | 'right') {
        const offset = 60;
        const x = side === 'left' ? this.x - offset : this.x + offset;
        const y = this.y;

        const hb = this.scene.add.rectangle(x, y, 80, 80, 0xff0000, 0);
        this.scene.physics.add.existing(hb);

        if (this.target) {
            this.scene.physics.overlap(hb, this.target, (_hb, target: any) => {
                if (target.takeDamage && !target.isInvincible) {
                    target.takeDamage(1);
                    this.scene.cameras.main.shake(100, 0.005);
                    VisualEffectManager.showOnomatopoeia(this.scene, target.x, target.y, 'SLASH!', 'physics');
                }
            });
        }
        this.scene.time.delayedCall(100, () => hb.destroy());
    }

    protected performDash() {
        if (!this.target) return;
        this.isDashing = true;
        const side = this.target.x < this.x ? 'left' : 'right';

        this.playAnim(`jump-${side}`);
        this.scene.physics.moveToObject(this, this.target, 600);

        this.scene.time.delayedCall(250, () => {
            if (this.active && this.isDashing) this.playAnim(`run-${side}`);
        });

        this.scene.time.delayedCall(600, () => {
            if (!this.active) return;
            this.setVelocity(0);
            this.playAnim(`knife-4-${side}`);
            this.createMeleeHitbox(side);
            this.isDashing = false;
        });
    }
}
