export type TranslationType = 'ui' | 'dialogue';

export default class TranslationManager {
    static translate(text: string, mText?: string, type: TranslationType = 'ui'): string {
        if (!text && !mText) return text;
        const state = SaveManager.load() || SaveManager.getInitialState();

        // Determine which language setting to use
        const lang = type === 'ui' ?
            (state.settings?.uiLanguage || 'en') :
            (state.settings?.dialogueLanguage || 'en');

        if (lang === 'ml' && mText) {
            return mText;
        }

        if (lang === 'en') return text;

        // Try to find translation in dictionary
        const translation = DICTIONARY[text];
        if (translation) {
            return translation[lang];
        }

        return text; // Fallback to original text
    }
}
