
import Phaser from 'phaser';
import BaseLevel from './BaseLevel';
import SaveManager from '../managers/SaveManager';
import LevelLoader from '../utils/LevelLoader';
import { LEVEL5_DATA } from '../config/Level5Data';
import { AUDIO_KEYS, SPRITE_KEYS } from '../config';
import NPC from '../entities/NPC';
import Saajan from '../entities/enemies/Saajan'; // Reuse standard enemy class for George for now, or Boss class

export default class Level5 extends BaseLevel {
    private gate: Phaser.Physics.Arcade.Image | null = null;
    private leela: NPC | null = null;
    // Damu is now in Hub
    private george: Saajan | null = null; // Using Saajan class as base for George
    private isGateOpen: boolean = false;
    private exitLink: any = null;

    constructor() {
        super('Level5', 'Level 5: Bridge Brawl');
    }

    preload() {
        super.preload();
        LevelLoader.preloadCustomAssets(this, this.customData || LEVEL5_DATA);
    }

    create() {
        super.create();
        const data = this.customData || LEVEL5_DATA;

        LevelLoader.playAudio(this, data);

        // Player
        this.player = this.createPlayer(data.playerSpawn.x, data.playerSpawn.y, data.playerSpawn.texture);

        LevelLoader.setupBounds(this, data);

        // Background image
        const bgKey = 'level_bg_texture_Level5';
        if (this.textures.exists(bgKey)) {
            this.add.image(0, 0, bgKey).setOrigin(0).setDepth(-20);
        }

        // Exit portal back to the village (so player isn't locked if they don't have Toddy)
        this.exitLink = this.createLevelLink(50, 8 * 64, 'HubScene', { x: 500, y: 500 }, 'Back to Village');

        // Gate (Visual Blockade) at x=5 tiles
        this.createGate(5 * 64, 7.5 * 64);

        // NPCs
        if (data.objects?.npcs) {
            data.objects.npcs.forEach((npcData: any) => {
                const texture = this.textures.exists(npcData.texture) ? npcData.texture : SPRITE_KEYS.BOSS_MIRROR; // Fallback
                const npc = new NPC(this, npcData.x, npcData.y, texture, npcData.dialogue || "...", npcData.frame);
                this.physics.add.collider(this.player, npc);
                this.registerInteractable(npc);

                this.leela = npc;
                this.overrideLeelaInteraction();
            });
        }

        // UI
        this.setupUI();

        // Intro
        if (!SaveManager.isLevelCompleted('Level5')) {
            LevelLoader.playIntroCutscene(this, data);
        }
    }

    private createGate(x: number, y: number) {
        // Create a vertical barrier
        this.gate = this.physics.add.image(x, y, 'tile_sheet', 2); // Wall tile
        this.gate.setScale(1, 15); // Stretched vertically
        this.gate.setImmovable(true);
        this.gate.setTint(0x555555);
        this.physics.add.collider(this.player, this.gate);
    }

    private overrideLeelaInteraction() {
        if (!this.leela) return;

        this.leela.speak = async () => {
            if (this.isGateOpen) {
                await this.showDialogue(this.leela!, "Go on, deal with him. He's crazy.");
                return;
            }

            if (SaveManager.hasItem("Toddy")) {
                this.startCutscene();
                await this.showDialogue(this.leela!, "Ooh! Is that Fresh Toddy? From Damu's shop?");
                await this.showDialogue(this.leela!, "Okay, you can pass. But don't tell George.");

                this.showConfirmationDialogue("FINAL BATTLE", "Once you step forward, there's no going back.\nAre you ready?", 
                    () => {
                        this.openGate();
                        if (this.exitLink) {
                            this.exitLink.body.enable = false;
                            this.exitLink.setVisible(false);
                            // Hide the label attached to it if we can find it.
                        }
                        if (this.hubBtnRef && !this.customData) {
                            this.hubBtnRef.setAlpha(0.4).disableInteractive();
                        }
                        this.endCutscene();
                    },
                    () => {
                        this.endCutscene(); // Canceled
                    }
                );
                return;
            }

            this.startCutscene();
            // Shout & Pushback
            await this.showDialogue(this.leela!, "Nillu! Where are you going? ERANGI PODA!");
            await this.showDialogue(this.leela!, "This bridge is closed! Unless you have something to drink...");

            // Pushback Effect
            const angle = Phaser.Math.Angle.Between(this.leela!.x, this.leela!.y, this.player.x, this.player.y);
            this.player.setVelocity(Math.cos(angle) * 600, Math.sin(angle) * 600);
            this.cameras.main.shake(200, 0.02);
            this.sound.play(AUDIO_KEYS.HARD_PUNCH); // Impact sound

            await this.showDialogue(this.player!, "I need to find some Toddy... Maybe Damu in the Village has some?", 2000);
            this.endCutscene();
        };
    }

    private openGate() {
        this.isGateOpen = true;
        if (this.gate) {
            this.tweens.add({
                targets: this.gate,
                alpha: 0,
                y: this.gate.y - 1000,
                duration: 2000,
                onComplete: () => {
                    this.gate?.destroy();
                    const data = this.customData || LEVEL5_DATA;
                    const bossData = data.objects?.boss;
                    if (bossData) {
                        this.spawnGeorge(bossData);
                    }
                }
            });
            this.sound.play(AUDIO_KEYS.EXPLOSION, { volume: 0.5 }); // Replaced RUMBLE
        }
    }

    private spawnGeorge(b: any) {
        this.george = new Saajan(this, b.x, b.y, this.player, b.texture, b.frame);
        this.george.setScale(1.3);
        this.george.setTint(0x333333);
        (this.george as any).health = 20;
        (this.george as any).maxHealth = 20;
        (this.george as any).isInvulnerable = true;

        this.startCutscene();
        this.showDialogue(this.george!, "Simply walking through my area?").then(() => {
            return this.showDialogue(this.player, "Bro, move. I need to find Shibu.");
        }).then(() => {
            return this.showDialogue(this.george!, "Give me a fight. Then go.");
        }).then(() => {
            this.endCutscene();
            (this.george as any).isInvulnerable = false;
            (this.george as any).speed = 40;
        });

        // Combat Group Setup
        const combatGroup = this.physics.add.group();
        combatGroup.add(this.george);
        this.player.setCombatTargets(combatGroup);

        // Collision Logic
        if (this.groundLayer && this.george) this.physics.add.collider(this.george, this.groundLayer);
        if (this.george) this.physics.add.collider(this.player, this.george);

        if (this.george) this.physics.add.overlap(this.player, this.george, () => {
            // ... existing collision logic ...
            if (this.george && this.george.active && !this.player.isDashingState) {
                this.player.takeDamage(10);
                const angle = Phaser.Math.Angle.Between(this.george!.x, this.george!.y, this.player.x, this.player.y);
                this.player.setVelocity(Math.cos(angle) * 800, Math.sin(angle) * 800);
                this.cameras.main.shake(100, 0.05);
            } else if (this.player.isDashingState && this.george) {
                if (this.player.isRageMode) {
                    this.george.takeDamage(5);
                    this.sound.play(AUDIO_KEYS.PUNCH);
                    this.george.setTint(0xff0000);
                    this.time.delayedCall(100, () => this.george?.setTint(0x333333));
                } else {
                    this.sound.play('metal_clank');
                    const txt = this.add.text(this.george.x, this.george.y - 60, "IMMUNE! USE RAGE!", {
                        fontSize: '12px', color: '#ff0000', stroke: '#000000', strokeThickness: 4
                    }).setOrigin(0.5);
                    this.tweens.add({ targets: txt, y: txt.y - 50, alpha: 0, duration: 800, onComplete: () => txt.destroy() });
                }
            }
        });
    }

    update(time: number, delta: number) {
        super.update(time, delta);

        if (this.george && this.george.active) {
            this.george.update();
            if ((this.george as any).health <= 0) {
                this.handleVictory();
            }
        }

        // Rotate portal effect if it exists
        if (this.portalEffect) {
            this.portalEffect.rotation += 0.05;
        }
    }

    private portalEffect: Phaser.GameObjects.Shape | Phaser.GameObjects.Sprite | null = null;

    private handleVictory() {
        if (this.isCutscenePlaying) return;
        this.startCutscene();

        // --- SCENE 1: THE VILLAGE JUNCTION (Post-Battle) ---
        this.sound.stopAll();

        // 1. Defeat George Animation
        if (this.george) {
            // George Kneels
            this.tweens.add({ targets: this.george, alpha: 1, scale: 1.3, duration: 500 }); // Restore scale/alpha if it was fading
            // Note: In a real implementation, we'd play a 'kneel' animation.
        }

        // Dialogue
        this.time.delayedCall(1000, async () => {
            await this.showDialogue(this.player, "It's over, George. The chaos ends now.");

            // George: Adjusts collar (imagined)
            await this.showDialogue(this.george!, "Alright, alright. You made your point.");
            await this.showDialogue(this.george!, "But look at us... we look epic.");

            // Smartphone out
            await this.showDialogue(this.george!, "First... lemme take a selfie.");

            // Jaison sighs
            await this.showDialogue(this.player, "...");

            // SELFIE VISUAL
            const selfieTxt = this.add.text(this.player.x, this.player.y - 80, "TAKING SELFIE...", {
                fontSize: '16px', color: '#ffff00', fontStyle: 'italic', stroke: '#000', strokeThickness: 4
            }).setOrigin(0.5);

            this.cameras.main.flash(200, 255, 255, 255);
            await new Promise(r => this.time.delayedCall(1000, r));
            this.cameras.main.flash(200, 255, 255, 255);
            selfieTxt.setText("VICTORY?");
            await new Promise(r => this.time.delayedCall(1000, r));
            selfieTxt.destroy();

            // Disable George for next scene
            if (this.george) this.george.setVisible(false);


            // --- SCENE 2: THE WIDE WORLD ---
            // Music Change: Low Ominous Hum
            // this.sound.play(AUDIO_KEYS.HUM); // Assuming we have one, or just silence for now.

            const portalX = this.player.x + 600; // Further away
            const portalY = this.player.y;

            // Pan Camera High/Far
            this.cameras.main.pan((this.player.x + portalX) / 2, portalY, 2000, 'Power2');
            this.cameras.main.zoomTo(0.7, 2000);
            await new Promise(r => this.time.delayedCall(2000, r));

            // Portal Opens
            this.portalEffect = this.add.circle(portalX, portalY, 100, 0xffaa00);
            const swirl = this.add.circle(portalX, portalY, 120, 0x4b0082).setAlpha(0.6); // Dark energy

            this.tweens.add({ targets: this.portalEffect, scale: { from: 0, to: 2 }, duration: 2000, ease: 'Bounce' });
            this.tweens.add({ targets: swirl, scale: { from: 0, to: 2.5 }, duration: 2000, ease: 'Sine.easeInOut', yoyo: true, repeat: -1 });

            await new Promise(r => this.time.delayedCall(2000, r));


            // --- SCENE 3: THE PORTAL'S EDGE ---
            const shibu = this.add.sprite(portalX, portalY, SPRITE_KEYS.BOSS).setTint(0x5555ff); // Blue/Sad tint
            shibu.setFlipX(true); // Facing portal (away from Jaison)

            // Jaison runs closer
            this.player.play(SPRITE_KEYS.HERO + '-run', true);
            const jaisonStopX = portalX - 250;
            this.tweens.add({ targets: this.player, x: jaisonStopX, duration: 1500 });
            await new Promise(r => this.time.delayedCall(1500, r));
            this.player.anims.stop();
            this.player.setFrame(0);

            // Dialogue
            await this.showDialogue(this.player, "Shibu! Stop!");
            await new Promise(r => this.time.delayedCall(1000, r));

            // Shibu doesn't turn yet
            await this.showDialogue({ x: portalX, y: portalY } as any, "You're late, superhero.");

            await this.showDialogue(this.player, "Look around! The realities are collapsing.");
            await this.showDialogue(this.player, "Why are you doing this?");

            // Shibu turns
            shibu.setFlipX(false);
            await this.showDialogue({ x: portalX, y: portalY } as any, "Because this universe... it doesn't have her.");

            // --- INTERACTIVE CHOICE ---
            const choice = await this.showChoiceDialogue("HOW DO YOU RESPOND?", [
                { text: "This is wrong. People are suffering.", value: 'morality' },
                { text: "There had to be another way.", value: 'logic' },
                { text: "I know you're hurting. But this is madness.", value: 'empathy' }
            ]);

            // Branching Reply
            if (choice === 'morality') {
                await this.showDialogue({ x: portalX, y: portalY } as any, "Right and wrong... luxuries for those with nothing to lose.");
                await this.showDialogue({ x: portalX, y: portalY } as any, "If the world must burn to light my path back to Usha... let it burn.");
            } else if (choice === 'logic') {
                await this.showDialogue({ x: portalX, y: portalY } as any, "Another way? I searched every shadow. Prayed to every god.");
                await this.showDialogue({ x: portalX, y: portalY } as any, "Love isn't logical, Jaison. It's a desperate clawing at the dark.");
            } else {
                await this.showDialogue({ x: portalX, y: portalY } as any, "Madness? Perhaps. But isn't true love always a little mad?");
                await this.showDialogue({ x: portalX, y: portalY } as any, "If this devotion is madness, I pray I never become sane again.");
            }


            // --- SCENE 4: THE CLIMAX ---
            shibu.setFlipX(true); // Turns back to portal
            await this.showDialogue({ x: portalX, y: portalY } as any, "She's right there. I'm coming, Usha.");

            await this.showDialogue(this.player, "No! You don't know what's on the other side!");

            // Shibu steps in (fade out)
            this.tweens.add({ targets: shibu, alpha: 0.5, scale: 0.8, duration: 1000 });

            await this.showDialogue(this.player, "I can't let you do it!");

            // CHARGING STANCE (Shake)
            this.cameras.main.shake(500, 0.01);
            this.sound.play(AUDIO_KEYS.DASH); // Electricity sound placeholder

            // SPEAR SUMMON (Modified for Jaison logic)
            // 1. Get from Idol (Optional detail for flow: we can skip the run-back for pacing, or do it fast)
            // Script implies he just "uses telekinesis" to lift "scrap metal (A SPEAR)".
            // So I will just spawn it near him.

            const spear = this.add.sprite(this.player.x, this.player.y - 60, SPRITE_KEYS.SPEAR).setScale(0.8);
            spear.setAlpha(0);

            // 2. Catch
            this.tweens.add({ targets: spear, alpha: 1, y: this.player.y, x: this.player.x + 20, rotation: 0.2, duration: 300, ease: 'Back.out' });
            await new Promise(r => this.time.delayedCall(400, r));

            // 3. THROW
            this.sound.play(AUDIO_KEYS.TK_THROW);
            this.tweens.add({
                targets: spear,
                x: portalX,
                y: portalY,
                rotation: 1.5,
                duration: 300, // Fast
                ease: 'Power2',
                onComplete: () => { spear.destroy(); }
            });

            // Shibu fully enters
            shibu.destroy();

            // SCREEN BLACK
            const blackScreen = this.add.rectangle(this.cameras.main.midPoint.x, this.cameras.main.midPoint.y, 2000, 2000, 0x000000).setDepth(4000);

            // THUD
            await new Promise(r => this.time.delayedCall(200, r)); // Millisecond delay
            this.sound.play(AUDIO_KEYS.HARD_PUNCH, { volume: 2.0 }); // Wet THUD

            // SCREAM
            await new Promise(r => this.time.delayedCall(500, r));
            this.sound.play(AUDIO_KEYS.EXPLOSION, { volume: 1.0 }); // SCREAM

            await new Promise(r => this.time.delayedCall(2000, r));


            // --- SCENE 5: THE AFTERMATH ---
            blackScreen.destroy();

            // Portal Gone
            this.portalEffect?.destroy();
            swirl.destroy();

            // Jaison Frozen
            this.player.setFrame(0); // Idle/Frozen

            await this.showDialogue(this.player, "...Usha?");

            // Wind Howls
            // this.sound.play('wind'); 

            await new Promise(r => this.time.delayedCall(2000, r));

            // PLAY UYIRE & FADE
            this.sound.stopAll();
            this.sound.play(AUDIO_KEYS.UYIRE, { volume: 1.0, loop: true });

            // FADE TO BLACK AND CREDITS
            this.cameras.main.fadeOut(1000, 0, 0, 0);
            this.cameras.main.once('camerafadeoutcomplete', () => {
                this.endCutscene();
                SaveManager.markLevelCompleted('Level5');
                this.showVictory("TO BE CONTINUED...", 'CreditsScene');
            });
        });
    }
}
