import Phaser from 'phaser';
import { PLAYER, SPRITE_KEYS, AUDIO_KEYS } from '../config';
import { AVATAR_ASSETS, type AvatarConfig } from '../config/AvatarAssets';
import SaveManager from '../managers/SaveManager';
import type { KeyBindings } from '../types/GameInterfaces';
import VisualEffectManager from '../utils/VisualEffectManager';

export type MovementMode = 'normal' | 'clumsy' | 'cutscene';

export default class Player extends Phaser.Physics.Arcade.Sprite {
    private cursors!: Phaser.Types.Input.Keyboard.CursorKeys;
    private maxSpeed: number = PLAYER.MAX_SPEED;

    public health: number = PLAYER.STARTING_HEALTH;
    public maxHealth: number = PLAYER.MAX_HEALTH;
    private healthBar!: Phaser.GameObjects.Graphics;

    private dashKey!: Phaser.Input.Keyboard.Key;
    private tkKey!: Phaser.Input.Keyboard.Key;
    private punchKey!: Phaser.Input.Keyboard.Key;
    private spellKey!: Phaser.Input.Keyboard.Key;
    private jumpKey!: Phaser.Input.Keyboard.Key;

    public money: number = PLAYER.STARTING_MONEY;
    private isInvincible: boolean = false;

    // Movement Physics
    private accelerationRate: number = 600;
    private dragRate: number = 1000;

    private movementMode: MovementMode = 'normal';
    private telekinesisTargets: Phaser.Physics.Arcade.Group | null = null;
    private heldObject: Phaser.Physics.Arcade.Sprite | null = null;
    private lastDirection: string = 'down';

    private isDashing: boolean = false;
    private lastDashTime: number = 0;
    private dashCooldown: number = PLAYER.DASH_COOLDOWN;

    private isAttacking: boolean = false;
    private combatTargets: Phaser.Physics.Arcade.Group | null = null;
    private lastStepTime: number = 0;

    private moveStartTime: number = 0;
    private isJumping: boolean = false;

    // Avatar Layers
    private layers: { [key: string]: Phaser.GameObjects.Sprite } = {};
    private currentAvatar: any = null;

    constructor(scene: Phaser.Scene, x: number, y: number, texture: string, scale: number = 0.4) {
        super(scene, x, y, texture);
        scene.add.existing(this);
        scene.physics.add.existing(this);
        this.setCollideWorldBounds(true);
        this.setScale(scale);
        if (scene.input.keyboard) {
            this.cursors = scene.input.keyboard.createCursorKeys();
        }
        // Foot-only hitbox for isometric walk precision.
        // Sprite is 256×256 at scale 0.4 → feet land at world y+36 to y+50.
        // Unscaled: width=90, height=35, offsetX=(256-90)/2=83, offsetY=256-35-3=218
        this.body!.setSize(90, 35);
        this.body!.setOffset(83, 218);
        this.setPushable(false);
        this.initAnimations();
        this.setupLayers();
        this.loadAvatar();
    }

    private setupLayers() {
        const layerNames = ['hair', 'shirt', 'pants', 'shoes', 'armor', 'weapon', 'hat'];
        layerNames.forEach(layer => {
            const sprite = this.scene.add.sprite(this.x, this.y, this.texture.key);
            sprite.setScale(this.scale);
            sprite.setDepth(this.depth + 1);
            this.layers[layer] = sprite;
        });
    }

    private loadAvatar() {
        const state = SaveManager.load() || SaveManager.getInitialState();
        if (state?.avatar) {
            this.updateAppearance(state.avatar);
        }
    }

    public updateAppearance(config: Partial<AvatarConfig>) {
        this.currentAvatar = config;

        // Update Base Body Skin/Texture if changed
        if (config.skin) {
            const skinAsset = AVATAR_ASSETS.find(a => a.id === config.skin);
            if (skinAsset && skinAsset.texture && this.texture.key !== skinAsset.texture) {
                this.setTexture(skinAsset.texture);
                this.initAnimations(); // Re-initialize anim keys for new texture
            }
        }

        Object.entries(this.layers).forEach(([name, sprite]) => {
            const assetId = (config as any)[name];
            const asset = AVATAR_ASSETS.find(a => a.id === assetId);

            if (!asset || asset.id.includes('none') || !asset.texture) {
                sprite.setVisible(false);
            } else {
                // Check if layer is redundant (using same full-sheet as base)
                const fullCharSheets = [SPRITE_KEYS.PLAYER, SPRITE_KEYS.HERO, 'saajan', 'dasan', 'boss'];
                const isRedundant = fullCharSheets.includes(asset.texture) && asset.texture === this.texture.key;

                sprite.setVisible(!isRedundant);
                sprite.setTexture(asset.texture);
                // Apply colors if applicable
                if (name === 'hair') {
                    sprite.setTint(config.hairColor || 0xffffff);
                } else {
                    sprite.clearTint();
                }
            }
        });
    }

    private initAnimations() {
        const anims = this.scene.anims;

        const setupSpriteAnims = (key: string, mirrorKey: string) => {
            // IDLE ANIMATIONS
            anims.create({ key: `${key}-idle-down`, frames: [{ key: key, frame: 0 }], frameRate: 1, repeat: -1 });
            anims.create({ key: `${key}-idle-up`, frames: [{ key: key, frame: 5 }], frameRate: 1, repeat: -1 });
            anims.create({ key: `${key}-idle-right`, frames: [{ key: key, frame: 10 }], frameRate: 1, repeat: -1 });
            anims.create({ key: `${key}-idle-left`, frames: [{ key: mirrorKey, frame: 10 }], frameRate: 1, repeat: -1 });

            // WALK FRONT/BACK (Row 1, Frame 1-7) -> 0-6
            anims.create({ key: `${key}-walk-down`, frames: anims.generateFrameNumbers(key, { start: 1, end: 4 }), frameRate: 12, repeat: -1 });
            anims.create({ key: `${key}-walk-up`, frames: anims.generateFrameNumbers(key, { start: 5, end: 6 }), frameRate: 12, repeat: -1 });

            // WALK SIDE RIGHT (Row 2, Frame 11-19) -> 10-18
            anims.create({ key: `${key}-walk-right`, frames: anims.generateFrameNumbers(key, { start: 14, end: 17 }), frameRate: 12, repeat: -1 });
            // WALK SIDE LEFT (Row 2, Mirror Frame 19-11) -> 18 to 10 reversed? User pattern
            anims.create({ key: `${key}-walk-left`, frames: anims.generateFrameNumbers(mirrorKey, { start: 17, end: 14 }), frameRate: 12, repeat: -1 });

            // RUN RIGHT (Row 4, Frame 31-33) -> 30-32
            anims.create({ key: `${key}-run-right`, frames: anims.generateFrameNumbers(key, { start: 30, end: 32 }), frameRate: 15, repeat: -1 });
            anims.create({ key: `${key}-run-left`, frames: anims.generateFrameNumbers(mirrorKey, { start: 39, end: 37 }), frameRate: 15, repeat: -1 });

            // PUNCH (Row 3, Frame 21-27) -> 20-26
            anims.create({ key: `${key}-punch-right`, frames: anims.generateFrameNumbers(key, { start: 20, end: 27 }), frameRate: 15 });
            anims.create({ key: `${key}-punch-left`, frames: anims.generateFrameNumbers(mirrorKey, { start: 29, end: 22 }), frameRate: 15 });

            // PICK/THROW (Row 4, Frame 34-39) -> 33-38
            anims.create({ key: `${key}-pick-right`, frames: anims.generateFrameNumbers(key, { start: 33, end: 36 }), frameRate: 12 });
            anims.create({ key: `${key}-pick-left`, frames: anims.generateFrameNumbers(mirrorKey, { start: 37, end: 35 }), frameRate: 12 });
            anims.create({ key: `${key}-throw-right`, frames: anims.generateFrameNumbers(key, { start: 38, end: 39 }), frameRate: 12 });
            anims.create({ key: `${key}-throw-left`, frames: anims.generateFrameNumbers(mirrorKey, { start: 31, end: 30 }), frameRate: 12 });

            // PSYCHIC BURST (Row 7 and 8) -> 60-79
            anims.create({ key: `${key}-burst-right`, frames: anims.generateFrameNumbers(key, { start: 80, end: 89 }), frameRate: 20 });
            anims.create({ key: `${key}-burst-left`, frames: anims.generateFrameNumbers(mirrorKey, { start: 90, end: 80 }), frameRate: 20 });

            // JUMP (Row 5) -> 40-43
            anims.create({ key: `${key}-jump-right`, frames: anims.generateFrameNumbers(key, { start: 70, end: 77 }), frameRate: 12 });
            anims.create({ key: `${key}-jump-left`, frames: anims.generateFrameNumbers(mirrorKey, { start: 79, end: 72 }), frameRate: 12 });

            // HIT/FALL (Row 5 to 7) -> 40 to 69
            anims.create({ key: `${key}-hit-right`, frames: anims.generateFrameNumbers(key, { start: 59, end: 56 }), frameRate: 12 });
            anims.create({ key: `${key}-hit-left`, frames: anims.generateFrameNumbers(mirrorKey, { start: 50, end: 53 }), frameRate: 12 });
            anims.create({ key: `${key}-fall-right`, frames: anims.generateFrameNumbers(key, { start: 45, end: 44 }), frameRate: 12 });
            anims.create({ key: `${key}-fall-left`, frames: anims.generateFrameNumbers(mirrorKey, { start: 44, end: 45 }), frameRate: 12 });
        };

        setupSpriteAnims(SPRITE_KEYS.PLAYER, SPRITE_KEYS.PLAYER_MIRROR);
        setupSpriteAnims(SPRITE_KEYS.HERO, SPRITE_KEYS.HERO_MIRROR);
    }

    public setMovementMode(mode: MovementMode) {
        this.movementMode = mode;
        if (mode === 'clumsy') {
            this.maxSpeed = 300;
        } else {
            this.maxSpeed = 160;
        }
    }

    public setTelekinesisTargets(group: Phaser.Physics.Arcade.Group) {
        this.telekinesisTargets = group;
    }

    public canDash(): boolean {
        return !this.isDashing && (this.scene.time.now - this.lastDashTime >= this.dashCooldown);
    }

    public get isDashingState(): boolean {
        return this.isDashing;
    }

    public initInput(bindings?: Partial<KeyBindings>) {
        if (!this.scene.input.keyboard) return;
        this.punchKey = this.scene.input.keyboard.addKey(bindings?.ACTION_PUNCH || 'X');
        this.tkKey = this.scene.input.keyboard.addKey(bindings?.ACTION_TK || 'Z');
        this.dashKey = this.scene.input.keyboard.addKey(bindings?.ACTION_DASH || 'SPACE');
        this.spellKey = this.scene.input.keyboard.addKey(bindings?.ACTION_SPELL || 'R');
        this.jumpKey = this.scene.input.keyboard.addKey(bindings?.ACTION_JUMP || 'B');
        this.rageKey = this.scene.input.keyboard.addKey(bindings?.ACTION_RAGE || 'M');
        this.duckKey = this.scene.input.keyboard.addKey(bindings?.ACTION_DUCK || 'C');
    }

    private rageKey!: Phaser.Input.Keyboard.Key;
    private duckKey!: Phaser.Input.Keyboard.Key;
    public isDucking: boolean = false;
    private originalScaleY: number = 0.4;
    public isRageMode: boolean = false;
    private rageDuration: number = 10000; // 10 seconds
    // private lastRageTime: number = 0;
    public rageValue: number = 0; // 0-100
    private rageMax: number = 100;
    private isSlowed: boolean = false;
    private slowRatio: number = 1.0;

    public applySlowdown(ratio: number) {
        this.isSlowed = true;
        this.slowRatio = ratio;
    }

    update(_time: number, _delta: number) {
        // Reset slowdown each frame unless overlap continues
        this.isSlowed = false;
        this.slowRatio = 1.0;

        // We will apply the ratio in updateMovement
        // But we need to keep the ratio if overlap is still happening.
        // Actually, the overlap callback will fire AFTER update starts if we are lucky,
        // or we just assume it fires before updateMovement is called.
        // In Arcade physics, update comes first, then physics.
        // Wait, if I reset it in update(), the overlap callback (which happens in physics step)
        // will set it for the NEXT frame.
        // That's fine.
        if (!this.cursors) return;
        if (this.movementMode === 'cutscene') {
            this.setVelocity(0, 0);
            this.anims.stop();
            return;
        }

        this.updateCombat();
        if (this.isAttacking) return;

        if (Phaser.Input.Keyboard.JustDown(this.tkKey)) {
            if (this.heldObject) this.throwObject();
            else this.tryGrab();
        }

        if (Phaser.Input.Keyboard.JustDown(this.spellKey)) this.psychicBurst();
        if (Phaser.Input.Keyboard.JustDown(this.jumpKey)) this.jump();
        // Rage Trigger: JustDown(RageKey) OR (RageFull AND Swipe Up)
        const isSwipeUp = (this.scene.input.activePointer.isDown &&
            (this.scene.input.activePointer.velocity.y < -250)); // Simple swipe detection

        if (Phaser.Input.Keyboard.JustDown(this.rageKey) ||
            (this.rageValue >= this.rageMax && isSwipeUp)) {
            this.triggerRageMode();
        }

        // Ducking Logic
        if (this.duckKey.isDown && !this.isJumping) {
            this.duck();
        } else if (this.isDucking) {
            this.stopDucking();
        }

        if (this.isDucking) return; // Restrict movement/actions while ducking? Or just slow down?
        // For now, let's allow movement but slower/restricted if needed. 
        // Actually, preventing other actions is safer for the mechanic.

        if (this.heldObject) {
            if (!this.heldObject.active || !this.heldObject.body) {
                this.heldObject = null;
            } else {
                this.heldObject.setPosition(this.x, this.y - 32);
                this.heldObject.setVelocity(0, 0);
            }
        }

        if (Phaser.Input.Keyboard.JustDown(this.dashKey)) this.dash();
        if (this.isDashing) return;

        const up = this.cursors.up.isDown;
        const down = this.cursors.down.isDown;
        const left = this.cursors.left.isDown;
        const right = this.cursors.right.isDown;

        this.updateMovement(up, down, left, right);
    }

    public getAnimBaseKey(): string {
        // Returns 'jaison' or 'hero' based on texture key
        if (this.texture.key.includes('hero')) return SPRITE_KEYS.HERO;
        return SPRITE_KEYS.PLAYER;
    }

    public getLayers(): { [key: string]: Phaser.GameObjects.Sprite } {
        return this.layers;
    }

    public getHeldObject(): Phaser.Physics.Arcade.Sprite | null {
        return this.heldObject;
    }

    private playAnim(keySuffix: string, ignoreIfPlaying: boolean = true) {
        const key = `${this.getAnimBaseKey()}-${keySuffix}`;
        if (!this.scene.anims.exists(key)) return;

        const anim = this.scene.anims.get(key);
        if (!anim || !anim.frames || anim.frames.length === 0) return;
        const frame = anim.frames[0].frame;
        const textureKey = frame.texture.key;

        if (this.texture.key !== textureKey) {
            this.setTexture(textureKey);
        }

        this.anims.play(key, ignoreIfPlaying);

        // Sync layers - only visibility and basic sync
        Object.values(this.layers).forEach(layer => {
            if (layer.visible) {
                // We no longer call layer.play() because it forces the layer to use the player's texture.
                // Frame sync happens manually in preUpdate instead.
            }
        });
    }

    private updateMovement(up: boolean, down: boolean, left: boolean, right: boolean) {
        let ax = 0, ay = 0;
        let currentMaxSpeed = this.maxSpeed;

        const now = this.scene.time.now;
        if (up || down || left || right) {
            if (this.moveStartTime === 0) this.moveStartTime = now;
        } else {
            this.moveStartTime = 0;
        }

        const moveDuration = this.moveStartTime !== 0 ? now - this.moveStartTime : 0;
        const isRunning = moveDuration > 500;

        if (this.heldObject) currentMaxSpeed *= 0.6;

        if (left) ax = -this.accelerationRate;
        else if (right) ax = this.accelerationRate;
        if (up) ay = -this.accelerationRate;
        else if (down) ay = this.accelerationRate;

        if (isRunning && !this.heldObject && !this.isJumping) {
            currentMaxSpeed *= 1.8;
            ax *= 1.5;
            ay *= 1.5;
        }

        if (this.isJumping) currentMaxSpeed *= 1.8; // Allow faster movement during jump

        // Apply Slowdown (Jackfruit Gum)
        if (this.isSlowed) {
            currentMaxSpeed *= this.slowRatio;
            ax *= this.slowRatio;
            ay *= this.slowRatio;
        }

        this.setAcceleration(ax, ay);
        this.setDrag(this.dragRate);
        this.body!.velocity.limit(currentMaxSpeed);

        const velocity = this.body!.velocity;
        const speed = velocity.length();
        const isMoving = speed > 10;

        if (isMoving) {
            if (Math.abs(velocity.x) > Math.abs(velocity.y)) {
                this.lastDirection = velocity.x < 0 ? 'left' : 'right';
            } else {
                this.lastDirection = velocity.y < 0 ? 'up' : 'down';
            }

            let animPrefix = isRunning && (left || right) ? 'run' : 'walk';
            // Only play movement animations if not jumping
            if (!this.isJumping) {
                if (this.lastDirection === 'left' || this.lastDirection === 'right') {
                    this.playAnim(`${animPrefix}-${this.lastDirection}`, true);
                } else {
                    this.playAnim(`walk-${this.lastDirection}`, true);
                }
            }

            const now = this.scene.time.now;
            const speedRatio = Phaser.Math.Clamp(speed / this.maxSpeed, 0, 1);
            let interval = Phaser.Math.Linear(600, 250, speedRatio);
            if (now - this.lastStepTime > interval) {
                this.lastStepTime = now;
                if (this.scene.sound.get('walk')) this.scene.sound.play('walk', { volume: 0.3 });
                else this.scene.sound.play('dash', { rate: 3.0, volume: 0.1 });
            }
        } else {
            this.moveStartTime = 0;
            if (!this.isJumping) this.anims.stop();
            if (ax === 0 && ay === 0 && speed < 5) this.setVelocity(0);
        }
    }

    private tryGrab() {
        if (!this.telekinesisTargets) return;
        let closest: any = null;
        let minDist = 400;
        this.telekinesisTargets.getChildren().forEach((obj: any) => {
            const dist = Phaser.Math.Distance.Between(this.x, this.y, obj.x, obj.y);
            if (dist < minDist) { minDist = dist; closest = obj; }
        });
        if (closest && this.telekinesisTargets) {
            this.heldObject = closest;
            const animSuffix = this.lastDirection === 'left' ? 'left' : 'right';
            this.playAnim(`pick-${animSuffix}`);
            this.scene.sound.play(AUDIO_KEYS.TK_GRAB, { volume: 0.5 });
            if (this.heldObject && 'setHeld' in this.heldObject) (this.heldObject as any).setHeld(true);
        }
    }

    private throwObject() {
        if (!this.heldObject) return;
        const animSuffix = this.lastDirection === 'left' ? 'left' : 'right';
        this.playAnim(`throw-${animSuffix}`);
        this.scene.sound.play(AUDIO_KEYS.TK_THROW, { volume: 0.6 });
        if ('setHeld' in this.heldObject) (this.heldObject as any).setHeld(false);
        let vx = 0, vy = 0;
        if (this.lastDirection === 'left') vx = -1;
        else if (this.lastDirection === 'right') vx = 1;
        else if (this.lastDirection === 'up') vy = -1;
        else if (this.lastDirection === 'down') vy = 1;
        if (vx === 0 && vy === 0) vy = 1;

        // Spawn distance small enough to not clip through walls (64px)
        const spawnDist = 40;
        const worldWidth = this.scene.physics.world.bounds.width || 2000;
        const worldHeight = this.scene.physics.world.bounds.height || 2000;

        const targetX = Phaser.Math.Clamp(this.x + (vx * spawnDist), 32, worldWidth - 32);
        const targetY = Phaser.Math.Clamp(this.y + (vy * spawnDist), 32, worldHeight - 32);

        this.heldObject.setPosition(targetX, targetY);
        this.heldObject.setVelocity(vx * 1000, vy * 1000);
        this.heldObject = null;
    }

    private dash() {
        const now = this.scene.time.now;
        if (this.isDashing || now - this.lastDashTime < this.dashCooldown) return;
        this.lastDashTime = now;
        this.isDashing = true;
        let vx = 0, vy = 0;
        if (this.cursors.left.isDown) vx = -1; else if (this.cursors.right.isDown) vx = 1;
        if (this.cursors.up.isDown) vy = -1; else if (this.cursors.down.isDown) vy = 1;
        if (vx === 0 && vy === 0) {
            if (this.lastDirection === 'left') vx = -1; else if (this.lastDirection === 'right') vx = 1;
            else if (this.lastDirection === 'up') vy = -1; else if (this.lastDirection === 'down') vy = 1;
        }
        const vec = new Phaser.Math.Vector2(vx, vy).normalize().scale(500);
        this.setVelocity(vec.x, vec.y);
        this.playAnim(`dash`);
        this.setTint(0xffff66);
        this.scene.time.delayedCall(200, () => { this.isDashing = false; this.clearTint(); });
    }

    public takeDamage(amount: number) {
        if (this.isInvincible) return;
        this.health -= amount;
        this.isInvincible = true;
        const animSuffix = this.lastDirection === 'left' ? 'left' : 'right';
        this.playAnim(`hit-${animSuffix}`);
        this.scene.sound.play(AUDIO_KEYS.HARD_PUNCH, { volume: 0.8 });
        this.setTint(0xff0000);
        this.scene.time.delayedCall(1000, () => { this.isInvincible = false; this.clearTint(); });
    }

    public updateCombat() {
        if (!this.isAttacking && Phaser.Input.Keyboard.JustDown(this.punchKey)) this.punch();
    }

    public setCombatTargets(group: Phaser.Physics.Arcade.Group) {
        this.combatTargets = group;
    }

    public increaseStats() {
        this.maxSpeed = Math.max(this.maxSpeed, 250);
        this.maxHealth = Math.max(this.maxHealth, 10);
        this.health = Math.max(this.health, 10);
        this.accelerationRate = Math.max(this.accelerationRate, 1200);
    }

    private punch() {
        if (this.isAttacking || this.isJumping) return;
        this.isAttacking = true;
        this.setVelocity(0);
        let animSuffix = this.lastDirection === 'left' ? 'left' : 'right';
        this.playAnim(`punch-${animSuffix}`);
        this.scene.sound.play(AUDIO_KEYS.PUNCH, { volume: 0.5 });

        const offset = 80;
        let bx = this.x, by = this.y;
        if (this.lastDirection === 'left') bx -= offset;
        else if (this.lastDirection === 'right') bx += offset;
        else if (this.lastDirection === 'up') by -= offset;
        else if (this.lastDirection === 'down') by += offset;

        const hitbox = this.scene.add.rectangle(bx, by, 80, 80, 0xff0000, 0);
        this.scene.physics.add.existing(hitbox);

        if (this.combatTargets) {
            this.scene.physics.overlap(hitbox, this.combatTargets, (_h, target: any) => {
                if (target.takeDamage) {
                    const dmg = this.isRageMode ? (PLAYER.PUNCH_DAMAGE || 1) * 2 : (PLAYER.PUNCH_DAMAGE || 1);
                    target.takeDamage(dmg);
                    this.scene.cameras.main.shake(100, 0.01);
                    if (this.isRageMode) this.addRage(0); // Reset or maintain? usually adding rage only happens outside rage mode
                    else this.addRage(10); // Build rage on hit

                    VisualEffectManager.showOnomatopoeia(this.scene, target.x, target.y, Phaser.Math.RND.pick(['POW!', 'BAM!', 'DISHYUM']), 'impact');
                }
            });
        }

        this.scene.time.delayedCall(400, () => {
            this.isAttacking = false;
            hitbox.destroy();
        });
    }

    private psychicBurst() {
        if (this.isAttacking) return;
        this.isAttacking = true;
        const animSuffix = this.lastDirection === 'left' ? 'left' : 'right';
        this.playAnim(`burst-${animSuffix}`);
        this.scene.sound.play(AUDIO_KEYS.PSYCHIC_BURST, { volume: 0.7 });

        const burst = this.scene.add.circle(this.x, this.y, 20, 0xff00ff, 0.4);
        this.scene.tweens.add({ targets: burst, radius: 200, alpha: 0, duration: 800, onComplete: () => burst.destroy() });

        if (this.combatTargets) {
            this.combatTargets.getChildren().forEach((target: any) => {
                const dist = Phaser.Math.Distance.Between(this.x, this.y, target.x, target.y);
                if (dist < 200) {
                    if (target.takeDamage) target.takeDamage(3);
                    VisualEffectManager.showOnomatopoeia(this.scene, target.x, target.y, 'BZZZT!', 'special' as any);
                }
            });
        }

        this.scene.time.delayedCall(1000, () => { this.isAttacking = false; });
    }

    private jump() {
        if (this.isJumping || this.isAttacking) return;
        this.isJumping = true;

        const moveDuration = this.scene.time.now - this.moveStartTime;
        const isRunning = this.moveStartTime !== 0 && moveDuration > 500;

        // Dynamic jump properties
        const jumpHeight = isRunning ? 60 : 30;
        const jumpDuration = isRunning ? 500 : 300;
        const velocityBoost = isRunning ? 1.5 : 1.1;

        // Apply a horizontal leap boost
        this.body!.velocity.scale(velocityBoost);

        const animSuffix = this.lastDirection === 'left' ? 'left' : 'right';
        this.playAnim(`jump-${animSuffix}`);

        // Visual Hop
        const originalScale = this.scaleX;
        this.scene.tweens.add({
            targets: this,
            scaleX: originalScale * 1.3,
            scaleY: originalScale * 1.3,
            y: this.y - jumpHeight,
            duration: jumpDuration / 2,
            yoyo: true,
            ease: 'Power1',
            onComplete: () => {
                this.isJumping = false;
                this.setScale(originalScale);
                this.playAnim(`walk-${this.lastDirection}`);
            }
        });

        // Invincibility during jump
        const wasInvincible = this.isInvincible;
        this.isInvincible = true;
        this.scene.time.delayedCall(jumpDuration, () => {
            this.isInvincible = wasInvincible;
        });
    }

    public heal(amount: number) {
        this.health = Math.min(this.health + amount, this.maxHealth);
        this.updateHealthBar();
    }

    public updateHealthBar() {
        if (this.movementMode === 'cutscene') {
            if (this.healthBar) this.healthBar.setVisible(false);
            return;
        }
        if (!this.healthBar) { this.healthBar = this.scene.add.graphics().setDepth(100); }
        this.healthBar.clear();
        const w = 60, h = 6, x = this.x - w / 2, y = this.y + 50;
        this.healthBar.fillStyle(0x000000, 0.7).fillRect(x, y, w, h);
        const pct = Phaser.Math.Clamp(this.health / this.maxHealth, 0, 1);
        this.healthBar.fillStyle(pct > 0.5 ? 0x00ff00 : 0xff0000, 1).fillRect(x + 1, y + 1, (w - 2) * pct, h - 2);
    }

    private rageBar!: Phaser.GameObjects.Graphics;

    public updateRageBar() {
        if (this.movementMode === 'cutscene') {
            if (this.rageBar) this.rageBar.setVisible(false);
            return;
        }
        if (!this.rageBar) { this.rageBar = this.scene.add.graphics().setDepth(100); }
        this.rageBar.clear();

        // Show bar only if there is rage or in rage mode
        if (this.rageValue <= 0 && !this.isRageMode) return;

        const w = 60, h = 4, x = this.x - w / 2, y = this.y + 58; // Below health bar
        this.rageBar.fillStyle(0x000000, 0.7).fillRect(x, y, w, h);

        // If in Rage Mode, maybe show full bar draining? Or just empty? 
        // For now, standard fill
        const pct = Phaser.Math.Clamp(this.rageValue / this.rageMax, 0, 1);

        // Flashing effect if full
        const color = (pct >= 1 && this.scene.time.now % 200 < 100) ? 0xffffff : 0xFF4500;

        this.rageBar.fillStyle(color, 1).fillRect(x + 1, y + 1, (w - 2) * pct, h - 2);

        if (pct >= 1) {
            // Optional: Add "Ready" text? kept simple for now
        }
    }

    public addRage(amount: number) {
        if (this.isRageMode) return;
        this.rageValue = Math.min(this.rageValue + amount, this.rageMax);
    }

    private triggerRageMode() {
        if (this.isRageMode || this.rageValue < this.rageMax) return;

        this.isRageMode = true;
        this.rageValue = 0;
        this.updateRageBar(); // clear bar immediately
        // let lastRageTime = 0;this.scene.time.now;

        // Visuals
        this.setTint(0xff4500); // Orange-Red Rage Tint
        VisualEffectManager.showOnomatopoeia(this.scene, this.x, this.y - 50, 'MUNDU MADAKKI!', 'special' as any);
        this.scene.cameras.main.shake(1000, 0.05); // Longer, stronger shake
        this.scene.cameras.main.flash(500, 255, 69, 0); // Flash Orange

        // Audio: MASS Transformation
        // Stop current BGM if possible (would need ref to active BGM, but for now just overlay)
        this.scene.sound.stopAll(); // Big impact silence first? Or just mix. 
        // Better: Stop BGM, Play Chenda Melam
        this.scene.sound.play(AUDIO_KEYS.RAGE_THEME, { volume: 0.6, rate: 1.2, loop: true });

        // Play Intro Sound
        this.scene.sound.play(AUDIO_KEYS.POWERUP, { volume: 1.0 });

        // Logic - Speed and Protection are handled in update and takeDamage
        const originalSpeed = this.maxSpeed;
        this.maxSpeed *= 1.8; // Faster!

        this.scene.time.delayedCall(this.rageDuration, () => {
            this.isRageMode = false;
            this.clearTint();
            this.maxSpeed = originalSpeed;

            // Restore Audio
            this.scene.sound.stopByKey(AUDIO_KEYS.RAGE_THEME);
            this.scene.sound.play(AUDIO_KEYS.BGM, { volume: 0.3, loop: true });
        });
    }

    private duck() {
        if (this.isDucking) return;
        this.isDucking = true;
        this.originalScaleY = this.scaleY;
        this.setScale(this.scaleX, 0.2); // Squish
        // Foot-strip stays the same while ducking — feet don't lift
        this.body!.setSize(90, 35);
        this.body!.setOffset(83, 218);
    }

    private stopDucking() {
        if (!this.isDucking) return;
        this.isDucking = false;
        this.setScale(this.scaleX, this.originalScaleY); // Restore scale
        this.body!.setSize(90, 35);
        this.body!.setOffset(83, 218);
    }

    preUpdate(_time: number, _delta: number) {
        super.preUpdate(_time, _delta);
        this.updateHealthBar();
        this.updateRageBar();

        if (this.isRageMode) {
            // Afterimage Trail Effect
            if (this.scene.time.now % 100 < 20) { // Spawn every ~100ms
                const ghost = this.scene.add.sprite(this.x, this.y, this.texture.key, this.frame.name)
                    .setScale(this.scaleX, this.scaleY)
                    .setAlpha(0.6)
                    .setTint(0xffaa00); // Yellow-Orange Ghost

                this.scene.tweens.add({
                    targets: ghost,
                    alpha: 0,
                    duration: 300,
                    onComplete: () => ghost.destroy()
                });
            }
        }

        const isDamaged = this.tintTopLeft !== 0xffffff && !this.isRageMode; // Don't override rage tint

        // Sync layer positions, properties, and depth
        const layerOrder = ['hair', 'shirt', 'pants', 'shoes', 'armor', 'weapon', 'hat'];

        layerOrder.forEach((name, index) => {
            const layer = this.layers[name];
            if (!layer || !layer.visible) return;

            // Sync Depth with Order
            layer.setDepth(this.depth + 1 + (index * 0.1));

            let assetScale = 1;
            let assetOffsetX = 0;
            let assetOffsetY = 0;
            let asset: any = null;

            if (this.currentAvatar) {
                const assetId = (this.currentAvatar as any)[name];
                asset = AVATAR_ASSETS.find(a => a.id === assetId);
                if (asset) {
                    // Level Requirement Check
                    // Extract level number from scene key (e.g. 'Level1' -> 1)
                    // If parsing fails (e.g. 'MainMenu'), assume level 0 or handled elsewhere
                    const levelMatch = this.scene.scene.key.match(/Level(\d+)/);
                    if (levelMatch) {
                        const currentLevel = parseInt(levelMatch[1]);
                        // If asset requires a higher level than current, hide it
                        // UNLESS asset uses legacy level checking logic requested by user:
                        // "if levelRequired = 1, it should be available in all levels" -> implies base items
                        // "if an asset is level2, it should be available from level2 onwards not lower levels"
                        if (asset.levelRequired > currentLevel) {
                            layer.setVisible(false);
                            return; // Skip rendering
                        }
                    }

                    assetScale = asset.scale || 1;
                    assetOffsetX = asset.offsetX || 0;
                    assetOffsetY = asset.offsetY || 0;
                }
            }

            const finalScaleX = this.scaleX * assetScale;
            const finalScaleY = this.scaleY * assetScale;

            // Apply direction-aware offset
            const dirX = this.flipX ? -1 : 1;

            layer.setPosition(
                this.x + (assetOffsetX * dirX * Math.abs(this.scaleX)),
                this.y + (assetOffsetY * Math.abs(this.scaleY))
            );

            layer.setAlpha(this.alpha);
            layer.setFlipX(this.flipX);
            layer.setScale(finalScaleX, finalScaleY);

            // Handle Mirror Textures
            // If the player is using a mirror texture (facing left), try to use the mirror version of the asset
            const isPlayerMirror = this.texture.key.includes('mirror');
            let targetTexture = layer.texture.key;

            if (asset && asset.texture) {
                targetTexture = asset.texture;
                if (isPlayerMirror && this.scene.textures.exists(targetTexture + '_mirror')) {
                    targetTexture = targetTexture + '_mirror';
                }
            }

            if (layer.texture.key !== targetTexture) {
                layer.setTexture(targetTexture);
            }

            if (layer.texture.key !== '__WHITE' && layer.texture.key !== '') {
                try {
                    layer.setFrame(this.frame.name);
                } catch (e) { }
            }

            // Handle Tints
            if (isDamaged) {
                layer.setTint(this.tintTopLeft);
            } else {
                if (layer === this.layers.hair && this.currentAvatar?.hairColor) {
                    layer.setTint(this.currentAvatar.hairColor);
                } else {
                    layer.clearTint();
                }
            }
        });
    }
}
