import SaveManager from './SaveManager';

export const RESOURCES = {
    CURRENCY: 'rupees',
    REEL_FRAGMENT: 'reel_fragment'
} as const;

export default class ResourceManager {
    private static instance: ResourceManager;

    private constructor() { }

    static getInstance(): ResourceManager {
        if (!ResourceManager.instance) {
            ResourceManager.instance = new ResourceManager();
        }
        return ResourceManager.instance;
    }

    /**
     * Add currency (Rupees)
     */
    static addCurrency(amount: number) {
        const state = SaveManager.load() || SaveManager.getInitialState();
        state.money = (state.money || 0) + amount;
        SaveManager.save({ money: state.money });
        return state.money;
    }

    /**
     * Spend currency
     * @returns true if successful, false if not enough funds
     */
    static spendCurrency(amount: number): boolean {
        const state = SaveManager.load() || SaveManager.getInitialState();
        if (state.money >= amount) {
            state.money -= amount;
            SaveManager.save({ money: state.money });
            return true;
        }
        return false;
    }

    /**
     * Get current currency balance
     */
    static getCurrency(): number {
        const state = SaveManager.load();
        return state?.money || 0;
    }

    /**
     * Collect a Reel Fragment for a specific level/zone
     */
    static collectReelFragment(levelId: string) {
        const state = SaveManager.load() || SaveManager.getInitialState();

        // Initialize inventory/collectibles if needed
        // For now, we'll store them in a specific 'reelFragments' array in flags or a new property
        // Let's use flags for flexibility first to avoid interface breaking changes immediately
        const flags = state.flags || {};

        if (!flags.reelFragments) {
            flags.reelFragments = [];
        }

        if (!flags.reelFragments.includes(levelId)) {
            flags.reelFragments.push(levelId);
            SaveManager.save({ flags: flags });
            return true;
        }
        return false;
    }

    /**
     * Check if a Reel Fragment is collected
     */
    static hasReelFragment(levelId: string): boolean {
        const state = SaveManager.load();
        const flags = state?.flags || {};
        return flags.reelFragments?.includes(levelId) || false;
    }

    /**
     * Get total count of collected fragments
     */
    static getReelFragmentCount(): number {
        const state = SaveManager.load();
        return state?.flags?.reelFragments?.length || 0;
    }
}
