
import Phaser from 'phaser';
import BaseLevel from './BaseLevel';
import SaveManager from '../managers/SaveManager';
import LevelLoader from '../utils/LevelLoader';
import { LEVEL4_DATA } from '../config/Level4Data';
import { AUDIO_KEYS } from '../config';
import TranslationManager from '../utils/TranslationManager';
import { SPRITE_KEYS, OBJECT_FRAMES } from '../config/AssetFrames';

export default class Level4 extends BaseLevel {
    private isGameWon: boolean = false;
    private obstacleGroup!: Phaser.Physics.Arcade.Group;
    private tkGroup!: Phaser.Physics.Arcade.Group;
    private nextSpawnX: number = 0;
    private ksrtcBus!: Phaser.GameObjects.Sprite;
    private midGameTriggered: boolean = false;
    private lorry!: Phaser.GameObjects.Sprite;
    private speedLines!: Phaser.GameObjects.Group;

    constructor() {
        super('Level4', 'Level 4: KSRTC Escape');
    }

    preload() {
        super.preload();
        LevelLoader.preloadCustomAssets(this, this.customData || LEVEL4_DATA);
        // Force load the KSRTC Lorry sprite here to be sure
        this.load.spritesheet(SPRITE_KEYS.KSRTC_LORRY, '/assets/KSRTC-LORRI.png', {
            frameWidth: 768,
            frameHeight: 512
        });
    }

    create() {
        super.create();
        const data = this.customData || LEVEL4_DATA;

        // Play music (Intense drumming placeholder)
        this.sound.play(AUDIO_KEYS.RAGE_THEME, { volume: 0.5, loop: true, rate: 1.2 });

        // Spawn player
        this.player = this.createPlayer(
            data.playerSpawn.x,
            data.playerSpawn.y,
            data.playerSpawn.texture
        );

        // World dimensions from data
        const mapW = data.map.width * data.map.tileWidth * data.map.tileScale;
        const mapH = data.map.height * data.map.tileHeight * data.map.tileScale;
        this.mapWidth = mapW;
        this.mapHeight = mapH;

        LevelLoader.setupBounds(this, data);

        // Camera Setup for Runner — offset left so player sees ahead
        this.cameras.main.startFollow(this.player, true, 0.1, 0.1, -200, 0);
        this.cameras.main.setBounds(0, 0, mapW, mapH);

        // Background image
        const bgKey = 'level_bg_texture_Level4';
        if (this.textures.exists(bgKey)) {
            this.add.image(0, 0, bgKey).setOrigin(0).setDepth(-20);
        }

        // Setup Obstacles
        this.setupObstacles();

        // Spawn KSRTC Bus (Chase) behind player
        this.ksrtcBus = this.add.sprite(this.player.x - 400, this.player.y, SPRITE_KEYS.KSRTC_LORRY, OBJECT_FRAMES.KSRTC_BUS);
        this.ksrtcBus.setScale(0.5);
        this.ksrtcBus.setDepth(500);
        this.ksrtcBus.setFlipX(false);
        this.ksrtcBus.play('ksrtc-drive');

        this.physics.add.existing(this.ksrtcBus);
        (this.ksrtcBus.body as Phaser.Physics.Arcade.Body).setAllowGravity(false);
        (this.ksrtcBus.body as Phaser.Physics.Arcade.Body).setImmovable(true);
        (this.ksrtcBus.body as Phaser.Physics.Arcade.Body).setSize(150, 100);

        // Player vs Obstacles
        this.physics.add.overlap(this.player, this.obstacleGroup, (_p, ob) => {
            this.handleObstacleHit(ob as Phaser.Physics.Arcade.Sprite);
        });

        // Bus vs Obstacles
        const handleCrush = (_bus: any, ob: any) => this.handleVehicleHitObstacle(ob);
        this.physics.add.overlap(this.ksrtcBus, this.obstacleGroup, handleCrush);
        this.physics.add.overlap(this.ksrtcBus, this.tkGroup, handleCrush);

        // Motion Blur Overlay
        this.add.rectangle(0, 0, this.scale.width, this.scale.height, 0x0000ff, 0.05)
            .setOrigin(0).setDepth(1000).setScrollFactor(0).setBlendMode(Phaser.BlendModes.ADD);

        // Speed Lines Group
        this.speedLines = this.add.group();
        for (let i = 0; i < 10; i++) {
            const line = this.add.rectangle(Math.random() * 800, Math.random() * 600, 100, 2, 0xffffff, 0.3)
                .setDepth(999).setScrollFactor(0);
            this.speedLines.add(line);
        }

        // Intro
        if (!SaveManager.isLevelCompleted('Level4')) {
            LevelLoader.playIntroCutscene(this, data);
        }

        this.nextSpawnX = this.player.x + 800;
    }

    private handleVehicleHitObstacle(obstacle: any) {
        if (!obstacle.active) return;
        this.createExplosion(obstacle.x, obstacle.y);
        obstacle.destroy();
        this.sound.play(AUDIO_KEYS.CRATE_BREAK, { volume: 0.3 });
    }

    private setupObstacles() {
        const data = this.customData || LEVEL4_DATA;
        this.obstacleGroup = this.physics.add.group();
        this.tkGroup = this.physics.add.group();
        this.player.setTelekinesisTargets(this.tkGroup);

        // Animations
        if (!this.anims.exists('ksrtc-drive')) {
            this.anims.create({
                key: 'ksrtc-drive',
                frames: this.anims.generateFrameNumbers(SPRITE_KEYS.KSRTC_LORRY, { start: 0, end: 1 }),
                frameRate: 10,
                repeat: -1
            });
        }
        if (!this.anims.exists('lorry-drive')) {
            this.anims.create({
                key: 'lorry-drive',
                frames: this.anims.generateFrameNumbers(SPRITE_KEYS.KSRTC_LORRY, { start: 2, end: 3 }),
                frameRate: 10,
                repeat: -1
            });
        }

        // Static Props as Obstacles
        if (data.objects?.props) {
            data.objects.props.forEach((prop: any) => {
                if (prop.collidable) {
                    const obs = this.physics.add.sprite(prop.x, prop.y, prop.texture, prop.frame);
                    obs.setImmovable(true);

                    // Fix "Big Crates" logic for static props too
                    if (prop.texture === 'tile_sheet' && prop.frame === 2) {
                        obs.setScale(0.15);
                        obs.setImmovable(false);
                        obs.setDrag(100);
                        obs.setDamping(true);
                        this.tkGroup.add(obs);
                    }

                    obs.body!.checkCollision.none = false;
                    this.obstacleGroup.add(obs);
                }
            });
        }
    }

    private handleObstacleHit(obstacle: Phaser.Physics.Arcade.Sprite) {
        // Ignore collision if this object is currently held by player
        if (this.player.getHeldObject() === obstacle) return;

        if (this.player.isDashingState) {
            // Dashing destroys obstacles
            this.createExplosion(obstacle.x, obstacle.y);
            obstacle.destroy();
            this.sound.play(AUDIO_KEYS.CRATE_BREAK, { volume: 0.5 });
        } else {
            // Hit!
            this.player.takeDamage(1);
            this.cameras.main.shake(100, 0.01);

            // Knockback
            this.player.setVelocityX(-200);

            // Destroy obstacle so we don't get stuck inside
            obstacle.setTint(0xff0000);
            this.tweens.add({
                targets: obstacle,
                alpha: 0,
                duration: 200,
                onComplete: () => obstacle.destroy()
            });
            this.sound.play(AUDIO_KEYS.EXPLOSION, { volume: 0.5 });
        }
    }

    private createExplosion(x: number, y: number) {
        const p = this.add.particles(x, y, 'tile_sheet', {
            frame: 2,
            speed: 100,
            lifespan: 500,
            quantity: 6,
            scale: { start: 0.3, end: 0 }
        });
        this.time.delayedCall(500, () => p.destroy());
    }

    protected setupUI() {
        super.setupUI(); // Call base UI (Health, etc)

        const data = this.customData || LEVEL4_DATA;
        if (data.ui?.objective) {
            this.add.text(16, 80, TranslationManager.translate(data.ui.objective), {
                fontSize: '20px',
                color: '#ffff00',
                stroke: '#000000',
                strokeThickness: 3
            }).setScrollFactor(0).setDepth(1000);
        }
    }

    update(time: number, delta: number) {
        super.update(time, delta);
        if (this.isCutscenePlaying || this.isGameWon) {
            this.player.setVelocityX(0);
            return;
        }

        // Auto-Run Mechanic: Disabled per user request
        // this.player.setVelocityX(this.runnerSpeed);

        // KSRTC Bus (Rear Chase) Logic
        if (this.ksrtcBus) {
            // Bus follows player from BEHIND (Left side)
            // It tries to catch up.

            // Bus continuously moves forward at a threatening pace
            const busSpeed = 220; // 220 px/second
            this.ksrtcBus.x += busSpeed * (delta / 1000);

            // Prevent the bus from falling too far behind if the player dashes way ahead
            if (this.ksrtcBus.x < this.player.x - 600) {
                this.ksrtcBus.x = this.player.x - 600; 
            }

            // Pothole Swerving Logic (Y-Axis)
            // Bus targets player's Y to try and hit them
            if (Math.random() < 0.02) {
                const targetLane = Phaser.Math.Between(3, 8);
                this.tweens.add({
                    targets: this.ksrtcBus,
                    y: targetLane * 64,
                    duration: 500,
                    ease: 'Sine.easeInOut'
                });
            }

            // Wobble
            this.ksrtcBus.y += Math.sin(time / 100) * 2;

            // Collision check
            const dist = Phaser.Math.Distance.Between(this.player.x, this.player.y, this.ksrtcBus.x, this.ksrtcBus.y);
            if (dist < 80) {
                this.player.takeDamage(1);
                const busVel = this.player.body ? this.player.body.velocity.x : 0;
                this.player.setVelocityX(busVel + 500); // Knockback forward
                this.cameras.main.shake(100, 0.01);
            }

            // Update Speed Lines
            this.speedLines.getChildren().forEach((line: any) => {
                line.x -= 20; // Move left fast
                if (line.x < -100) line.x = 900;
            });

            // Camera Motion Blur Wobble
            this.cameras.main.setLerp(0.1 + Math.sin(time / 50) * 0.02);
        }

        // Spawn procedural obstacles ahead
        this.handleSpawners();

        // Check Win Condition: Reach X > 95 * 64
        if (this.player.x > 95 * 64) {
            this.completeLevel();
        }

        // Check if fell off road (Y bounds)
        if (this.player.y < 0 || this.player.y > this.mapHeight) {
            this.player.setPosition(this.player.x - 200, 6 * 64);
            this.player.takeDamage(1);
        }

        // Climax Event Trigger
        // Trigger near end of map 
        // Map Width is roughly 15000 (from previous logs?) or calculate it?
        // tileWidth * width * scale??
        // Let's use a dynamic check: map.widthInPixels - 1000
        const endTriggerX = this.mapWidth - 1200;

        if (!this.midGameTriggered && this.player.x > endTriggerX) {
            this.triggerClimaxSequence();
        }
    }

    private handleSpawners() {
        const spawnDistance = 1000; // Distance ahead of player to spawn

        if (this.player.x + spawnDistance > this.nextSpawnX) {
            // Spawn an obstacle
            const y = Phaser.Math.Between(2, 9) * 64; // Random lane
            const obs = this.physics.add.sprite(this.nextSpawnX, y, 'tile_sheet', 2); // 'Crate'
            obs.setScale(0.15); // Much smaller (was default huge)
            // Allow TK to move it
            obs.setImmovable(false);
            obs.setDrag(100);
            obs.setDamping(true);
            this.obstacleGroup.add(obs);
            this.tkGroup.add(obs); // Add to TK group

            this.nextSpawnX += Phaser.Math.Between(400, 800);
        }

        // Cleanup old obstacles
        this.obstacleGroup.getChildren().forEach(c => {
            const obs = c as Phaser.Physics.Arcade.Sprite;
            if (obs.x < this.cameras.main.scrollX - 100) {
                obs.destroy();
            }
        });
    }

    private completeLevel() {
        if (this.isGameWon) return;
        this.isGameWon = true;
        this.startCutscene();

        const data = LEVEL4_DATA;

        this.time.delayedCall(500, async () => {
            if (data.cutscenes?.completion) {
                for (const step of data.cutscenes.completion.steps) {
                    if (step.type === 'dialogue') {
                        await this.showDialogue(this.player, step.text!, step.duration);
                    }
                }
            }

            this.endCutscene();
            SaveManager.markLevelCompleted('Level4');
            SaveManager.unlockLevel('Level5');
            SaveManager.save({
                currentLevel: 'HubScene',
                playerHealth: this.player.health,
                money: this.player.money,
                lastSaveTime: Date.now()
            });
            this.showVictory("KSRTC ESCAPED!");
        });
    }



    private async triggerClimaxSequence() {
        this.midGameTriggered = true; // Use same flag
        const data = LEVEL4_DATA;

        // Spawn Lorry AHEAD (Right) - Opposite Direction
        // Spawn slightly off-screen or just ahead
        const spawnX = this.player.x + 800;
        const spawnY = 6 * 64;

        this.lorry = this.add.sprite(spawnX, spawnY, SPRITE_KEYS.KSRTC_LORRY, OBJECT_FRAMES.LORRY);
        this.lorry.setDepth(501);
        this.lorry.setScale(0.5);
        this.lorry.setFlipX(false);
        this.lorry.play('lorry-drive');

        this.physics.add.existing(this.lorry);
        (this.lorry.body as Phaser.Physics.Arcade.Body).setAllowGravity(false);
        (this.lorry.body as Phaser.Physics.Arcade.Body).setImmovable(true);
        const handleCrush = (_lorry: any, ob: any) => this.handleVehicleHitObstacle(ob);
        this.physics.add.overlap(this.lorry, this.obstacleGroup, handleCrush);
        this.physics.add.overlap(this.lorry, this.tkGroup, handleCrush);

        // Stop Player
        this.startCutscene();

        // Bus also stops? or crashes?
        // Let's have Bus stop just as Lorry hits it.
        this.ksrtcBus.setTint(0xffffff);
        this.ksrtcBus.clearTint();

        // Lorry intercepts Bus - BRAKING STOP
        this.tweens.add({
            targets: this.lorry,
            x: this.ksrtcBus.x + 350, // Leave a gap!
            y: this.ksrtcBus.y,
            duration: 1500,
            ease: 'Power2.easeOut', // Brake feel
            onComplete: async () => {
                this.cameras.main.shake(100, 0.005); // Subtle shake
                this.ksrtcBus.stop(); // Stop animation
                this.lorry.stop(); // Stop animation

                // Spawn Aadu Thoma NPC
                // Use BOSS sprite as placeholder for Aadu Thoma
                const aaduThoma = this.add.sprite(this.lorry.x + 20, this.lorry.y + 20, SPRITE_KEYS.BOSS);
                aaduThoma.setDepth(502);
                aaduThoma.setScale(1.2);
                (this as any).aaduThoma = aaduThoma; // Expose for LevelLoader

                // --- RAY-BAN SPARKLE EFFECT ---
                if (this.cache.audio.exists(AUDIO_KEYS.COIN_COLLECT)) {
                    this.sound.play(AUDIO_KEYS.COIN_COLLECT, { volume: 0.8, rate: 2.0 }); // Sparkle sound
                }
                const sparkle = this.add.star(aaduThoma.x + 10, aaduThoma.y - 20, 5, 2, 10, 0xffffff)
                    .setDepth(510).setAlpha(0);
                this.tweens.add({
                    targets: sparkle,
                    alpha: 1,
                    scale: 2,
                    rotation: 3.14,
                    duration: 200,
                    yoyo: true,
                    onComplete: () => sparkle.destroy()
                });

                // Play climax dialogue
                if (data.cutscenes?.climax) {
                    for (const step of data.cutscenes.climax.steps) {
                        await LevelLoader['executeCutsceneStep'](this, step);
                    }
                }

                this.endCutscene();
                this.completeLevel(); // Level finishes after cutscene
            }
        });
    }
}
