import Phaser from 'phaser';
import BaseLevel from '../scenes/BaseLevel';
import type { DialogueTree } from '../config/LevelData';

export default class NPC extends Phaser.Physics.Arcade.Sprite {
    public dialogueTree?: DialogueTree;
    public mDialogue?: string;
    private dialogText: string;
    private isTalking: boolean = false;
    private dialogBox: Phaser.GameObjects.Text | null = null;

    constructor(scene: Phaser.Scene, x: number, y: number, texture: string, dialog: string, frame?: string | number) {
        super(scene, x, y, texture, frame);
        this.dialogText = dialog;

        scene.add.existing(this);
        scene.physics.add.existing(this);
        this.setImmovable(true);
        this.setScale(0.5);
        this.setDepth(100); // Ensure on top of background
    }

    async speak() {
        if (this.isTalking) return;
        this.isTalking = true;

        if (this.dialogueTree && this.scene instanceof BaseLevel) {
            await this.scene['showInteractiveDialogue'](this.dialogueTree);
            this.isTalking = false;
        } else {
            const x = this.x - 50;
            const y = this.y - 100;

            const baseLevel = this.scene as BaseLevel;
            // Falls back to BaseLevel's standard showDialogue if available, which handles translations
            if (this.scene instanceof BaseLevel) {
                await baseLevel['showDialogue'](this, this.dialogText, 3000, true, this.mDialogue);
            } else {
                // Simple fallback for other scenes
                this.dialogBox = this.scene.add.text(x, y, this.dialogText, {
                    fontSize: '16px', color: '#ffffff', backgroundColor: '#0000aa', padding: { x: 5, y: 5 }
                }).setDepth(100);
                this.scene.time.delayedCall(3000, () => this.closeDialog());
            }
            this.isTalking = false;
        }
    }

    closeDialog() {
        if (this.dialogBox) {
            this.dialogBox.destroy();
            this.dialogBox = null;
        }
        this.isTalking = false;
    }
}
