import Phaser from 'phaser';

export default class Extras extends Phaser.Scene {
    constructor() {
        super('Extras');
    }

    create() {
        const width = this.scale.width;
        const height = this.scale.height;

        this.add.rectangle(0, 0, width, height, 0x050510).setOrigin(0);

        this.add.text(width / 2, 100, "CREDITS", {
            fontFamily: 'Cinzel',
            fontSize: '64px',
            color: '#FFD700',
            stroke: '#000000',
            strokeThickness: 6
        }).setOrigin(0.5);

        const credits = [
            { role: "Developer", name: "Akhi M Balakrishnan & AI" },
            { role: "Lead Programmer", name: "Project Lightning" },
            { role: "Story & Design", name: "Basil Joseph, Arun Anirudhan and Justin Mathew" },
            { role: "Assets", name: "Phaser Community" },
            { role: "Special Thanks", name: "Minnal Murali Movie Team" }
        ];

        let y = 250;
        credits.forEach(c => {
            this.add.text(width / 2 - 20, y, c.role + ":", { fontSize: '24px', color: '#aaaaaa', align: 'right' }).setOrigin(1, 0.5);
            this.add.text(width / 2 + 20, y, c.name, { fontSize: '24px', color: '#ffffff', align: 'left' }).setOrigin(0, 0.5);
            y += 60;
        });

        // Level Editor Button
        const editorBtn = this.add.text(width / 2, y + 20, "🎨 LEVEL EDITOR", {
            fontFamily: 'Cinzel',
            fontSize: '28px',
            color: '#00ff00',
            stroke: '#000000',
            strokeThickness: 3
        }).setOrigin(0.5).setInteractive({ useHandCursor: true });

        editorBtn.on('pointerover', () => editorBtn.setScale(1.1).setColor('#ffff00'));
        editorBtn.on('pointerout', () => editorBtn.setScale(1).setColor('#00ff00'));
        editorBtn.on('pointerdown', () => {
            this.scene.start('EditorScene');
        });

        const backBtn = this.add.text(width / 2, height - 100, "BACK", {
            fontFamily: 'Cinzel',
            fontSize: '32px',
            color: '#FFD700'
        }).setOrigin(0.5).setInteractive({ useHandCursor: true });

        backBtn.on('pointerover', () => backBtn.setScale(1.1).setColor('#ffffff'));
        backBtn.on('pointerout', () => backBtn.setScale(1).setColor('#FFD700'));

        backBtn.on('pointerdown', () => {
            this.scene.start('MainMenu');
        });

        this.input.keyboard!.on('keydown-ESC', () => {
            this.scene.start('MainMenu');
        });

        // Floating particles
        this.add.particles(0, 0, 'tile_sheet', {
            frame: 1,
            x: { min: 0, max: width },
            y: { min: 0, max: height },
            speed: 20,
            scale: { start: 0.1, end: 0 },
            alpha: { start: 0.5, end: 0 },
            frequency: 100
        });
    }
}
