
import Phaser from 'phaser';
import Enemy from '../Enemy';
import { SPRITE_KEYS } from '../../config';

export default class SarojKumar extends Enemy {
    private slapCooldown: number = 3000;
    private lastSlapTime: number = 0;

    constructor(scene: Phaser.Scene, x: number, y: number, target: Phaser.Physics.Arcade.Sprite, texture: string = SPRITE_KEYS.SAROJ_KUMAR, frame?: string | number) {
        super(scene, x, y, texture, target, 'BOSS');
        if (frame !== undefined) this.setFrame(frame);

        this.isBoss = true;
        this.chaseSpeed = 100; // Slower, menacing walk
        this.attackCooldown = 2000;
        this.health = 25;
        this.maxHealth = 25;
        this.setScale(1.3);
        this.setTint(0xffd700); // Gold Suit tint

        // Physics
        this.setCollideWorldBounds(true);
        this.setDrag(1000);
        this.setBounce(0.1);
        this.setPushable(true);
    }

    protected initAnimations() {
        // Reuse basic animations or define specifics if assets existed
        // For now, relying on base class or simple frame updates
    }

    protected handleAttack() {
        if (!this.scene || !this.target || this.isAttacking || !this.active) return;
        const now = this.scene.time.now;

        // Special: Emotional Slap (AOE Stun)
        if (now - this.lastSlapTime > this.slapCooldown) {
            this.performEmotionalSlap();
            return;
        }

        const dist = Phaser.Math.Distance.Between(this.x, this.y, this.target.x, this.target.y);

        // Melee
        if (dist < 80 && now - this.lastAttackTime > this.attackCooldown) {
            this.performMeleeAttack();
            this.lastAttackTime = now;
        }
    }

    private performEmotionalSlap() {
        this.isAttacking = true;
        this.setVelocity(0, 0);
        this.setTint(0xff0000); // Warning Color

        // Telegraph
        const warningText = this.scene.add.text(this.x, this.y - 80, "EMOTIONAL...", { fontSize: '18px', color: '#ff0000', fontStyle: 'bold' }).setOrigin(0.5);
        this.scene.tweens.add({ targets: warningText, scale: 1.5, duration: 1000, onComplete: () => warningText.destroy() });

        this.scene.time.delayedCall(1000, () => {
            if (!this.active) return;

            // Execute Slap (Shockwave)
            this.setTint(0xffd700); // Back to Gold
            const wave = this.scene.add.circle(this.x, this.y, 10, 0xffff00, 0.5);
            this.scene.physics.add.existing(wave);

            this.scene.tweens.add({
                targets: wave,
                scale: 20, // Expands huge
                alpha: 0,
                duration: 500,
                onComplete: () => wave.destroy()
            });

            // Check collision manually or via physics
            const playerDist = Phaser.Math.Distance.Between(this.x, this.y, this.target!.x, this.target!.y);
            if (playerDist < 200) {
                // STUN PLAYER
                if ((this.target as any).stun) {
                    (this.target as any).stun(2000);
                    const stunnedText = this.scene.add.text(this.target!.x, this.target!.y - 50, "EMOTIONAL DAMAGE!", { fontSize: '14px', color: '#ffff00' }).setOrigin(0.5);
                    this.scene.tweens.add({ targets: stunnedText, y: stunnedText.y - 50, alpha: 0, duration: 1500 });
                }
            }

            this.lastSlapTime = this.scene.time.now;
            this.isAttacking = false;
        });
    }

    private performMeleeAttack() {
        this.isAttacking = true;
        // Simple lunge
        this.scene.physics.moveToObject(this, this.target!, 400);

        this.scene.time.delayedCall(300, () => {
            if (this.active) this.setVelocity(0, 0);
            this.isAttacking = false;
        });
    }

    protected die() {
        if (!this.active) return;
        this.emit('dead');
        this.setVelocity(0, 0);
        if (this.body) this.body.enable = false;
        this.setTint(0x555555);
    }
}
