import BaseLevel from './BaseLevel';
import SaveManager from '../managers/SaveManager';
import LevelLoader from '../utils/LevelLoader';
import { LEVEL1_DATA } from '../config/Level1Data';
import ResourceManager from '../managers/ResourceManager';
import Enemy from '../entities/Enemy';
import { SPRITE_KEYS, AUDIO_KEYS } from '../config';

export default class Level1 extends BaseLevel {
    private objectiveText!: Phaser.GameObjects.Text;
    private enemyGroup!: Phaser.Physics.Arcade.Group;
    private lightningFlash!: Phaser.GameObjects.Rectangle;

    // Logic flags
    private gafoorkaTriggered: boolean = false;
    private mapReceived: boolean = false;

    constructor() {
        super('Level1', 'Level 1: Strike From Shadows');
    }

    preload() {
        super.preload();
        // Preload custom assets defined in the level data
        LevelLoader.preloadCustomAssets(this, this.customData || LEVEL1_DATA);
    }

    create() {
        super.create();

        // Visual/structural data: use editor customData if available (collision, bounds, background)
        // Game-logic data: ALWAYS use canonical LEVEL1_DATA (player spawn, NPCs, exit zones)
        const data = this.customData || LEVEL1_DATA;
        const gameData = LEVEL1_DATA; // canonical — never overridden by editor

        // Play background music
        LevelLoader.playAudio(this, data);

        // Spawn player at canonical spawn — always override any saved position for Level1
        this.player = this.createPlayer(
            gameData.playerSpawn.x,
            gameData.playerSpawn.y,
            gameData.playerSpawn.texture
        );
        // Force position: createPlayer may override with saved posX/posY from localStorage
        this.player.setPosition(gameData.playerSpawn.x, gameData.playerSpawn.y);

        // Render background image (createTileLayers is not used, so display it directly)
        const bgKey = 'level_bg_texture_Level1';
        if (this.textures.exists(bgKey)) {
            this.add.image(0, 0, bgKey).setOrigin(0).setDepth(-20);
        }

        // Setup world and camera bounds (use data so editor bounds are respected)
        LevelLoader.setupBounds(this, data);

        // Create UI elements
        this.objectiveText = LevelLoader.createUI(this, data) as any;

        // Storm Atmosphere
        const worldW = data.map.width * data.map.tileWidth * data.map.tileScale;
        const worldH = data.map.height * data.map.tileHeight * data.map.tileScale;
        this.add.rectangle(0, 0, worldW, worldH, 0x000033, 0.4)
            .setOrigin(0).setDepth(100).setScrollFactor(1);

        this.lightningFlash = this.add.rectangle(0, 0, this.scale.width, this.scale.height, 0xffffff, 0)
            .setOrigin(0).setDepth(1000).setScrollFactor(0);

        // Handle intro cutscene or level link
        if (!SaveManager.isLevelCompleted('Level1')) {
            this.time.delayedCall(100, () => this.checkLogicFlags());
        }

        // Spawn visual/prop objects from editor data (excludes game-logic NPCs to avoid duplicates)
        const visualData = { ...data, objects: { ...data.objects, npcs: [] } };
        LevelLoader.spawnObjects(this, visualData);

        // Always spawn game-logic NPCs from canonical LEVEL1_DATA — guaranteed correct dialogue trees
        gameData.objects?.npcs?.forEach(npc => LevelLoader.spawnNPC(this, npc));

        // Create exit zone from canonical data — consistent trigger position
        LevelLoader.createExitZones(this, gameData, () => this.completeLevel());

        // Setup Combat/Enemies
        this.enemyGroup = this.physics.add.group({ runChildUpdate: true });
        this.physics.add.collider(this.player, this.enemyGroup);
        this.player.setCombatTargets(this.enemyGroup);

        // Check Flags Loop (Every 500ms)
        this.time.addEvent({
            delay: 500,
            loop: true,
            callback: () => this.checkLogicFlags()
        });

        // Initial check if already completed
        if (SaveManager.isLevelCompleted('Level1')) {
            this.openExit();
        }
    }

    protected endCutscene() {
        super.endCutscene();
        // Immediately check flags when any cutscene/dialogue ends — no 500ms wait
        this.checkLogicFlags();
    }

    private checkLogicFlags() {
        const state = SaveManager.load();
        if (!state || !state.flags) return;

        // 1. Gafoorka Aggro (Wrong Answer)
        if (state.flags['gafoorka_aggro'] && !this.gafoorkaTriggered && !this.isCutscenePlaying) {
            this.gafoorkaTriggered = true;
            this.triggerAmbush();
        }

        // 2. Map Received (Correct Answer)
        if (state.flags['received_map'] && !this.mapReceived && !this.isCutscenePlaying) {
            this.mapReceived = true;
            this.handleMapAcquisition();
        }
    }

    private triggerAmbush() {
        this.cameras.main.shake(300, 0.01);
        this.showProfessionalDialogue("Jaison", "Uh oh... bad choice!");

        // Spawn 2 Enemies
        const spawns = [{ x: 200, y: 1000 }, { x: 1300, y: 1150 }];
        spawns.forEach(pos => {
            const enemy = new Enemy(this, pos.x, pos.y, SPRITE_KEYS.HERO, this.player); // Using Hero as generic enemy texture for now if 'enemy' key missing
            // Or use 'nephew' as placeholder for thugs
            (enemy as any).setTexture(SPRITE_KEYS.NEPHEW);
            enemy.setTint(0xff0000); // Red tint for bad guys
            this.enemyGroup.add(enemy);
        });
    }

    private async handleMapAcquisition() {
        this.sound.play('level_won', { volume: 0.5 });

        // --- GLITCH REVEAL ---
        this.startCutscene();

        // Screen flicker violently
        this.tweens.add({
            targets: this.cameras.main,
            flashAlpha: 0.5,
            duration: 50,
            repeat: 10,
            yoyo: true,
            onStart: () => this.cameras.main.flash(500, 255, 0, 0) // Flash red
        });

        const gafoorka = (this as any).npcGroup?.getChildren()[0]; // Find Gafoorka NPC
        const speaker = gafoorka ? "Gafoorka" : "Jaison";
        await this.showProfessionalDialogue(speaker, "Jaison... WAKE UP! The Reel is burning! Break the Screen!");

        this.cameras.main.shake(500, 0.02);
        this.endCutscene();

        await this.showProfessionalDialogue("Jaison", "Got the map! Time to head to the Blockade.");

        // Open the exit path (Unlock Level 2)
        this.openExit();

        // Maybe create a visual item pickup?
        const mapItem = this.add.sprite(this.player.x, this.player.y - 50, 'tile_sheet', 3).setScale(0.5);
        this.tweens.add({
            targets: mapItem,
            y: mapItem.y - 50,
            alpha: 0,
            duration: 1500,
            onComplete: () => mapItem.destroy()
        });
    }

    private openExit() {
        // Always use canonical LEVEL1_DATA for exit zone coords — consistent in editor + real play
        LevelLoader.openExitPath(this, LEVEL1_DATA, {
            objectiveText: this.objectiveText,
            successMessage: 'OBJECTIVE: EXIT OPEN!',
            disableWorldCollision: 'down',
        });
    }

    private async completeLevel() {
        if (!SaveManager.isLevelCompleted('Level1') && !this.mapReceived) {
            await this.showProfessionalDialogue("Jaison", "I can't leave yet. I need that map from Gafoorka.");
            return;
        }

        // Award Reel Fragment
        const fragmentCollected = ResourceManager.collectReelFragment('Level1');

        SaveManager.markLevelCompleted('Level1');
        SaveManager.unlockLevel('Level2'); // Unlock next zone

        // Return to Hub instead of auto-next
        const nextScene = 'HubScene';

        SaveManager.save({
            currentLevel: nextScene,
            playerHealth: this.player ? this.player.health : 100,
            maxHealth: this.player ? this.player.maxHealth : 100,
            money: this.player ? this.player.money : 0,
            unlockedAbilities: (this.player as any)?.unlockedAbilities || [],
            lastSaveTime: Date.now()
        });

        if (fragmentCollected) {
            this.showVictory("REEL FRAGMENT RECOVERED!");
        } else {
            // Still create the exit portal even without the fragment
            this.createCompletionExit();
        }
    }

    update(time: number, delta: number) {
        super.update(time, delta);

        // Random Lightning
        if (Math.random() < 0.005) { // ~Every 3-4 seconds on average
            this.triggerLightning();
        }
    }

    private triggerLightning() {
        this.lightningFlash.setAlpha(0.6);
        this.sound.play(AUDIO_KEYS.EXPLOSION, { volume: 0.3, rate: 0.5 }); // Thunder

        this.tweens.add({
            targets: this.lightningFlash,
            alpha: 0,
            duration: 150,
            ease: 'Power2'
        });
    }
}


