
import BaseLevel from './BaseLevel';
import { SPRITE_KEYS, AUDIO_KEYS } from '../config';
import SaveManager from '../managers/SaveManager';
import LevelLoader from '../utils/LevelLoader';
import { RECORD_ROOM_DATA } from '../config/RecordRoomData';

export default class RecordRoomScene extends BaseLevel {
    private siSaajan!: any;
    private evidenceFound: boolean = false;
    private torch!: Phaser.GameObjects.Graphics;
    private evidenceSprite!: Phaser.GameObjects.Sprite;
    private patrolOfficer!: Phaser.Physics.Arcade.Sprite;
    private patrolDirection: number = 1;
    private detectionCone!: Phaser.GameObjects.Graphics;
    private isCaught: boolean = false;
    private spaceKey!: Phaser.Input.Keyboard.Key;

    constructor() {
        super('RecordRoomScene', 'Record Room - Muralipuram PS');
    }

    preload() {
        super.preload();
        LevelLoader.preloadCustomAssets(this, this.customData || RECORD_ROOM_DATA);
    }

    create() {
        super.create();
        const data = this.customData || RECORD_ROOM_DATA;

        LevelLoader.setupBounds(this, data);

        // Player
        this.player = this.createPlayer(data.playerSpawn.x, data.playerSpawn.y, data.playerSpawn.texture, data.playerSpawn.scale || 0.8);

        // NPCs
        LevelLoader.spawnObjects(this, data);

        // Find Saajan - Handle both plain objects and full NPC instances
        this.siSaajan = this.interactables.find((npc: any) => {
            const tex = npc.texture || (npc.sprite && npc.sprite.texture);
            return tex && (tex.key === SPRITE_KEYS.SAAJAN || tex.key === SPRITE_KEYS.HERO);
        });

        if (this.siSaajan) {
            this.siSaajan.speak = () => this.handleSaajanInteraction();
            // Fallback visual if Saajan texture missing
            if (!this.textures.exists(SPRITE_KEYS.SAAJAN)) {
                const targetSprite = this.siSaajan.sprite || this.siSaajan;
                targetSprite.setTint(0x3333ff); // Blue tint for police
                this.add.circle(targetSprite.x, targetSprite.y, 40, 0x3333ff, 0.3)
                    .setDepth(targetSprite.depth - 1);
            }
        }

        // Show Shelves (Procedural placeholders)
        for (let i = 0; i < 4; i++) {
            const shelfX = 1000 + (i * 200);
            this.add.rectangle(shelfX, 400, 150, 300, 0x4d3319)
                .setStrokeStyle(4, 0x000000).setDepth(10);
            this.add.text(shelfX, 280, "FILES", { fontSize: '14px', color: '#ffffff' }).setOrigin(0.5).setDepth(11);
        }

        // Hidden Evidence Fallback
        if (!this.textures.exists(SPRITE_KEYS.EVIDENCE_GUM)) {
            const graphics = this.make.graphics({ x: 0, y: 0 });
            graphics.fillStyle(0xffff00, 1);
            graphics.fillCircle(16, 16, 14);
            graphics.lineStyle(2, 0x000000, 1);
            graphics.strokeCircle(16, 16, 14);
            graphics.generateTexture('fallback_evidence', 32, 32);
            graphics.destroy();
        }

        const evidenceKey = this.textures.exists(SPRITE_KEYS.EVIDENCE_GUM) ? SPRITE_KEYS.EVIDENCE_GUM : 'fallback_evidence';
        this.evidenceSprite = this.add.sprite(1150, 450, evidenceKey)
            .setScale(0.8)
            .setAlpha(0)
            .setInteractive({ useHandCursor: true });

        this.evidenceSprite.on('pointerdown', () => this.collectEvidence());

        // Torch Effect (Hidden by default)
        this.torch = this.add.graphics();
        this.torch.setDepth(2000);

        // UI
        LevelLoader.createUI(this, data);
        LevelLoader.createExitZones(this, data);

        // Add Patrol Officer (The Challenge)
        // Patrol near the shelves (y = 450)
        this.patrolOfficer = this.physics.add.sprite(900, 450, SPRITE_KEYS.HERO);
        this.patrolOfficer.setTint(0xff3333).setScale(0.8); // Red tint for "Enemy"
        this.add.text(900, 390, "Duty Officer", { fontSize: '12px', color: '#ff0000' }).setOrigin(0.5);

        this.detectionCone = this.add.graphics();
        this.detectionCone.setDepth(1900);

        // Input
        this.spaceKey = this.input.keyboard!.addKey(Phaser.Input.Keyboard.KeyCodes.SPACE);

        this.startCutscene();
        this.time.delayedCall(1000, async () => {
            await this.showProfessionalDialogue("Jaison", "This place smells like old paper... and stale Jackfruit.");
            this.endCutscene();
        });
    }

    private async handleSaajanInteraction() {
        this.startCutscene();
        if (this.evidenceFound) {
            await this.showProfessionalDialogue("SI Saajan", "Excellent, Jaison! This 'Nadan Forensic' evidence— Jackfruit glue on a broomstick— is 100% scientifically accurate.");
            await this.showProfessionalDialogue("SI Saajan", "Now go to the City. The High Court is waiting for this stick.");
            this.endCutscene();
            this.completeRoom();
        } else {
            await this.showProfessionalDialogue("SI Saajan", "Jaison, we have no budget for DNA tests. We use 'Nadan Forensics' here.");
            await this.showProfessionalDialogue("SI Saajan", "The culprit used Jackfruit Gum to stick the glitched files. Find the broomstick evidence!");
            await this.showProfessionalDialogue("SI Saajan", "Use your 'Super-Sense' (Hold Space and move mouse) to scan the shelves.");
            await this.showProfessionalDialogue("SI Saajan", "BUT BE CAREFUL! The Duty Officer is on patrol. If he catches you scanning restricted files, we're both in trouble!");
            this.endCutscene();
        }
    }

    private completeRoom() {
        if (this.isLevelComplete) return;
        SaveManager.markLevelCompleted('RecordRoomScene');
        SaveManager.unlockLevel('Level4');
        SaveManager.save({
            currentLevel: 'HubScene',
            playerHealth: this.player.health,
            money: this.player.money,
            lastSaveTime: Date.now()
        });
        this.showVictory("EVIDENCE SECURED!");
    }

    private collectEvidence() {
        if (this.evidenceFound) return;
        this.evidenceFound = true;
        this.evidenceSprite.setAlpha(1);

        this.startCutscene();
        this.tweens.add({
            targets: this.evidenceSprite,
            x: this.player.x,
            y: this.player.y - 50,
            scaleX: 0.1,
            scaleY: 0.1,
            duration: 800,
            onComplete: async () => {
                this.evidenceSprite.destroy();
                if (this.cache.audio.exists(AUDIO_KEYS.COIN_COLLECT)) {
                    this.sound.play(AUDIO_KEYS.COIN_COLLECT);
                }
                await this.showProfessionalDialogue("Jaison", "Got it! Sticky evidence found. Saajan will be impressed by this technology.");
                this.endCutscene();
            }
        });
    }

    update(time: number, delta: number) {
        super.update(time, delta);
        if (this.isCaught || this.isLevelComplete) return;

        // --- PATROL LOGIC ---
        const speed = 80;
        this.patrolOfficer.setVelocityX(speed * this.patrolDirection);
        if (this.patrolOfficer.x > 1600) this.patrolDirection = -1;
        if (this.patrolOfficer.x < 900) this.patrolDirection = 1;
        this.patrolOfficer.setFlipX(this.patrolDirection === -1);

        // Update Detection Cone
        if (!this.evidenceFound) {
            this.updateDetectionCone();
        } else {
            this.detectionCone.clear();
        }

        // --- FORENSIC LOGIC ---
        if (this.spaceKey.isDown && !this.evidenceFound) {
            this.updateForensicTorch();
        } else {
            this.torch.clear();
            if (this.evidenceSprite && this.evidenceSprite.active && !this.evidenceFound) {
                this.evidenceSprite.setAlpha(0); // Hide if torch is off
            }
        }
    }

    private updateDetectionCone() {
        this.detectionCone.clear();

        const coneWidth = 250;
        const coneAngle = 0.5; // radians
        const x = this.patrolOfficer.x;
        const y = this.patrolOfficer.y;

        this.detectionCone.fillStyle(0xff0000, 0.2);

        // Draw triangle for vision
        const points = [
            { x: x, y: y },
            { x: x + (this.patrolDirection * coneWidth), y: y - (coneWidth * Math.tan(coneAngle)) },
            { x: x + (this.patrolDirection * coneWidth), y: y + (coneWidth * Math.tan(coneAngle)) }
        ];
        this.detectionCone.fillPoints(points, true);

        // Check if player is inside the triangle (Simplified box check for performance)
        const player = this.player;
        const distY = Math.abs(player.y - y);
        const distX = (player.x - x) * this.patrolDirection;

        if (distX > 0 && distX < coneWidth && distY < (distX * Math.tan(coneAngle)) + 20) {
            this.handlePlayerCaught();
        }
    }

    private async handlePlayerCaught() {
        if (this.isCaught) return;
        this.isCaught = true;
        this.player.setVelocity(0, 0);
        this.patrolOfficer.setVelocity(0, 0);

        this.startCutscene();
        this.cameras.main.flash(500, 255, 0, 0);
        await this.showProfessionalDialogue("Duty Officer", "HEI! What are you doing here in the Evidence Room?");
        await this.showProfessionalDialogue("Jaison", "Uhh... I was just checking for... Jackfruit?");

        // Reset player to Saajan
        this.player.setPosition(this.siSaajan.sprite.x - 100, this.siSaajan.sprite.y);
        this.isCaught = false;
        this.endCutscene();
    }

    private updateForensicTorch() {
        this.torch.clear();

        const pointer = this.input.activePointer;
        // World coordinates of pointer (Phaser automatically calculates this taking camera into account)
        const wx = pointer.worldX;
        const wy = pointer.worldY;

        // Draw a "Reveal" circle (Torch light)
        this.torch.fillStyle(0xffff00, 0.15);
        this.torch.fillCircle(wx, wy, 120);
        this.torch.lineStyle(2, 0xffff00, 0.8);
        this.torch.strokeCircle(wx, wy, 120);

        // Check if evidence is within torch
        if (this.evidenceSprite && this.evidenceSprite.active && !this.evidenceFound) {
            const dist = Phaser.Math.Distance.Between(wx, wy, this.evidenceSprite.x, this.evidenceSprite.y);
            if (dist < 120) {
                this.evidenceSprite.setAlpha(0.9);
                // Add a glow when found
                this.torch.lineStyle(4, 0x00ff00, 1);
                this.torch.strokeCircle(this.evidenceSprite.x, this.evidenceSprite.y, 40);
                
                // Automatically collect the evidence when found
                this.collectEvidence();
            } else {
                this.evidenceSprite.setAlpha(0);
            }
        }
    }
}
