import Phaser from 'phaser';
import SaveManager from '../managers/SaveManager';
import TranslationManager from '../utils/TranslationManager';
import type { AvatarAsset, AvatarConfig } from '../config/AvatarAssets';
import { AVATAR_ASSETS } from '../config/AvatarAssets';
import Player from '../entities/Player';
import LevelLoader from '../utils/LevelLoader';

export default class AvatarEditor extends Phaser.Scene {
    private playerPreview!: Player;
    private currentCategory: string = 'hair';
    private categories = ['hair', 'hat', 'shirt', 'pants', 'shoes', 'glasses', 'mask'];
    private config!: AvatarConfig;
    private ownedAssets: string[] = [];
    private money: number = 0;
    private itemGrid: Phaser.GameObjects.Container[] = [];
    private gridContainer!: Phaser.GameObjects.Container;
    private tabContainer!: Phaser.GameObjects.Container;
    private gridScrollY: number = 0;
    private selectedAsset: AvatarAsset | null = null;
    private equipBtn!: Phaser.GameObjects.Container;
    private purchaseBtn!: Phaser.GameObjects.Container;
    private scanline!: Phaser.GameObjects.Graphics;
    private playerPreviewContainer!: Phaser.GameObjects.Container;
    private tooltipContainer!: Phaser.GameObjects.Container;
    private tooltipText!: Phaser.GameObjects.Text;
    private tooltipBg!: Phaser.GameObjects.Graphics;

    // UI Constants
    private readonly GRID_COLS = 4;
    private readonly ACCENT_COLOR = 0xffd700;
    private readonly CYAN_GLOW = 0x00ffff;
    private readonly CYAN_GLOW_STR = '#00ffff';
    private readonly PADDING = 25;
    private readonly CYLINDER_HEIGHT = 600;
    private readonly CYLINDER_WIDTH = 220;
    private readonly CHARACTER_OFFSET_X = 8; // Nudge character left for centering

    constructor() {
        super('AvatarEditor');
    }

    preload() {
        LevelLoader.preloadAvatarAssets(this);
        this.load.image('icon_hair', '/assets/icons/hair.png');
        this.load.image('icon_hat', '/assets/icons/hat.png');
        this.load.image('icon_shirt', '/assets/icons/shirt.png');
        this.load.image('icon_pants', '/assets/icons/pants.png');
        this.load.image('icon_shoes', '/assets/icons/shoe.png');
        this.load.image('icon_glasses', '/assets/icons/glasses.png');
        this.load.image('icon_mask', '/assets/icons/mask.png');
    }

    create() {
        const width = this.scale.width;
        const height = this.scale.height;

        // --- LAYOUT ---
        const sidebarWidth = 80;
        const gridWidth = 450;
        const previewX = (width - sidebarWidth - gridWidth) / 2 + sidebarWidth;

        // Add Atmospheric Dust Particles (Enhanced)
        this.add.particles(0, 0, 'tile_sheet', {
            frame: 1,
            x: { min: 0, max: width },
            y: { min: 0, max: height },
            lifespan: { min: 5000, max: 10000 },
            speedY: { min: -5, max: -20 },
            alpha: { start: 0, end: 0.15, ease: 'Sine.easeIn' },
            scale: { start: 0.05, end: 0 },
            quantity: 1,
            blendMode: 'ADD'
        }).setDepth(-5);

        // Load Data
        const state = SaveManager.load() || SaveManager.getInitialState();
        // @ts-ignore
        this.config = state.avatar || {
            hair: 'hair_base',
            shirt: 'shirt_red',
            pants: 'pants_plain',
            shoes: 'shoes_default',
            hat: 'hat_none',
            glasses: 'glasses_none',
            mask: 'mask_none',
            hairColor: 0xffffff,
            skinColor: 0xffffff
        } as AvatarConfig;
        this.ownedAssets = state.ownedAssets || [];
        this.money = state.money || 0;

        // Sidebar Panel (Glassmorphism)
        this.tabContainer = this.add.container(0, 0);
        this.drawGlassPanel(this.PADDING, this.PADDING, sidebarWidth, height - this.PADDING * 2);
        this.createVerticalTabs(this.PADDING + sidebarWidth / 2, this.PADDING + 60);

        // Moved up to allow space for footer text
        // Preview Area - Glow Platform
        // Moved up to allow space for footer text
        const cylinderBottomY = height / 2 + 260;
        this.createPreviewPlatform(previewX, cylinderBottomY);

        // Player Preview Container for layering
        this.playerPreviewContainer = this.add.container(previewX, height / 2);
        this.playerPreviewContainer.setDepth(5);

        // Cylinder Back Layer
        this.createCylinderBack(previewX, cylinderBottomY);

        this.playerPreview = new Player(this, 0, 0, 'jaison');
        this.playerPreview.setScale(1.8); // Better fit
        this.playerPreview.setMovementMode('cutscene');
        this.playerPreview.updateAppearance(this.config);
        this.playerPreview.play(`${this.playerPreview.getAnimBaseKey()}-idle-down`);
        this.playerPreview.anims.timeScale = 1;

        // Match character layers to container
        this.playerPreview.setPosition(this.CHARACTER_OFFSET_X, 0);
        this.playerPreviewContainer.add(this.playerPreview);

        const layers = this.playerPreview.getLayers();
        Object.values(layers).forEach(layer => {
            this.playerPreviewContainer.add(layer);
            layer.setPosition(this.CHARACTER_OFFSET_X, 0); // Reset position relative to container
            layer.setScale(this.playerPreview.scale); // Sync scale
        });

        // Cylinder Front Layer
        this.createCylinderFront(previewX, cylinderBottomY);

        // Preview Label (Sleek High-Tech Pill)
        const previewLabelContainer = this.add.container(previewX, 40);
        const labelBg = this.add.graphics();
        labelBg.fillGradientStyle(0x0a0a1a, 0x0a0a1a, 0x1a1a40, 0x1a1a40, 1);
        labelBg.fillRoundedRect(-100, -20, 200, 40, 20);
        labelBg.lineStyle(2, this.CYAN_GLOW, 0.6);
        labelBg.strokeRoundedRect(-100, -20, 200, 40, 20);

        // Inner highlights for tech look
        labelBg.lineStyle(1, 0xffffff, 0.1);
        labelBg.strokeRoundedRect(-95, -15, 190, 30, 15);

        const labelText = this.add.text(0, 0, "PREVIEW", {
            fontFamily: 'Orbitron', fontSize: '20px', color: this.CYAN_GLOW_STR, fontStyle: 'bold', letterSpacing: 4
        }).setOrigin(0.5);
        previewLabelContainer.add([labelBg, labelText]);

        // Scanning highlight on label
        const labelScan = this.add.graphics();
        labelScan.fillStyle(0xffffff, 0.2);
        labelScan.fillRect(-100, -20, 10, 40);
        previewLabelContainer.add(labelScan);
        this.tweens.add({
            targets: labelScan,
            x: 190,
            duration: 3000,
            repeat: -1
        });

        // Right Grid Panel
        const gridX = width - gridWidth - this.PADDING;
        const gridHeight = height - this.PADDING * 2;
        this.drawGlassPanel(gridX, this.PADDING, gridWidth, gridHeight); // Add circuit design

        // Cylinder Glow Effects (Scanline)
        this.createCylinderScanline(previewX, cylinderBottomY);

        // Grid Container & Mask
        const gridAreaY = this.PADDING + 90;
        this.gridContainer = this.add.container(gridX + 20, gridAreaY);


        this.updateItemGrid(gridWidth);

        // Sidebar Controls Area (Bottom)
        const sidebarBottomY = height - this.PADDING - 40;
        this.createSidebarControls(this.PADDING + sidebarWidth / 2, sidebarBottomY);

        // Descriptive text at bottom platform area - slightly higher to avoid glow overlap
        const completedLevels = SaveManager.load()?.completedLevels.length || 0;
        this.add.text(previewX, height - 20, `PIXEL ART HERO - LEVEL ${completedLevels + 1}`, {
            fontFamily: 'Cinzel', fontSize: '18px', color: this.CYAN_GLOW_STR, fontStyle: 'bold'
        }).setOrigin(0.5).setDepth(20);

        // Money Display
        const moneyContainer = this.add.container(width - 170, this.PADDING + 10);
        const moneyBg = this.add.graphics();
        moneyBg.fillStyle(0x000000, 0.5);
        moneyBg.fillRoundedRect(0, 0, 100, 30, 15);
        moneyBg.lineStyle(1, 0xffd700, 0.8);
        moneyBg.strokeRoundedRect(0, 0, 100, 30, 15);

        const moneyText = this.add.text(50, 15, `🪙 ${this.money}`, {
            fontFamily: 'Orbitron', fontSize: '16px', color: '#ffd700', fontStyle: 'bold'
        }).setOrigin(0.5);

        moneyContainer.add([moneyBg, moneyText]);
        moneyContainer.setDepth(20);

        // Item Actions (Pill Buttons) at bottom of grid
        const btnY = gridHeight - 35;
        this.equipBtn = this.createActionButton(gridX + gridWidth * 0.3, btnY, "EQUIP", 0x4ade80);
        this.purchaseBtn = this.createActionButton(gridX + gridWidth * 0.7, btnY, "PURCHASE", 0x3ac1cf, true);

        // Background Effects
        this.createLightRays();

        // Help Toggle
        this.add.text(width - 70, 40, "ℹ️", { fontSize: '24px' })
            .setInteractive({ useHandCursor: true })
            .on('pointerdown', () => this.showHelpModal());

        this.createTooltip();
        this.updateButtonStates();
    }

    private createTooltip() {
        this.tooltipContainer = this.add.container(0, 0).setDepth(1000).setVisible(false);

        this.tooltipBg = this.add.graphics();
        this.tooltipBg.fillStyle(0x000000, 0.9);
        this.tooltipBg.lineStyle(1, this.CYAN_GLOW, 0.8);

        this.tooltipText = this.add.text(0, 0, "", {
            fontFamily: 'Orbitron',
            fontSize: '14px',
            color: '#ffffff'
        }).setOrigin(0.5);

        this.tooltipContainer.add([this.tooltipBg, this.tooltipText]);
    }

    private showTooltip(x: number, y: number, text: string) {
        this.tooltipText.setText(text);
        const bounds = this.tooltipText.getBounds();
        const padding = 10;
        const w = bounds.width + padding * 2;
        const h = bounds.height + padding * 2;

        this.tooltipBg.clear();
        this.tooltipBg.fillStyle(0x000000, 0.9);
        this.tooltipBg.lineStyle(1, this.CYAN_GLOW, 0.8);
        this.tooltipBg.fillRoundedRect(-w / 2, -h / 2, w, h, 8);
        this.tooltipBg.strokeRoundedRect(-w / 2, -h / 2, w, h, 8);

        this.tooltipContainer.setPosition(x, y);
        this.tooltipContainer.setVisible(true);
        this.tooltipContainer.setAlpha(0);

        this.tweens.killTweensOf(this.tooltipContainer);
        this.tweens.add({
            targets: this.tooltipContainer,
            alpha: 1,
            duration: 150
        });
    }

    private hideTooltip() {
        this.tweens.add({
            targets: this.tooltipContainer,
            alpha: 0,
            duration: 100,
            onComplete: () => {
                this.tooltipContainer.setVisible(false);
            }
        });
    }

    // @ts-ignore
    private createNebulaBackground(width: number, height: number) {
        const bgContainer = this.add.container(0, 0).setDepth(-10);

        // 1. Deep Space Base (Rich Gradient)
        const base = this.add.graphics();
        base.fillGradientStyle(0x020010, 0x020010, 0x1a0b2e, 0x0d0420, 1);
        base.fillRect(0, 0, width, height);
        bgContainer.add(base);

        // 2. Ambient Glows ( mimicking the reference lighting )
        // Left Cyan Glow
        const leftGlow = this.add.graphics();
        leftGlow.fillStyle(0x00aaff, 0.15);
        leftGlow.fillCircle(0, height * 0.4, 500);
        leftGlow.setBlendMode(Phaser.BlendModes.ADD);
        bgContainer.add(leftGlow);

        // Right Magenta Glow
        const rightGlow = this.add.graphics();
        rightGlow.fillStyle(0xff00aa, 0.12);
        rightGlow.fillCircle(width, height * 0.6, 600);
        rightGlow.setBlendMode(Phaser.BlendModes.ADD);
        bgContainer.add(rightGlow);

        // 3. Dynamic Light Rays ("God Rays")
        const rays = this.add.graphics();
        bgContainer.add(rays);
        rays.setAngle(-20); // Tilt
        for (let i = 0; i < 5; i++) {
            rays.fillGradientStyle(0xffffff, 0xffffff, 0x000000, 0x000000, 0.08, 0.02, 0, 0);
            rays.fillRect(i * 300 - 400, -200, 100 + Math.random() * 100, height * 1.5);
        }

        // 4. Subtle Tech Grid Overlay
        const grid = this.add.graphics();
        grid.lineStyle(2, 0xffffff, 0.03);
        const gridSize = 60;

        // Horizontal lines
        for (let y = 0; y < height; y += gridSize) {
            grid.moveTo(0, y);
            grid.lineTo(width, y);
        }
        // Angled lines for "Tech" feel
        for (let x = -height; x < width; x += gridSize * 2) {
            grid.moveTo(x, 0);
            grid.lineTo(x + height, height);
        }
        bgContainer.add(grid);
    }

    // @ts-ignore
    private createDirectionalLighting(width: number, height: number) {
        const lightContainer = this.add.container(0, 0).setDepth(-9);

        // 1. Left Source (Cyan/Blue Cool Light)
        const leftLight = this.add.graphics();
        // Large diffuse glow
        leftLight.fillGradientStyle(0x00ffff, 0x0044ff, 0x000000, 0x000000, 0.2, 0.1, 0, 0);
        leftLight.fillRect(0, 0, width * 0.4, height);
        // Focused hotspot
        leftLight.fillStyle(0x00ffff, 0.1);
        leftLight.fillCircle(0, height * 0.4, 300);
        lightContainer.add(leftLight);

        // 2. Right Source (Magenta/Purple Warm Light)
        const rightLight = this.add.graphics();
        rightLight.fillGradientStyle(0x000000, 0x000000, 0xff00ff, 0xaa00ff, 0, 0, 0.1, 0.15);
        rightLight.fillRect(width * 0.6, 0, width * 0.4, height);
        // Focused hotspot
        rightLight.fillStyle(0xff00ff, 0.05);
        rightLight.fillCircle(width, height * 0.6, 350);
        lightContainer.add(rightLight);

        // 3. Top Down Spotlight (Divine/Heroic)
        const spotLight = this.add.graphics();
        spotLight.fillGradientStyle(0xffffff, 0xffffff, 0x000000, 0x000000, 0.15, 0.15, 0, 0);
        spotLight.beginPath();
        spotLight.moveTo(width * 0.3, 0);
        spotLight.lineTo(width * 0.7, 0);
        spotLight.lineTo(width * 0.8, height);
        spotLight.lineTo(width * 0.2, height);
        spotLight.closePath();
        spotLight.fillPath();
        lightContainer.add(spotLight);

        // Animate lights slightly for 'breathing' effect
        this.tweens.add({
            targets: [leftLight, rightLight],
            alpha: { from: 0.8, to: 1 },
            duration: 3000,
            yoyo: true,
            repeat: -1,
            ease: 'Sine.easeInOut'
        });
    }

    // @ts-ignore
    private createLightStreaks(width: number, height: number) {
        const streakContainer = this.add.container(0, 0).setDepth(-8);
        const streakCount = 12;

        for (let i = 0; i < streakCount; i++) {
            const streak = this.add.graphics();
            const color = Math.random() > 0.5 ? 0x00ffff : 0xffd700; // Cyan or Golden
            const length = 400 + Math.random() * 600;
            const thickness = 1 + Math.random() * 3;
            const alpha = 0.05 + Math.random() * 0.1;

            streak.fillGradientStyle(color, color, color, color, 0, alpha, alpha, 0); // Faded ends
            streak.fillRect(0, 0, length, thickness);
            streak.setAngle(-45);

            // Random start position
            const startX = Math.random() * (width + length);
            const startY = -length + Math.random() * (height + length);
            streak.setPosition(startX, startY);
            streakContainer.add(streak);

            this.tweens.add({
                targets: streak,
                x: startX - 800,
                y: startY + 800,
                duration: 3000 + Math.random() * 4000,
                repeat: -1,
                delay: Math.random() * 5000
            });
        }
    }

    // @ts-ignore
    private createCentralBeam(x: number, height: number) {
        const beam = this.add.graphics().setDepth(-5);

        // Soft central vertical glow
        beam.fillGradientStyle(0x00ffff, 0x00ffff, 0x00ffff, 0x00ffff, 0, 0.1, 0.1, 0);
        beam.fillRect(x - 150, 0, 300, height);

        // Intense core line
        beam.fillStyle(0x00ffff, 0.05);
        beam.fillRect(x - 20, 0, 40, height);

        this.tweens.add({
            targets: beam,
            alpha: { from: 0.3, to: 0.6 },
            duration: 2000,
            yoyo: true,
            repeat: -1
        });
    }

    private createLightRays() {
        const width = this.scale.width;
        const height = this.scale.height;
        const rays = this.add.container(width / 2, height / 2).setDepth(-1).setAlpha(0.1);

        for (let i = 0; i < 8; i++) {
            const ray = this.add.graphics();
            ray.fillGradientStyle(0x00ffff, 0x00ffff, 0x000000, 0x000000, 0, 0, 0.5, 0.5);
            ray.fillRect(-50, -height, 100, height * 2);
            ray.setAngle(i * 45);
            rays.add(ray);

            this.tweens.add({
                targets: ray,
                angle: '+=360',
                duration: 60000 + Math.random() * 20000,
                repeat: -1
            });
        }

        this.tweens.add({
            targets: rays,
            alpha: 0.4,
            duration: 3000,
            yoyo: true,
            repeat: -1
        });
    }

    private updateButtonStates() {
        if (!this.selectedAsset) {
            this.equipBtn.setVisible(false);
            this.purchaseBtn.setVisible(false);
            return;
        }

        const isOwned = this.ownedAssets.includes(this.selectedAsset.id);
        const isEquipped = (this.config as any)[this.selectedAsset.category] === this.selectedAsset.id;

        if (isOwned) {
            this.equipBtn.setVisible(true).setAlpha(isEquipped ? 0.5 : 1);
            this.purchaseBtn.setVisible(false);
            // If show coin or label change
            (this.equipBtn.getAt(0) as Phaser.GameObjects.Graphics).setAlpha(isEquipped ? 0.5 : 1);
        } else {
            this.equipBtn.setVisible(false);
            this.purchaseBtn.setVisible(true);

            const completedLevels = SaveManager.load()?.completedLevels.length || 0;
            const canAfford = this.money >= this.selectedAsset.price;
            const unlocked = completedLevels + 1 >= this.selectedAsset.levelRequired;

            this.purchaseBtn.setAlpha(canAfford && unlocked ? 1 : 0.5);
        }
    }

    private createActionButton(x: number, y: number, label: string, color: number, showCoin = false) {
        const container = this.add.container(x, y);
        const bg = this.add.graphics();

        // Plain & Simple Clean Button
        bg.fillStyle(color, 1);
        bg.fillRoundedRect(-85, -22, 170, 44, 22);

        // Simple Stroke
        bg.lineStyle(2, color, 0.8);
        bg.strokeRoundedRect(-85, -22, 170, 44, 22);

        const text = this.add.text(showCoin ? -20 : 0, 0, label, {
            fontFamily: 'Orbitron', fontSize: '20px', color: '#ffffff', fontStyle: 'bold'
        }).setOrigin(0.5);

        container.add([bg, text]);
        if (showCoin) {
            const coin = this.add.text(50, 0, "🪙", {
                fontFamily: 'Arial',
                fontSize: '24px',
                padding: { y: 10 }
            }).setOrigin(0.5);
            container.add(coin);
        }

        const area = this.add.rectangle(0, 0, 170, 44, 0x000000, 0).setInteractive({ useHandCursor: true });
        container.add(area);
        area.on('pointerover', () => { if (container.alpha === 1) container.setScale(1.05); });
        area.on('pointerout', () => { container.setScale(1); });

        area.on('pointerdown', () => {
            if (container.alpha < 1) return;
            if (label === "EQUIP") this.equipSelected();
            else if (label === "PURCHASE") this.purchaseSelected();
        });

        return container;
    }

    private equipSelected() {
        if (!this.selectedAsset) return;
        (this.config as any)[this.selectedAsset.category] = this.selectedAsset.id;
        SaveManager.save({ avatar: this.config, ownedAssets: this.ownedAssets, money: this.money });
        this.playerPreview.updateAppearance(this.config);
        this.updateItemGrid(450); // Refresh grid
        this.updateButtonStates();
    }

    private purchaseSelected() {
        if (!this.selectedAsset) return;
        if (this.money >= this.selectedAsset.price) {
            this.money -= this.selectedAsset.price;
            this.ownedAssets.push(this.selectedAsset.id);
            SaveManager.save({ avatar: this.config, ownedAssets: this.ownedAssets, money: this.money });
            this.updateItemGrid(450); // Refresh grid to show owned icon
            this.updateButtonStates();
        } else {
            this.cameras.main.shake(100, 0.01);
        }
    }

    private drawGlassPanel(x: number, y: number, w: number, h: number, _withDesign = false) {
        const graphics = this.add.graphics();

        // // Inner Glow / Subtle highlight at the top
        graphics.fillGradientStyle(0xffffff, 0xffffff, 0x101030, 0x101030, 0.1, 0.1, 0, 0);
        graphics.fillRoundedRect(x + 5, y + 5, w - 10, 40, 15);

        // Neon Border Effect (Multi-layered stroke)
        // Core white line
        graphics.lineStyle(1.5, 0xffffff, 0.6);
        graphics.strokeRoundedRect(x, y, w, h, 24);


        // Specular highlight line (left edge)
        graphics.lineStyle(1.5, 0x00ffff, 0.1);
        graphics.moveTo(x + 5, y + 30);
        graphics.lineTo(x + 5, y + h - 30);
        graphics.strokePath();
    }

    private createCylinderScanline(x: number, y: number) {
        this.scanline = this.add.graphics();
        this.scanline.setDepth(10);
        this.scanline.fillStyle(0x00ffff, 0.4);
        this.scanline.fillRect(x - this.CYLINDER_WIDTH / 2, 0, this.CYLINDER_WIDTH, 3);

        this.tweens.add({
            targets: this.scanline,
            y: { from: y - this.CYLINDER_HEIGHT + 20, to: y - 20 },
            duration: 2500,
            repeat: -1
        });

        const maskShape = this.add.graphics();
        maskShape.fillRoundedRect(x - this.CYLINDER_WIDTH / 2, y - this.CYLINDER_HEIGHT, this.CYLINDER_WIDTH, this.CYLINDER_HEIGHT, 40);
        this.scanline.setMask(maskShape.createGeometryMask());
    }

    private createCylinderBack(x: number, y: number) {
        const glassBack = this.add.graphics().setDepth(4);
        glassBack.fillStyle(0x00ffff, 0.05);
        glassBack.fillRoundedRect(x - this.CYLINDER_WIDTH / 2, y - this.CYLINDER_HEIGHT, this.CYLINDER_WIDTH, this.CYLINDER_HEIGHT, 40);
    }

    private createCylinderFront(x: number, y: number) {
        const glassFront = this.add.graphics().setDepth(6);

        // Edge glow
        glassFront.lineStyle(3, 0xffffff, 0.2);
        glassFront.strokeRoundedRect(x - this.CYLINDER_WIDTH / 2, y - this.CYLINDER_HEIGHT, this.CYLINDER_WIDTH, this.CYLINDER_HEIGHT, 40);

        // Specular glint
        glassFront.fillGradientStyle(0xffffff, 0xffffff, 0xffffff, 0xffffff, 0.3, 0, 0.3, 0);
        glassFront.fillRect(x - 80, y - this.CYLINDER_HEIGHT + 20, 40, this.CYLINDER_HEIGHT - 40);

        // Additional glints
        glassFront.fillStyle(0xffffff, 0.1);
        glassFront.fillRect(x + 50, y - this.CYLINDER_HEIGHT + 20, 5, this.CYLINDER_HEIGHT - 40);
        glassFront.fillRect(x + 70, y - this.CYLINDER_HEIGHT + 20, 10, this.CYLINDER_HEIGHT - 40);
    }

    private createPreviewPlatform(x: number, y: number) {
        const platform = this.add.container(x, y).setDepth(3);

        // Ground Rings
        const rings = this.add.graphics();
        for (let i = 0; i < 3; i++) {
            rings.lineStyle(4 - i, this.CYAN_GLOW, 0.1 + i * 0.2);
            rings.strokeEllipse(0, 0, 240 - i * 40, 100 - i * 20);
        }

        // Solid base
        const base = this.add.ellipse(0, 0, 160, 60, 0x0a0a20, 1).setStrokeStyle(2, this.CYAN_GLOW);

        // Intense glow
        const glow = this.add.ellipse(0, 0, 140, 50, this.CYAN_GLOW, 0.2);

        platform.add([rings, base, glow]);

        this.tweens.add({
            targets: glow,
            alpha: 0.8,
            scale: 1.2,
            duration: 1500,
            yoyo: true, repeat: -1
        });

        // Add additional decorative rings for mockup look
        for (let i = 0; i < 6; i++) {
            const ring = this.add.ellipse(0, 0, 200 + i * 30, 80 + i * 15, this.CYAN_GLOW, 0);
            ring.setStrokeStyle(2 - (i * 0.2), this.CYAN_GLOW, 0.3 - (i * 0.05));
            platform.add(ring);
            this.tweens.add({
                targets: ring,
                alpha: 0.1,
                scale: 1.05,
                duration: 2000 + i * 200,
                delay: i * 300,
                yoyo: true, repeat: -1
            });
        }
    }

    private createSidebarControls(x: number, y: number) {
        const controls = this.add.container(x, y);

        // Exit Arrow (Modern style)
        const exit = this.add.container(0, 0);
        const exitBg = this.add.graphics();
        exitBg.fillStyle(0xffd700, 0.2);
        exitBg.fillRoundedRect(-20, -20, 40, 40, 10);
        exitBg.lineStyle(2, 0xffd700, 0.6);
        exitBg.strokeRoundedRect(-20, -20, 40, 40, 10);
        const exitTxt = this.add.text(0, 0, "⬅", { fontSize: '24px', color: '#ffd700' }).setOrigin(0.5);
        exit.add([exitBg, exitTxt]);

        exit.setInteractive(new Phaser.Geom.Rectangle(-20, -20, 40, 40), Phaser.Geom.Rectangle.Contains)
            .on('pointerdown', () => this.scene.start('MainMenu'));

        // Add hover effect
        exit.on('pointerover', () => { exit.setScale(1.1); exitBg.strokeRoundedRect(-20, -20, 40, 40, 10); });
        exit.on('pointerout', () => { exit.setScale(1); });

        controls.add(exit);
    }

    private createVerticalTabs(x: number, startY: number) {
        this.tabContainer.removeAll(true);
        const gap = 70; // Spacious premium gap

        const state = SaveManager.load() || SaveManager.getInitialState();
        const completedLevels = state.completedLevels?.length || 0;
        const unlockedLevels = state.unlockedLevels || [];

        // Level 3 requires finishing Level 1 & 2, OR if Level 3 is explicitly unlocking
        const isLevel3Unlocked = completedLevels >= 2 || unlockedLevels.includes('Level3');

        this.categories.forEach((cat, i) => {
            const isSelected = this.currentCategory === cat;
            const isLocked = (cat === 'glasses' || cat === 'mask') && !isLevel3Unlocked;

            const container = this.add.container(x, startY + i * gap);

            // Mockup symbols removed in favor of images


            // Slot Background (Fluorescent Neon Style)
            const bg = this.add.graphics();
            const iconMap: { [key: string]: string } = {
                hat: 'icon_hat', shirt: 'icon_shirt', pants: 'icon_pants', shoes: 'icon_shoes',
                hair: 'icon_hair', glasses: 'icon_glasses', mask: 'icon_mask'
            };

            let iconContainer = this.add.container(0, 0);

            if (isLocked) {
                const lockIcon = this.add.text(0, 0, '🔒', {
                    fontSize: '30px',
                    fontFamily: 'Arial',
                    color: '#888888'
                }).setOrigin(0.5);
                iconContainer.add(lockIcon);
            } else {
                const iconKey = iconMap[cat];
                if (iconKey) {

                    // Glow effect (duplicate behind)
                    const glow = this.add.image(0, 0, iconKey);
                    glow.setDisplaySize(68, 68); // Slightly larger
                    glow.setBlendMode(Phaser.BlendModes.ADD);

                    // Main Icon
                    const img = this.add.image(0, 0, iconKey);
                    img.setDisplaySize(64, 64);

                    iconContainer.add([glow, img]);

                    // Pulse animation for selected
                    if (isSelected) {
                        this.tweens.add({
                            targets: glow,
                            alpha: { from: .5, to: 1 },
                            scale: { from: .25, to: .3 },
                            duration: 500,
                            yoyo: true,
                            repeat: -1
                        });
                    }
                } else {
                    const fallback = this.add.text(0, 0, '?', { fontSize: '24px', color: '#ffffff' }).setOrigin(0.5);
                    iconContainer.add(fallback);
                }
            }

            container.add([bg, iconContainer]);

            const hitArea = this.add.rectangle(0, 0, 50, 50, 0x000000, 0).setInteractive({ useHandCursor: !isLocked });
            container.add(hitArea);

            hitArea.on('pointerover', () => {
                if (!isLocked) {
                    container.setScale(1.1);
                }
                const tooltipText = isLocked
                    ? "Unlock at Level 3"
                    : cat.charAt(0).toUpperCase() + cat.slice(1);
                this.showTooltip(x + 50, startY + i * gap, tooltipText);
            });
            hitArea.on('pointerout', () => {
                container.setScale(1);
                this.hideTooltip();
            });
            hitArea.on('pointerdown', () => {
                if (isLocked) return;
                this.currentCategory = cat;
                this.createVerticalTabs(x, startY); // Redraw tabs for highlight
                this.updateItemGrid(450); // Refresh grid 
                this.updateButtonStates();
            });
            this.tabContainer.add(container);
        });
    }

    private updateItemGrid(gridWidth: number) {
        this.itemGrid.forEach(c => c.destroy());
        this.itemGrid = [];

        const assets = AVATAR_ASSETS.filter(a => a.category === this.currentCategory);
        const margin = 10;
        const effectiveWidth = gridWidth - 40;
        const colWidth = (effectiveWidth - (this.GRID_COLS - 1) * margin) / this.GRID_COLS;

        assets.forEach((asset, i) => {
            const col = i % this.GRID_COLS;
            const row = Math.floor(i / this.GRID_COLS);
            const x = col * (colWidth + margin) + colWidth / 2;
            const y = row * (colWidth + margin) + colWidth / 2;

            const container = this.add.container(x, y);
            const isEquipped = (this.config as any)[this.currentCategory] === asset.id;
            const isOwned = this.ownedAssets.includes(asset.id);
            const isSelected = this.selectedAsset?.id === asset.id;

            // Mockup Style Slot
            const slotBg = this.add.graphics();
            const slotColor = isEquipped ? 0x2e355c : (isSelected ? 0x3a457a : 0x1f223d);

            // Modern Gradient Slot
            slotBg.fillGradientStyle(slotColor, slotColor, 0x111122, 0x111122, 1);
            slotBg.fillRoundedRect(-colWidth / 2, -colWidth / 2, colWidth, colWidth, 15);

            // Circuit Pattern inside slot (from mockup)
            slotBg.lineStyle(1, 0xffffff, 0.05);
            // Dots at corners
            const dotSize = 2;
            slotBg.fillStyle(this.CYAN_GLOW, 0.3);
            slotBg.fillCircle(-colWidth / 2 + 8, -colWidth / 2 + 8, dotSize);
            slotBg.fillCircle(colWidth / 2 - 8, -colWidth / 2 + 8, dotSize);
            slotBg.fillCircle(-colWidth / 2 + 8, colWidth / 2 - 8, dotSize);
            slotBg.fillCircle(colWidth / 2 - 8, colWidth / 2 - 8, dotSize);

            // Connecting lines
            slotBg.lineStyle(1, 0xffffff, 0.03);
            slotBg.strokeRect(-colWidth / 2 + 12, -colWidth / 2 + 12, colWidth - 24, colWidth - 24);

            if (isEquipped || isSelected) {
                slotBg.lineStyle(3, isEquipped ? this.CYAN_GLOW : this.ACCENT_COLOR, 0.8);
                const glow = this.add.graphics();
                glow.lineStyle(4, isEquipped ? this.CYAN_GLOW : this.ACCENT_COLOR, 0.2);
                glow.strokeRoundedRect(-colWidth / 2 - 2, -colWidth / 2 - 2, colWidth + 4, colWidth + 4, 17);
                container.add(glow);

                this.tweens.add({
                    targets: glow,
                    alpha: 0.1,
                    duration: 1500,
                    yoyo: true,
                    repeat: -1
                });
            } else {
                slotBg.lineStyle(2, 0xffffff, 0.1);
            }
            slotBg.strokeRoundedRect(-colWidth / 2, -colWidth / 2, colWidth, colWidth, 15);
            container.add(slotBg);

            // Asset Sprite
            if (asset.texture) {
                // Icon Backlight Glow
                const iconGlow = this.add.graphics();
                iconGlow.fillStyle(isEquipped ? this.CYAN_GLOW : (isOwned ? 0xffd700 : 0xffffff), 0.15);
                iconGlow.fillCircle(0, 0, colWidth * 0.3);
                container.add(iconGlow);

                const preview = this.add.sprite(0, -5, asset.texture, 0);
                const scale = (colWidth * 0.6) / preview.width;
                preview.setScale(scale);
                container.add(preview);
            }

            // Icons (Mockup style)
            const iconY = -colWidth / 2 + 15;
            const iconX = colWidth / 2 - 15;

            if (isEquipped) {
                // Green checkmark from mockup
                const checkBg = this.add.graphics();
                checkBg.fillStyle(0x4ade80, 1);
                checkBg.fillRoundedRect(iconX - 10, iconY - 10, 20, 20, 4);
                const check = this.add.text(iconX, iconY, "✔", { fontSize: '14px', color: '#000000', fontStyle: 'bold' }).setOrigin(0.5);
                container.add([checkBg, check]);

                // Cyan glowing bottom bar
                const bar = this.add.graphics().fillStyle(this.CYAN_GLOW, 0.8).fillRect(-colWidth / 2 + 10, colWidth / 2 - 8, colWidth - 20, 4);
                container.add(bar);
            } else if (isOwned) {
                // Golden crown for premium owned
                const crown = this.add.text(iconX, iconY, "👑", { fontSize: '16px' }).setOrigin(0.5);
                container.add(crown);
            } else {
                const completedLevels = SaveManager.load()?.completedLevels.length || 0;
                if (completedLevels + 1 < asset.levelRequired) {
                    const lock = this.add.text(iconX, iconY, "🔒", { fontSize: '16px', color: '#ff4444' }).setOrigin(0.5);
                    container.add(lock);
                }
            }

            const hitArea = this.add.rectangle(0, 0, colWidth, colWidth, 0x000000, 0).setInteractive({ useHandCursor: true });
            container.add(hitArea);

            hitArea.on('pointerover', () => { container.setScale(1.05); slotBg.setAlpha(1); });
            hitArea.on('pointerout', () => { container.setScale(1); slotBg.setAlpha(0.8); });
            hitArea.on('pointerdown', () => this.handleItemClick(asset));

            this.gridContainer.add(container);
            this.itemGrid.push(container);
        });

        // Add scroll wheel logic
        this.input.on('wheel', (_p: any, _g: any, _dx: number, dy: number) => {
            const rows = Math.ceil(assets.length / this.GRID_COLS);
            const contentHeight = rows * (colWidth + margin);
            const limit = Math.max(0, contentHeight - 400);

            this.gridScrollY = Phaser.Math.Clamp(this.gridScrollY - dy, -limit, 0);
            this.gridContainer.y = this.PADDING + 90 + this.gridScrollY;

            // Updated Scrollbar Indicator
            this.updateScrollbar(limit, gridWidth);
        });

        // Initialize/Update Scrollbar
        this.updateScrollbar(Math.max(0, (Math.ceil(assets.length / this.GRID_COLS) * (colWidth + margin)) - 400), gridWidth);
    }

    private scrollbarGraphics: Phaser.GameObjects.Graphics | null = null;
    private updateScrollbar(limit: number, _gridWidth: number) {
        if (this.scrollbarGraphics) this.scrollbarGraphics.destroy();
        if (limit <= 0) return;

        const sidebarX = this.PADDING + (this.scale.width - 450 - this.PADDING * 2) + 450 - 5;
        const scrollAreaY = this.PADDING + 90;
        const scrollAreaH = this.scale.height - this.PADDING * 2 - 180;

        this.scrollbarGraphics = this.add.graphics();
        this.scrollbarGraphics.setDepth(100);

        // Track
        this.scrollbarGraphics.fillStyle(0xffffff, 0.05);
        this.scrollbarGraphics.fillRoundedRect(sidebarX, scrollAreaY, 4, scrollAreaH, 2);

        // Handle
        const handleH = Math.max(20, (scrollAreaH / (limit + scrollAreaH)) * scrollAreaH);
        const handleY = scrollAreaY + (-this.gridScrollY / limit) * (scrollAreaH - handleH);

        this.scrollbarGraphics.fillStyle(this.CYAN_GLOW, 0.6);
        this.scrollbarGraphics.fillRoundedRect(sidebarX, handleY, 4, handleH, 2);
    }

    private handleItemClick(asset: AvatarAsset) {
        this.selectedAsset = asset;

        // Temporarily update preview for visual feedback
        const tempConfig = { ...this.config, [this.currentCategory]: asset.id };
        this.playerPreview.updateAppearance(tempConfig);

        this.updateItemGrid(450);
        this.updateButtonStates();
    }

    private showHelpModal() {
        const w = this.scale.width;
        const h = this.scale.height;
        const modal = this.add.container(0, 0).setDepth(20000);

        // Dark Overlay
        const overlay = this.add.rectangle(w / 2, h / 2, w, h, 0x000000, 0.85).setInteractive();
        modal.add(overlay);

        // Modal Box
        const boxW = 600;
        const boxH = 500;
        const box = this.add.rectangle(w / 2, h / 2, boxW, boxH, 0x1a1a40).setStrokeStyle(3, 0x333366);
        modal.add(box);

        const title = this.add.text(w / 2, h / 2 - boxH / 2 + 30, 'AVATAR EDITOR GUIDE', {
            fontSize: '24px', color: '#ffd700', fontStyle: 'bold'
        }).setOrigin(0.5);
        modal.add(title);

        const helpContent = [
            "# Style Your Hero!",
            "Welcome to the Avatar Editor! Personalize Jaison's look before heading into KURUKKANMOOLA.",
            "",
            "## 1. Things (Categories)",
            "Select a category from the left sidebar to choose what you want to customize: Skin, Hair, Hat, Clothing, and more.",
            "",
            "## 2. Choosing Items",
            "Browse the items on the right. Each item shows its price in coins if you don't own it.",
            "",
            "## 3. Buying & Equipping",
            "If you own an item, click it to EQUIP. If not, click to BUY it. Your money is shown in the top right corner.",
            "",
            "## 4. Requirements",
            "Some premium items require you to complete levels before they become available for purchase.",
            "",
            "## 5. Live Preview",
            "The center area shows a live, animated preview of your character. Check how your new gear looks in action!",
            "",
            "## 6. Persistence",
            "Your choices are automatically saved and will be used as your character's look throughout the game."
        ];

        // Scrollable Area
        const scrollW = boxW - 60;
        const scrollH = boxH - 140;
        const scrollX = w / 2 - boxW / 2 + 30;
        const scrollY = h / 2 - boxH / 2 + 80;

        const scrollContainer = this.add.container(scrollX, scrollY);
        modal.add(scrollContainer);

        const maskShape = this.add.graphics().fillStyle(0xffffff).fillRect(scrollX, scrollY, scrollW, scrollH);
        scrollContainer.setMask(maskShape.createGeometryMask());

        let currentY = 0;
        helpContent.forEach(line => {
            let color = '#ffffff';
            let fontSize = '16px';
            let style = 'normal';

            if (line.startsWith('# ')) { color = '#ffd700'; fontSize = '20px'; style = 'bold'; }
            else if (line.startsWith('## ')) { color = '#8888ff'; fontSize = '18px'; style = 'bold'; }

            const txt = this.add.text(0, currentY, TranslationManager.translate(line), {
                fontSize, color, fontStyle: style, wordWrap: { width: scrollW - 10 }
            });
            scrollContainer.add(txt);
            currentY += txt.height + 8;
        });

        const scrollLimit = Math.max(0, currentY - scrollH);
        this.input.on('wheel', (_p: any, _g: any, _dx: number, dy: number) => {
            scrollContainer.y = Phaser.Math.Clamp(scrollContainer.y - dy, scrollY - scrollLimit, scrollY);
        });

        const closeBtn = this.add.text(w / 2, h / 2 + boxH / 2 - 30, '[ CLOSE ]', {
            fontSize: '18px', color: '#ffffff', backgroundColor: '#333333', padding: { x: 10, y: 5 }
        }).setOrigin(0.5).setInteractive({ useHandCursor: true })
            .on('pointerdown', () => {
                this.input.off('wheel');
                maskShape.destroy();
                modal.destroy();
            })
            .on('pointerover', (t: any) => t.setColor('#ffd700'))
            .on('pointerout', (t: any) => t.setColor('#ffffff'));
        modal.add(closeBtn);
    }
}
