/**
 * Level Loader Utility
 * Processes level data and creates level elements
 */

import Phaser from 'phaser';
import type { LevelData, CutsceneStep, NPCConfig } from '../config/LevelData';
import BaseLevel from '../scenes/BaseLevel';
import NPC from '../entities/NPC';
import { AUDIO_KEYS, SPRITE_CONFIG, ASSET_PATHS, DEPTHS } from '../config';
import { AVATAR_ASSETS } from '../config/AvatarAssets';
import TranslationManager from '../utils/TranslationManager';

export default class LevelLoader {
    /**
     * Preloads custom assets for the level
     */
    static preloadCustomAssets(scene: Phaser.Scene, data: LevelData): void {
        // Preload standard avatar assets for character customization
        LevelLoader.preloadAvatarAssets(scene);

        if (data.backgroundImage) {
            const bgKey = 'level_bg_texture_' + scene.scene.key;
            // Force reload if already exists (avoids stale cache in editor sessions)
            if (scene.textures.exists(bgKey)) {
                scene.textures.remove(bgKey);
            }
            scene.load.image(bgKey, data.backgroundImage);
        }

        if (!data.customAssets) return;

        data.customAssets.forEach(asset => {
            const assetKey = typeof asset === 'string' ? asset : asset.key;
            const assetData = typeof asset === 'object' ? asset.data : undefined;

            if (assetData) {
                // If base64 data is present (Play Test Mode), load it directly
                scene.load.image(assetKey, assetData);
            } else {
                // Otherwise look for it in the standard custom assets path
                scene.load.image(assetKey, `/assets/custom/${assetKey}.png`);
            }
        });
    }

    /**
     * Preloads all available avatar assets to ensure customization works in any level
     */
    static preloadAvatarAssets(scene: Phaser.Scene): void {
        const textures = new Set(AVATAR_ASSETS.map(a => a.texture).filter(t => t && t !== ''));
        textures.add('test_sheet'); // Explicitly add Test Sprite for NPCs
        textures.add('ksrtc_lorry'); // Explicitly add KSRTC Lorry Sheet
        textures.add('damu'); // Explicitly add Damu for Tea Shop
        textures.add('saroj_kumar');
        textures.add('pachalam_bhasi');
        textures.forEach(texture => {
            if (!scene.textures.exists(texture)) {
                if (texture === 'tile_sheet') {
                    scene.load.spritesheet(texture, '/assets/tileset.png', SPRITE_CONFIG.TILESET);
                } else {
                    // Try to find matching path in ASSET_PATHS
                    let path = `/assets/characters/${texture}.png`; // Default

                    // Map keys to ASSET_PATHS
                    // Map keys to ASSET_PATHS
                    const TEXTURE_MAP: Record<string, { path: string; mirror?: string; config?: Phaser.Types.Loader.FileTypes.ImageFrameConfig }> = {
                        'jaison': { path: ASSET_PATHS.JAISON, mirror: ASSET_PATHS.JAISON_MIRROR },
                        'hero': { path: ASSET_PATHS.HERO, mirror: ASSET_PATHS.HERO_MIRROR },
                        'dasan': { path: ASSET_PATHS.DASAN, mirror: ASSET_PATHS.DASAN_MIRROR },
                        'boss': { path: ASSET_PATHS.BOSS, mirror: ASSET_PATHS.BOSS_MIRROR },
                        'nephew': { path: ASSET_PATHS.NEPHEW },
                        'saajan': { path: ASSET_PATHS.SAAJAN },
                        'hat_base': { path: ASSET_PATHS.HAT_BASE },
                        'black_hat': { path: ASSET_PATHS.BLACK_HAT },
                        'brown_hat': { path: ASSET_PATHS.BROWN_HAT },
                        'hair_base': { path: ASSET_PATHS.HAIR_BASE },
                        'hair_long': { path: ASSET_PATHS.HAIR_LONG },
                        'shirt_base': { path: ASSET_PATHS.SHIRT_BASE },
                        'shirt_blue': { path: ASSET_PATHS.SHIRT_BLUE },
                        'test_sheet': { path: ASSET_PATHS.TEST_SHEET, config: SPRITE_CONFIG.TEST_SHEET },
                        'ksrtc_lorry': { path: ASSET_PATHS.KSRTC_LORRY, config: SPRITE_CONFIG.KSRTC_LORRY },
                        'damu': { path: ASSET_PATHS.DAMU },
                        'saroj_kumar': { path: ASSET_PATHS.SAROJ_KUMAR },
                        'pachalam_bhasi': { path: ASSET_PATHS.PACHALAM_BHASI }
                    };

                    const config = TEXTURE_MAP[texture];
                    if (config) {
                        path = config.path;
                        scene.load.spritesheet(texture, path, config.config || SPRITE_CONFIG.CHARACTER);

                        if (config.mirror && !scene.textures.exists(texture + '_mirror')) {
                            scene.load.spritesheet(texture + '_mirror', config.mirror, config.config || SPRITE_CONFIG.CHARACTER);
                        }
                    } else {
                        scene.load.spritesheet(texture, path, SPRITE_CONFIG.CHARACTER);
                    }
                }
            }
        });
    }

    /**
     * Renders the background image for a level if one is provided
     */
    static renderBackground(scene: BaseLevel, data: LevelData): void {
        if (data.backgroundImage && scene.textures.exists('level_bg_texture_' + scene.scene.key)) {
            scene.add.image(0, 0, 'level_bg_texture_' + scene.scene.key).setOrigin(0).setDepth(-20);
        }
    }

    /**
     * Sets up camera and physics bounds, and loads collision polygons
     */
    static setupBounds(scene: BaseLevel, data: LevelData): void {
        const { map } = data;
        let worldWidth = map.width * map.tileWidth * map.tileScale;
        let worldHeight = map.height * map.tileHeight * map.tileScale;

        // Active Area Override: Use the biggest LevelLink zone as the playable world bounds
        let bX = 0, bY = 0;
        if (data.objects?.levelLinks) {
            // Find a link that has width/height (indicating a zone)
            const zone = data.objects.levelLinks.find(l => (l.width || 0) > 100 && (l.height || 0) > 100);
            if (zone) {
                bX = zone.x - (zone.width || 0) / 2;
                bY = zone.y - (zone.height || 0) / 2;
                worldWidth = zone.width!;
                worldHeight = zone.height!;
            }
        }
        
        // Keep bounds on exact pixel coordinates to avoid half-pixel clipping.
        const boundsX = Math.floor(bX);
        const boundsY = Math.floor(bY);
        const boundsWidth = Math.ceil(worldWidth);
        const boundsHeight = Math.ceil(worldHeight);

        console.log(`[LevelLoader] Setting bounds to: ${boundsX}, ${boundsY}, ${boundsWidth}, ${boundsHeight}`);
        scene.physics.world.setBounds(boundsX, boundsY, boundsWidth, boundsHeight);
        scene.cameras.main.setBounds(boundsX, boundsY, boundsWidth, boundsHeight);

        // Create Collision Masks (Rects)
        LevelLoader.createCollisionMasks(scene, data);
    }


    /**
     * Spawns level objects (coins, save zones, houses, etc.)
     */
    static spawnObjects(scene: BaseLevel, data: LevelData): void {
        // Spawn packed tiles (optimized grid-aligned props)
        LevelLoader.spawnPackedTiles(scene, data);

        if (!data.objects) return;

        // Spawn coins
        if (data.objects.coins) {
            data.objects.coins.forEach(coin => {
                scene['spawnCoin'](coin.x, coin.y);
            });
        }

        // Spawn save zones
        if (data.objects.saveZones) {
            data.objects.saveZones.forEach(zone => {
                scene['createSaveZone'](zone.x, zone.y);
            });
        }

        // Spawn houses
        if (data.objects.houses) {
            data.objects.houses.forEach(house => {
                scene['createHouse'](house.x, house.y, house.id || '', house.label);
            });
        }

        // Spawn NPCs
        if (data.objects.npcs) {
            data.objects.npcs.forEach(npcData => {
                LevelLoader.spawnNPC(scene, npcData);
            });
        }

        // Create level links
        if (data.objects.levelLinks) {
            data.objects.levelLinks.forEach(link => {
                scene['createLevelLink'](
                    link.x,
                    link.y,
                    link.targetLevel,
                    link.spawnPoint,
                    link.label,
                    link.confirmDestination || false,
                    link.width || 128,
                    link.height || 128,
                    link.sublabel
                );
            });
        }

        // Spawn generic props
        if (data.objects.props) {
            LevelLoader.spawnProps(scene, data);
        }
    }

    /**
     * Spawns optimized packed tiles from grid coordinates
     */
    static spawnPackedTiles(scene: BaseLevel, data: LevelData): void {
        if (!data.packedTiles) return;

        const gridSize = data.map.tileWidth * data.map.tileScale;

        Object.entries(data.packedTiles).forEach(([textureKey, positions]) => {
            positions.forEach(([tx, ty]) => {
                // Calculate center position based on grid
                const x = tx * gridSize + gridSize / 2;
                const y = ty * gridSize + gridSize / 2;

                const sprite = scene.add.sprite(x, y, textureKey);
                sprite.setDepth(DEPTHS.TILES); // Default depth for tiles
            });
        });
    }

    /**
     * Spawns generic decorative props
     */
    static spawnProps(scene: BaseLevel, data: LevelData): void {
        if (!data.objects?.props) return;

        data.objects.props.forEach(prop => {
            const sprite = scene.add.sprite(prop.x, prop.y, prop.texture, prop.frame);

            if (prop.scaleX !== undefined) sprite.scaleX = prop.scaleX;
            if (prop.scaleY !== undefined) sprite.scaleY = prop.scaleY;
            if (prop.rotation !== undefined) sprite.setRotation(prop.rotation);
            sprite.setDepth(prop.depth !== undefined ? prop.depth : DEPTHS.PROPS);
            if (prop.flipX !== undefined) sprite.setFlipX(prop.flipX);
            if (prop.flipY !== undefined) sprite.setFlipY(prop.flipY);


        });
    }

    /**
     * Spawns an NPC and sets up interaction
     */
    static spawnNPC(scene: BaseLevel, config: NPCConfig): void {
        const npc = new NPC(scene, config.x, config.y, config.texture, config.dialogue || '');

        // Depth logic: overrides > default (100)
        const depth = config.depth !== undefined ? config.depth : DEPTHS.NPCS;
        npc.setDepth(depth);


        if (config.scale) npc.setScale(config.scale);
        if (config['m-dialogue']) (npc as any).mDialogue = config['m-dialogue'];
        if (config.dialogueTree) npc.dialogueTree = config.dialogueTree;
        if (config.label) (npc as any).label = config.label;
        (npc as any).customKey = config.texture;

        // Interaction setup
        scene['registerInteractable'](npc);

        // Add physics collider with player
        if ((scene as any).player) {
            scene.physics.add.collider((scene as any).player, npc);
        }
    }

    /**
     * Creates exit zones with custom triggers
     */
    static createExitZones(
        scene: BaseLevel,
        data: LevelData,
        onExitCallback?: () => void
    ): void {
        if (!data.objects?.exitZones) return;

        data.objects.exitZones.forEach(exitConfig => {
            const exitZone = scene.add.zone(
                exitConfig.x,
                exitConfig.y,
                exitConfig.width,
                exitConfig.height
            );
            scene.physics.add.existing(exitZone, true);

            scene.physics.add.overlap((scene as any).player, exitZone, () => {
                if (!(scene as any).isCutscenePlaying) {
                    // Prevention: Level Transiton Looping
                    if (scene.time.now < ((scene as any).player as any).lastTransitionTime + 1500) return;

                    if (onExitCallback) {
                        onExitCallback();
                    }
                }
            });
        });
    }


    /**
     * Plays intro cutscene from data
     */
    static async playIntroCutscene(scene: BaseLevel, data: LevelData): Promise<void> {
        if (!data.cutscenes?.intro?.enabled) return;

        scene['startCutscene']();

        for (const step of data.cutscenes.intro.steps) {
            await LevelLoader.executeCutsceneStep(scene, step);
        }

        scene['endCutscene']();
    }

    /**
     * Executes a single cutscene step
     */
    public static async executeCutsceneStep(
        scene: BaseLevel,
        step: CutsceneStep
    ): Promise<void> {
        const player = (scene as any).player;

        switch (step.type) {
            case 'delay':
                return new Promise(resolve => {
                    scene.time.delayedCall(step.duration || 1000, () => resolve());
                });

            case 'action':
                if (step.action?.startsWith('setAngle:')) {
                    const angle = parseInt(step.action.split(':')[1]);
                    player.setAngle(angle);
                } else if (step.action === 'stand') {
                    player.setAngle(0);
                }
                return Promise.resolve();

            case 'dialogue':
                return scene['showDialogue'](player, step.text || '', step.duration || 3000, true, step['m-text']);

            case 'bossDialogue':
                // Try to find a boss or specific NPC
                // In Level 4, we might store it as 'aaduThoma' or 'boss'
                const bossTarget = (scene as any).aaduThoma || (scene as any).boss || (scene as any).ksrtcBus || player;
                return scene['showDialogue'](bossTarget, step.text || '', step.duration || 3000, true, step['m-text']);

            case 'cameraShake':
                scene.cameras.main.shake(step.duration || 500, step.intensity || 0.05);
                return new Promise(resolve => scene.time.delayedCall(step.duration || 500, () => resolve()));

            default:
                return Promise.resolve();
        }
    }

    /**
     * Creates invisible collision masks from rect and polygon data.
     * Polygons are rasterized at pixel precision and merged into row spans.
     */
    static createCollisionMasks(scene: BaseLevel, data: LevelData): void {
        if (!data.collisionRects && !data.collisionPolygons) return;

        const player = (scene as any).player;

        function createStaticRect(x: number, y: number, w: number, h: number) {
            const area = scene.add.rectangle(x, y, w, h);
            area.setOrigin(0);
            area.setVisible(false);
            scene.physics.add.existing(area, true);
            if (area.body) {
                (area.body as Phaser.Physics.Arcade.StaticBody).updateFromGameObject();
            }
            if (player) {
                scene.physics.add.collider(player, area);
            }
        }

        if (data.collisionRects) {
            data.collisionRects.forEach(rect => {
                createStaticRect(rect.x, rect.y, rect.width, rect.height);
            });
        }

        const isPixelInsidePolygonCell = (poly: Phaser.Geom.Polygon, x: number, y: number, cellSize: number): boolean => {
            const x2 = x + cellSize;
            const y2 = y + cellSize;
            const eps = 0.0001;

            // Any cell corner inside polygon means the cell must block.
            if (
                Phaser.Geom.Polygon.Contains(poly, x + eps, y + eps) ||
                Phaser.Geom.Polygon.Contains(poly, x2 - eps, y + eps) ||
                Phaser.Geom.Polygon.Contains(poly, x + eps, y2 - eps) ||
                Phaser.Geom.Polygon.Contains(poly, x2 - eps, y2 - eps)
            ) {
                return true;
            }

            // If a polygon vertex lands inside the cell, keep it blocked.
            for (const point of poly.points as Phaser.Types.Math.Vector2Like[]) {
                if (point.x >= x && point.x <= x2 && point.y >= y && point.y <= y2) {
                    return true;
                }
            }

            // Any polygon edge crossing the cell should also block this pixel.
            const rect = new Phaser.Geom.Rectangle(x, y, cellSize, cellSize);
            for (let i = 0; i < poly.points.length; i++) {
                const p1 = poly.points[i] as Phaser.Types.Math.Vector2Like;
                const p2 = poly.points[(i + 1) % poly.points.length] as Phaser.Types.Math.Vector2Like;
                const edge = new Phaser.Geom.Line(p1.x, p1.y, p2.x, p2.y);
                if (Phaser.Geom.Intersects.LineToRectangle(edge, rect)) {
                    return true;
                }
            }

            return false;
        };

        // Rasterize collision polygons at pixel precision and merge contiguous runs.
        if (data.collisionPolygons) {
            const polyRasterSize = 1;
            data.collisionPolygons.forEach(polyData => {
                if ((polyData as any).type === 'safe') return;
                const phaserPoly = new Phaser.Geom.Polygon(polyData.points as Phaser.Types.Math.Vector2Like[]);
                const bounds = Phaser.Geom.Polygon.GetAABB(phaserPoly);
                const startX = Math.floor(bounds.left);
                const startY = Math.floor(bounds.top);
                const endX = Math.ceil(bounds.right);
                const endY = Math.ceil(bounds.bottom);

                for (let cy = startY; cy < endY; cy += polyRasterSize) {
                    let runStart = -1;

                    for (let cx = startX; cx < endX; cx += polyRasterSize) {
                        const blocksCell = isPixelInsidePolygonCell(phaserPoly, cx, cy, polyRasterSize);

                        if (blocksCell) {
                            if (runStart === -1) runStart = cx;
                        } else if (runStart !== -1) {
                            createStaticRect(runStart, cy, cx - runStart, polyRasterSize);
                            runStart = -1;
                        }
                    }

                    if (runStart !== -1) {
                        createStaticRect(runStart, cy, endX - runStart, polyRasterSize);
                    }
                }
            });
        }
    }

    /**
     * Creates zones that slow down the player (Jackfruit Gum)
     */
    static createStickyZones(scene: BaseLevel, data: LevelData): Phaser.Physics.Arcade.Group {
        const group = scene.physics.add.group();
        if (!data.stickyZones) return group;

        const player = (scene as any).player;

        data.stickyZones.forEach(zone => {
            const area = scene.add.rectangle(zone.x, zone.y, zone.width, zone.height, 0xffff00, 0.3);
            area.setOrigin(0);
            scene.physics.add.existing(area, true);

            scene.physics.add.overlap(player, area, () => {
                if (player.applySlowdown) {
                    player.applySlowdown(0.5); // 50% speed
                }
            });
        });

        return group;
    }

    /**
     * Creates UI elements from data
     */
    static createUI(scene: BaseLevel, data: LevelData): Phaser.GameObjects.Text | undefined {
        if (!data.ui) return undefined;

        let objectiveText: Phaser.GameObjects.Text | undefined;

        // Objective text
        if (data.ui.objective) {
            objectiveText = scene.add.text(scene.scale.width - 20, 50, TranslationManager.translate(data.ui.objective, (data.ui as any)["m-objective"]), {
                fontSize: '24px',
                color: '#ffff00',
                stroke: '#000000',
                strokeThickness: 4,
                align: 'right'
            }).setOrigin(1, 0).setScrollFactor(0).setDepth(3000);
        }

        // Arrows
        if (data.ui.arrows) {
            data.ui.arrows.forEach(arrowConfig => {
                const arrow = scene.add.text(arrowConfig.x, arrowConfig.y, arrowConfig.direction, {
                    fontSize: '64px',
                    color: arrowConfig.color || '#00ff00',
                    stroke: '#000000',
                    strokeThickness: 4
                }).setOrigin(0.5).setDepth(100);

                if (arrowConfig.animate) {
                    const offset = arrowConfig.direction === '↓' || arrowConfig.direction === '↑' ? 32 : 32;
                    scene.tweens.add({
                        targets: arrow,
                        y: arrowConfig.direction === '↓' ? arrowConfig.y + offset : arrowConfig.y - offset,
                        x: arrowConfig.direction === '→' ? arrowConfig.x + offset : arrowConfig.x - offset,
                        duration: 500,
                        yoyo: true,
                        repeat: -1
                    });
                }
            });
        }

        return objectiveText;
    }


    /**
     * Clears blocking objects and updates UI when an exit path opens
     */
    static openExitPath(
        scene: BaseLevel,
        data: LevelData,
        params: {
            objectiveText?: Phaser.GameObjects.Text,
            successMessage?: string,
            disableWorldCollision?: 'up' | 'down' | 'left' | 'right',
            tilemapLayer?: Phaser.Tilemaps.TilemapLayer
        } = {}
    ): void {
        const { exitZones } = data.objects || {};
        if (!exitZones) return;

        // 1. Clear overlapping sprites/props
        const zoneRects = exitZones.map(config => {
            return new Phaser.Geom.Rectangle(
                config.x - config.width / 2,
                config.y - config.height / 2,
                config.width,
                config.height
            );
        });

        const toDestroy: any[] = [];
        scene.children.each((child: any) => {
            if (!child || child === (scene as any).player) return;
            if (child.type !== 'Sprite' && child.type !== 'Image' && child.type !== 'Container') return;

            for (const zone of zoneRects) {
                const detectionRect = Phaser.Geom.Rectangle.Clone(zone);
                Phaser.Geom.Rectangle.Inflate(detectionRect, -4, -4);
                if (detectionRect.contains(child.x, child.y)) {
                    toDestroy.push(child);
                    break;
                }
            }
        });
        toDestroy.forEach(c => c.destroy());

        // 2. Clear tiles from ALL layers in the scene
        if ((scene as any).map) {
            (scene as any).map.layers.forEach((layer: any) => {
                if (layer.tilemapLayer) {
                    zoneRects.forEach(zone => {
                        const tiles = layer.tilemapLayer.getTilesWithinWorldXY(zone.x, zone.y, zone.width, zone.height);
                        tiles.forEach((tile: any) => {
                            if (tile.index !== -1) {
                                layer.tilemapLayer.removeTileAt(tile.x, tile.y);
                            }
                        });
                    });
                }
            });
        }

        // 3. Disable world collision if requested
        if (params.disableWorldCollision) {
            (scene.physics.world.checkCollision as any)[params.disableWorldCollision] = false;
        }

        // 4. Update objective UI
        if (params.objectiveText && typeof (params.objectiveText as any).setText === 'function') {
            params.objectiveText.setText(TranslationManager.translate(params.successMessage || 'OBJECTIVE: PATH OPEN!'));
            params.objectiveText.setColor('#00ff00');
        }

        // 5. Force reset cutscene state to ensure transition isn't blocked
        (scene as any).isCutscenePlaying = false;

        // 6. Sound feedback
        scene.sound.play(AUDIO_KEYS.LEVEL_WON, { volume: 0.5 });
    }

    /**
     * Starts background music
     */
    static playAudio(scene: BaseLevel, data: LevelData): void {
        if (!data.audio?.bgm) return;

        const key = data.audio.bgm;
        if (scene.cache.audio.exists(key)) {
            scene.sound.stopAll();
            scene.sound.play(key, {
                loop: true,
                volume: data.audio.volume || 0.3
            });
        } else {
            console.warn(`Audio key "${key}" not found in cache. Skipping BGM.`);
        }
    }
}
