import SaveManager from '../managers/SaveManager';
import BaseLevel from './BaseLevel';
import Phaser from 'phaser';
import LevelLoader from '../utils/LevelLoader';
import { LEVEL2_DATA } from '../config/Level2Data';
import { SPRITE_KEYS } from '../config';
import ResourceManager from '../managers/ResourceManager';
import SarojKumar from '../entities/enemies/SarojKumar';
import PachalamBhasi from '../entities/enemies/PachalamBhasi';

export default class Level2 extends BaseLevel {
    private hasShownIntro: boolean = false;
    private saroj!: SarojKumar;
    private bhasi!: PachalamBhasi;
    private driver!: Phaser.Physics.Arcade.Sprite;
    private helicopter!: Phaser.Physics.Arcade.Sprite;
    private combatGroup!: Phaser.Physics.Arcade.Group;
    private isBossActive: boolean = false;

    constructor() {
        super('Level2', 'Level 2: The Blockade');
    }

    preload() {
        super.preload();
        LevelLoader.preloadCustomAssets(this, this.customData || LEVEL2_DATA);
    }

    create() {
        super.create();
        const data = this.customData || LEVEL2_DATA;

        // Audio
        LevelLoader.playAudio(this, data);

        // Player
        this.player = this.createPlayer(data.playerSpawn.x, data.playerSpawn.y, data.playerSpawn.texture);

        // World & camera bounds + collision masks
        LevelLoader.setupBounds(this, data);

        if (SaveManager.isLevelCompleted('Level2')) {
            this.hasShownIntro = true;
        } else {
            this.setupScene();
        }

        // Film Set Atmosphere (Bloom/Bright Lights)
        const worldW = data.map.width * data.map.tileWidth * data.map.tileScale;
        const worldH = data.map.height * data.map.tileHeight * data.map.tileScale;
        this.add.rectangle(0, 0, worldW, worldH, 0xffffff, 0.1)
            .setOrigin(0).setDepth(100).setScrollFactor(1).setBlendMode(Phaser.BlendModes.ADD);

        // Background image
        const bgKey = 'level_bg_texture_Level2';
        if (this.textures.exists(bgKey)) {
            this.add.image(0, 0, bgKey).setOrigin(0).setDepth(-20);
        }

        // Exit Zones
        LevelLoader.createExitZones(this, data, () => this.completeLevel());
    }

    private setupScene() {
        const data = this.customData || LEVEL2_DATA;

        // 1. Helicopter (Heavy Crate Logic)
        if (data.objects?.crates?.[0]) {
            const hData = data.objects.crates[0];
            this.helicopter = this.physics.add.sprite(hData.x, hData.y, SPRITE_KEYS.HELICOPTER_PROP);
            this.helicopter.setScale(1.0); // Adjusted scale for new prop
            this.helicopter.setTint(0xffffff); // Clear grey metallic tint

            // Physics
            this.helicopter.setDamping(true);
            this.helicopter.setDrag(0.2); // Reduced drag for easier movement
            this.helicopter.setMass(100); // Lower mass so telekinesis can move it easily
            this.helicopter.setCollideWorldBounds(true);
            this.helicopter.setData('health', 50);

            // Register for Telekinesis
            const heliGroup = this.physics.add.group();
            heliGroup.add(this.helicopter);
            if (this.player) this.player.setTelekinesisTargets(heliGroup);

            if (this.player) this.physics.add.collider(this.player, this.helicopter);

            // Allow throwing helicopter into enemies
            this.physics.add.collider(this.helicopter, this.combatGroup, (obj1, obj2) => {
                if (!this.helicopter.body) return;
                const vel = this.helicopter.body.velocity.length();
                if (vel > 200) {
                    // Damage enemy
                    const enemy = (obj1 === this.helicopter ? obj2 : obj1) as any;
                    if (enemy.takeDamage) enemy.takeDamage(10); // Heavy damage
                }
            });
        }

        // 2. Boss & Minion
        this.combatGroup = this.physics.add.group();
        this.player.setCombatTargets(this.combatGroup);

        if (!data.objects) return;

        const sarojData = data.objects.npcs?.[1]; // Index 1 is Saroj
        const bhasiData = data.objects.npcs?.[2]; // Index 2 is Bhasi
        const driverData = data.objects.npcs?.[0]; // Index 0 is Driver

        if (sarojData) {
            this.saroj = new SarojKumar(this, sarojData.x, sarojData.y, this.player, SPRITE_KEYS.SAROJ_KUMAR);
            this.saroj.on('dead', () => this.handleBossDefeat());
            this.combatGroup.add(this.saroj);
            this.add.text(this.saroj.x, this.saroj.y - 70, "Saroj Kumar", { fontSize: '16px', color: '#ffd700', backgroundColor: '#000' }).setOrigin(0.5);
        }

        if (bhasiData) {
            this.bhasi = new PachalamBhasi(this, bhasiData.x, bhasiData.y, this.player, SPRITE_KEYS.PACHALAM_BHASI);
            this.combatGroup.add(this.bhasi);
            this.add.text(this.bhasi.x, this.bhasi.y - 60, "Pachalam Bhasi", { fontSize: '14px', color: '#ffffff', backgroundColor: '#000' }).setOrigin(0.5);
        }

        if (driverData) {
            this.driver = this.physics.add.sprite(driverData.x, driverData.y, driverData.texture || SPRITE_KEYS.NEPHEW);
            this.driver.setImmovable(true);
            this.add.text(this.driver.x, this.driver.y - 60, "Driver", { fontSize: '12px', color: '#ffffff', backgroundColor: '#000' }).setOrigin(0.5);
        }



        // 3. Intro Cutscene
        if (!this.hasShownIntro && data.cutscenes?.intro) {
            this.hasShownIntro = true;
            this.startCutscene();

            const steps = data.cutscenes.intro.steps;
            let stepIndex = 0;

            const nextStep = async () => {
                try {
                    if (stepIndex >= steps.length) {
                        this.endCutscene();
                        this.startFight();
                        return;
                    }
                    const step = steps[stepIndex];
                    stepIndex++;

                    if (step.type === 'npcDialogue') {
                        // Driver is index 0, Saroj is index 1
                        let target: any = this.player;
                        if (step.npcIndex === 1) target = this.saroj;
                        if (step.npcIndex === 0) target = this.driver || this.player;

                        if (target && target.x !== undefined) {
                            if (step.npcIndex === 1) {
                                this.cameras.main.pan(target.x, target.y, 500, 'Power2');
                            } else {
                                this.cameras.main.pan(this.player.x, this.player.y, 500, 'Power2');
                            }
                            await this.showDialogue(target, step.text!, step.duration);
                        } else {
                            // Fallback if target is missing
                            await this.showDialogue(this.player, step.text!, step.duration);
                        }
                    } else if (step.type === 'dialogue') {
                        await this.showDialogue(this.player, step.text!, step.duration);
                    } else if (step.type === 'delay') {
                        await new Promise(r => this.time.delayedCall(step.duration!, r));
                    }
                    nextStep();
                } catch (err) {
                    console.error("Cutscene error:", err);
                    this.endCutscene();
                    this.startFight();
                }
            };
            nextStep();
        } else {
            this.startFight();
        }
    }

    private startFight() {
        this.isBossActive = true;
    }

    private handleBossDefeat() {
        this.isBossActive = false;
        // Kill Bhasi too if alive
        if (this.bhasi && this.bhasi.active) this.bhasi.takeDamage(100);

        this.time.delayedCall(1000, async () => {
            // Completion Cutscene
            const data = this.customData || LEVEL2_DATA;
            const steps = data.cutscenes?.completion?.steps || [];
            this.startCutscene();
            for (const step of steps) {
                const target = step.npcIndex === 1 ? this.saroj : this.player;
                if (step.type === 'npcDialogue' || step.type === 'dialogue') {
                    await this.showDialogue(target, step.text!, 2000);
                }
            }
            this.endCutscene();
            this.completeLevel();
        });
    }

    update(time: number, delta: number) {
        super.update(time, delta);
        if (this.isBossActive) {
            if (this.saroj && this.saroj.active) this.saroj.update();
            if (this.bhasi && this.bhasi.active) this.bhasi.update();
        }
    }

    private completeLevel() {
        if (this.isCutscenePlaying || SaveManager.isLevelCompleted('Level2')) return;
        ResourceManager.collectReelFragment('Level2');
        SaveManager.markLevelCompleted('Level2');
        SaveManager.unlockLevel('Level3');
        const nextScene = 'HubScene';
        SaveManager.save({
            currentLevel: nextScene,
            playerHealth: this.player.health,
            money: this.player.money,
            lastSaveTime: Date.now()
        });
        this.showVictory("BLOCKADE BROKEN!");
    }
}

